window.HISTORY_DATA = {"units":[{"id":1,"group":1,"title":"일제의 식민 통치 정책","summary":"1910년대 무단 통치, 1920년대 문화 정치, 1930년대 이후 민족 말살 통치를 목적과 수단으로 비교한다.","keywords":["헌병 경찰","조선 태형령","문화 정치","치안 유지법","황국 신민화"],"sections":[{"title":"1910년대: 무력에 의한 통제","body":"조선 총독부가 식민 통치의 중심이 되었으며 총독에게 강력한 권한이 집중되었다. 헌병이 일반 경찰 업무와 행정 업무에 관여하는 헌병 경찰 제도를 운영했다. 조선 태형령은 한국인에게만 적용된 차별적 법령이었다. 관리와 교원이 제복을 입고 칼을 차도록 하여 위압감을 조성했고 언론·출판·집회·결사의 자유를 억압했다."},{"title":"1920년대: 허용의 외형과 통제의 실상","body":"3·1 운동으로 무단 통치의 한계가 드러나자 일제는 문화 정치를 내세웠다. 헌병 경찰제를 보통 경찰제로 바꾸었지만 경찰 인원과 기관은 증가했다. 한국어 신문 발행을 일부 허용하면서 검열·삭제·정간으로 통제했다. 문관 총독 임명이 가능해졌으나 실제 문관 총독은 없었다. 1925년 치안 유지법은 사회주의 운동뿐 아니라 항일 운동의 탄압에도 활용되었다."},{"title":"1930년대 이후: 전쟁과 민족 말살","body":"침략 전쟁이 확대되자 한국인을 전쟁에 동원하기 위해 황국 신민화를 강요했다. 황국 신민 서사 암송, 신사 참배, 일본식 성명 사용, 일본어 사용 강요 등이 대표적이다. 1938년 국가 총동원법을 바탕으로 인력과 물자를 동원했다. 정책 이름은 바뀌었지만 식민 지배와 저항 억압이라는 목적은 계속되었다."}],"timeline":[{"year":"1912","event":"조선 태형령 제정"},{"year":"1919 이후","event":"문화 정치 표방"},{"year":"1925","event":"치안 유지법 제정"},{"year":"1938","event":"국가 총동원법 제정"}],"pitfalls":["보통 경찰제로의 전환이 경찰력 축소를 의미하지 않는다.","태형령은 1910년대, 황국 신민 서사는 1930년대 이후의 단서이다.","문화 정치 시기에도 언론의 자유가 전면 보장된 것은 아니다."],"sourcePages":[2,3,4,5,6],"blank":{"prompt":"1925년에 제정되어 사회주의 운동과 항일 운동 탄압에 이용된 법은 ____이다.","answer":"치안 유지법","explanation":"문화 정치의 외형과 달리 감시와 탄압이 계속되었음을 보여 주는 법이다."},"essay":{"prompt":"문화 정치가 기만적이었다는 평가의 근거를 경찰과 언론 정책을 포함하여 설명하시오.","model":"일제는 3·1 운동 이후 문화 정치를 내세웠으나 식민 통치를 유지하려 했다. 헌병 경찰제를 보통 경찰제로 바꾸면서도 경찰 인원과 기관을 늘렸고, 신문 발행을 허용하면서 검열과 기사 삭제를 실시했다.","criteria":["3·1 운동 이후 통치 방식 변화","보통 경찰제 전환과 경찰력 증가","신문 발행 허용과 검열 병행"]},"ox":{"statement":"문화 정치 시기에는 헌병 경찰제가 보통 경찰제로 바뀌었지만 경찰 인원과 기관은 오히려 늘어났다.","answer":true,"explanation":"통치 방식의 외형을 바꾸면서도 감시와 억압을 유지했다. 보통 경찰제 전환을 경찰력 축소로 해석하면 안 된다."}},{"id":2,"group":1,"title":"경제 구조의 변화와 경제생활 ①","summary":"토지 조사 사업과 산미 증식 계획을 명분·목적·농민 생활의 변화로 구분한다.","keywords":["토지 조사 사업","회사령","산미 증식 계획","수리 조합","소작농"],"sections":[{"title":"토지 조사 사업의 진행과 결과","body":"일제는 1910년 임시 토지 조사국을 설치하고 1912년 토지 조사령을 공포했다. 토지 소유자는 정해진 기간 안에 소유지의 정보를 신고해야 했다. 근대적 소유권 확립을 내세웠지만 지세 수입 확대와 식민 통치 재정 확보가 중요한 목적이었다. 소유권이 지주 중심으로 확립되고 농민의 관습적 경작권은 보호받지 못하면서 기한부 계약을 맺는 소작농이 늘었다."},{"title":"회사령과 산업 장악","body":"1910년 회사령은 회사 설립에 조선 총독의 허가를 받도록 하고 총독에게 해산 권한도 부여했다. 어업령·삼림령·조선 광업령 등으로 자원과 산업을 통제했다. 1920년 회사령이 폐지되어 신고제로 바뀌자 일본 자본의 진출이 확대되었다. 허가제의 폐지를 한국인 산업 보호 정책으로 해석하지 않도록 주의한다."},{"title":"산미 증식 계획의 모순","body":"1920년부터 일본의 쌀 부족을 해결하기 위해 한국의 쌀 생산량을 늘리는 계획이 추진되었다. 품종 개량, 토지 개량, 수리 시설 확충 등이 이루어졌으나 증산 비용은 농민에게 전가되었다. 늘어난 생산량보다 많은 쌀이 일본으로 반출되어 한국인의 식량 사정은 악화되었고 만주산 잡곡 수입이 증가했다. 생산 증가와 농민 생활 개선은 같은 뜻이 아니다."}],"timeline":[{"year":"1910","event":"임시 토지 조사국 설치·회사령 공포"},{"year":"1912","event":"토지 조사령 공포"},{"year":"1918","event":"토지 조사 사업 완료"},{"year":"1920","event":"회사령 폐지·산미 증식 계획 시작"}],"pitfalls":["토지 조사 사업의 명분은 소유권 정비, 식민 통치의 목적은 재정 확보와 지배 기반 강화이다.","산미 증식 계획은 한국인의 식량 부족 해결을 우선한 정책이 아니다.","회사령의 허가제와 폐지 이후 신고제를 구분한다."],"sourcePages":[7,8,9,10,11],"blank":{"prompt":"1920년부터 일본의 쌀 부족을 해결하기 위해 추진한 정책은 ____이다.","answer":"산미 증식 계획","explanation":"품종 개량과 수리 시설 확충으로 증산을 추진했지만 반출과 비용 부담으로 농민 생활은 악화되었다."},"essay":{"prompt":"산미 증식 계획으로 생산량이 늘었는데도 한국 농민의 생활이 어려워진 이유를 설명하시오.","model":"산미 증식 계획의 목적은 일본의 쌀 부족 해결이었다. 증산량보다 많은 쌀이 일본으로 반출되어 국내 식량 사정이 악화되었고, 수리 조합비 등 증산 비용도 농민이 부담하여 생활이 더욱 어려워졌다.","criteria":["일본의 쌀 부족 해결 목적","증산량을 넘는 쌀 반출","농민의 증산 비용 부담"]},"ox":{"statement":"산미 증식 계획으로 한국의 쌀 생산이 늘었으므로 한국 농민의 식량 사정도 전반적으로 개선되었다.","answer":false,"explanation":"증산량보다 많은 쌀이 일본으로 반출되었고 수리 조합비 등 증산 비용을 농민에게 전가하여 식량 사정과 농민 생활이 악화되었다."}},{"id":3,"group":1,"title":"경제 구조의 변화와 경제생활 ②","summary":"병참 기지화와 전시 수탈을 연결하고 이주 동포의 지역별 경험을 구분한다.","keywords":["병참 기지화","중화학 공업","공출","배급","중앙아시아 강제 이주"],"sections":[{"title":"전쟁을 위한 산업 재편","body":"만주 침략과 중일 전쟁 등으로 전선이 확대되면서 일제는 한국을 군수 물자 공급 기지로 만들었다. 지하자원과 수력 자원이 풍부한 북부에 중화학 공업을 집중 육성하고 군수 산업 중심으로 공업 구조를 바꾸었다. 공장 수와 생산량의 증가만으로 한국인의 생활이 개선되었다고 볼 수 없다. 산업의 목적과 소유 구조를 함께 살펴야 한다."},{"title":"인력과 물자의 강제 동원","body":"국가 총동원법 이후 전시 동원이 강화되었다. 미곡과 금속류 등을 공출하고 생필품 배급제를 실시했다. 노동력을 군수 공장과 광산 등에 동원했으며 지원병제와 징병제를 통해 전쟁에 투입했다. 일본군 ‘위안부’ 동원 등 심각한 인권 침해도 발생했다. 공출은 물자 수탈, 징용은 노동력 동원이라는 차이를 구별한다."},{"title":"국외 이주 동포의 생활","body":"생계난과 독립운동을 이유로 한인들이 만주·연해주·일본·미주로 이주했다. 만주에서는 간도 참변, 일본에서는 1923년 관동 대지진 때의 한인 학살을 겪었다. 연해주의 한인들은 신한촌을 형성했으나 1937년 소련에 의해 중앙아시아로 강제 이주되었다. 하와이 등 미주 동포들은 의연금과 독립 공채 구입으로 독립운동을 지원했다."}],"timeline":[{"year":"1923","event":"관동 대지진 당시 한인 학살"},{"year":"1931","event":"만주 사변"},{"year":"1937","event":"중일 전쟁·연해주 한인 중앙아시아 강제 이주"},{"year":"1938","event":"국가 총동원법 제정"}],"pitfalls":["1937년 중앙아시아 강제 이주의 주체는 소련이다.","군수 공업의 성장을 자립적 민족 경제 발전과 동일시하지 않는다.","공출·징용·징병은 각각 물자·노동력·병력 동원과 연결된다."],"sourcePages":[12,13,14,15,16],"blank":{"prompt":"일제가 한국을 침략 전쟁에 필요한 군수 물자의 공급 기지로 만든 정책을 ____ 정책이라고 한다.","answer":"병참 기지화","explanation":"북부 지역의 중화학 공업과 군수 산업 확대가 대표적인 모습이다."},"essay":{"prompt":"일제의 병참 기지화가 산업 구조와 주민의 경제생활에 미친 영향을 설명하시오.","model":"일제는 전쟁 물자 공급을 위해 북부 지역의 중화학 공업과 군수 산업을 육성했다. 이 과정에서 주민들은 노동력 동원에 시달렸으며, 미곡·금속류 공출과 생필품 배급으로 일상생활이 어려워졌다.","criteria":["전쟁 물자 공급 목적","북부 중화학·군수 산업 육성","공출·배급 또는 노동력 동원의 피해"]},"ox":{"statement":"1937년 연해주의 한인들을 중앙아시아로 강제 이주시킨 주체는 일본이었다.","answer":false,"explanation":"강제 이주의 주체는 소련이었다. 일본의 관동 대지진 당시 한인 학살 및 일제의 전시 동원과 구분해야 한다."}},{"id":4,"group":1,"title":"민족 운동의 전개와 분화 ①","summary":"비밀 결사의 국가 구상, 3·1 운동의 영향, 임시 정부의 조직과 활동을 연결한다.","keywords":["독립 의군부","대한 광복회","3·1 운동","대한민국 임시 정부","연통제"],"sections":[{"title":"비밀 결사가 꿈꾼 나라","body":"1912년 임병찬 등이 조직한 독립 의군부는 국권을 회복하고 군주정을 복구하려는 복벽주의를 내세웠다. 1915년 박상진 등이 조직한 대한 광복회는 군대식 조직으로 군자금을 모으고 만주 무관 학교 설립을 추진했으며 공화정 국가를 지향했다. 두 단체 모두 독립을 추구했지만 독립 이후 정치 체제에 대한 구상은 달랐다."},{"title":"3·1 운동의 배경과 전개","body":"무단 통치와 경제 수탈에 대한 저항이 쌓인 가운데 민족 자결주의의 확산, 도쿄 유학생의 2·8 독립 선언, 고종의 사망 등이 영향을 주었다. 1919년 3월 1일 독립 선언과 만세 시위가 시작되어 전국과 해외로 확산되었다. 학생·농민·상인 등 다양한 계층이 참여했다. 일제의 탄압에도 민족의 독립 의지를 드러냈고 임시 정부 수립과 다양한 독립운동을 촉진했다."},{"title":"민주 공화정 임시 정부","body":"1919년 상하이에 대한민국 임시 정부가 수립되었고 같은 해 국내외 임시 정부를 통합했다. 삼권 분립에 기초한 민주 공화정을 채택했다. 연통제는 비밀 행정망, 교통국은 통신망이었다. 독립 공채와 의연금으로 자금을 마련하고 구미 위원부를 통한 외교, 독립신문 발행, 한일 관계 사료집 편찬을 추진했다. 1923년 국민 대표 회의에서는 창조파와 개조파가 대립해 합의에 이르지 못했다."}],"timeline":[{"year":"1912","event":"독립 의군부 조직"},{"year":"1915","event":"대한 광복회 조직"},{"year":"1919","event":"3·1 운동·대한민국 임시 정부 수립과 통합"},{"year":"1923","event":"국민 대표 회의 개최"}],"pitfalls":["독립 의군부는 복벽주의, 대한 광복회는 공화정을 지향했다.","3·1 운동은 특정 지역이나 특정 종교만의 운동이 아니었다.","연통제는 행정망, 교통국은 통신망이다."],"sourcePages":[17,18,19,20,21],"blank":{"prompt":"대한민국 임시 정부가 국내외를 연결하기 위해 운영한 비밀 행정 조직은 ____이다.","answer":"연통제","explanation":"통신 기관인 교통국과 함께 임시 정부의 국내외 연락과 활동을 뒷받침했다."},"essay":{"prompt":"3·1 운동이 독립운동과 일제의 통치 방식에 미친 영향을 세 가지 서술하시오.","model":"3·1 운동은 독립운동을 이끌 통합 지도부의 필요성을 높여 대한민국 임시 정부 수립을 촉진했다. 무장 투쟁 등 다양한 민족 운동을 활성화했고, 일제는 무단 통치의 한계를 깨닫고 문화 정치를 표방했다.","criteria":["대한민국 임시 정부 수립 촉진","다양한 독립운동 활성화","문화 정치로의 전환"]},"ox":{"statement":"독립 의군부와 대한 광복회는 모두 국권 회복을 추구했지만 독립 이후 정치 체제에 대한 구상은 달랐다.","answer":true,"explanation":"독립 의군부는 군주정 회복을 지향하는 복벽주의를, 대한 광복회는 공화정 국가 건설을 지향했다."}},{"id":5,"group":1,"title":"민족 운동의 전개와 분화 ②","summary":"1920년대 무장 투쟁·실력 양성·민족 유일당 운동의 방법과 단서를 구별한다.","keywords":["봉오동","청산리","의열단","물산 장려 운동","신간회"],"sections":[{"title":"독립군의 승리와 시련","body":"1920년 홍범도의 대한 독립군 등이 봉오동에서 일본군을 격퇴했다. 같은 해 김좌진의 북로 군정서군과 홍범도의 대한 독립군 등이 청산리 일대에서 승리했다. 일본군은 간도 참변으로 한인 사회를 탄압했다. 이후 독립군은 이동과 재편 과정에서 자유시 참변 등 시련을 겪었고 만주에서 참의부·정의부·신민부를 조직했다."},{"title":"의열 활동과 실력 양성","body":"김원봉 등이 1919년 조직한 의열단은 식민 통치 기관 파괴와 주요 인물 처단을 추진했다. 신채호의 조선 혁명 선언을 활동 지침으로 삼았다. 한편 국내에서는 경제·교육의 힘을 길러 독립의 토대를 마련하려 했다. 물산 장려 운동은 토산품 애용, 민립 대학 설립 운동은 고등 교육 기관 설립 모금, 문자 보급과 브나로드 운동은 문맹 퇴치를 추진했다."},{"title":"민족 유일당 운동과 신간회","body":"비타협적 민족주의 세력과 사회주의 세력은 민족 협동 전선을 모색하여 1927년 신간회를 결성했다. 정치적·경제적 각성, 공고한 단결, 기회주의 배격을 내세우고 강연과 지회 활동, 농민·노동·학생 운동 지원에 나섰다. 광주 학생 항일 운동을 지원하려 민중 대회를 계획했다. 1931년 내부 노선 갈등과 일제의 탄압 속에서 해소되었다."}],"timeline":[{"year":"1919","event":"의열단 결성"},{"year":"1920","event":"봉오동 전투·청산리 대첩"},{"year":"1927","event":"신간회 창립"},{"year":"1931","event":"신간회 해소"}],"pitfalls":["봉오동과 청산리는 모두 1920년이며 봉오동이 먼저이다.","의열단의 김원봉과 한인 애국단의 김구를 구분한다.","신간회는 사회주의 세력만의 단체가 아니라 민족 협동 전선이다."],"sourcePages":[22,23,24,25,26],"blank":{"prompt":"1927년 비타협적 민족주의 세력과 사회주의 세력이 함께 결성한 대표적 민족 협동 전선 단체는 ____이다.","answer":"신간회","explanation":"신간회는 기회주의 배격과 단결을 내세우고 농민·노동·학생 운동을 지원했다."},"essay":{"prompt":"물산 장려 운동과 민립 대학 설립 운동의 공통 목표 및 각각의 방법을 설명하시오.","model":"두 운동은 민족의 실력을 길러 독립의 토대를 마련하려 했다. 물산 장려 운동은 토산품 애용으로 민족 기업과 자본을 보호하려 했고, 민립 대학 설립 운동은 모금을 통해 한국인의 고등 교육 기관을 세우려 했다.","criteria":["독립을 위한 실력 양성","토산품 애용과 민족 기업 보호","모금을 통한 고등 교육 기관 설립"]},"ox":{"statement":"신간회는 비타협적 민족주의 세력과 사회주의 세력이 연합한 단체로 광주 학생 항일 운동을 지원했다.","answer":true,"explanation":"1927년 결성된 신간회는 민족 협동 전선을 지향했다. 1929년 광주 학생 항일 운동을 지원하기 위해 민중 대회를 계획했다."}},{"id":6,"group":1,"title":"사회·문화의 변화와 대중운동 ①","summary":"농민·노동자·학생·여성·어린이·백정의 요구를 단체 및 사건과 연결한다.","keywords":["암태도 소작 쟁의","원산 총파업","광주 학생 항일 운동","근우회","조선 형평사"],"sections":[{"title":"도시화와 식민지 생활","body":"도시에는 교통·상업 시설이 들어서고 서양식 의식주와 대중문화가 확산되었다. 그러나 근대적 생활의 혜택은 지역과 계층에 따라 달랐고 한국인과 일본인의 생활 공간에도 차이가 나타났다. 농촌에서는 소작료와 세금 부담이 커져 농민이 도시나 국외로 이동했다. 새로운 생활문화와 식민지 차별을 함께 파악해야 한다."},{"title":"농민과 노동자의 권리 요구","body":"농민은 소작인 조합 등을 조직하여 소작료 인하와 소작권 보장을 요구했다. 1923~1924년 암태도 소작 쟁의가 대표적이다. 노동자는 낮은 임금과 장시간 노동, 민족 차별에 맞서 임금 인상과 노동 조건 개선을 요구했다. 1929년 원산 총파업은 지역 노동자들의 연대와 국내외 지원으로 확대된 노동 운동이었다."},{"title":"차별을 넘어서는 대중운동","body":"1926년 순종의 장례를 계기로 6·10 만세 운동이 일어났고, 1929년 광주 학생 항일 운동은 민족 차별에 대한 저항에서 전국적 운동으로 확대되었다. 방정환 등은 어린이를 독립된 인격체로 존중하는 소년 운동을 전개했다. 1927년 근우회는 여성의 권익과 계몽을 위해 활동했다. 1923년 진주에서 조직된 조선 형평사는 법적 신분제 폐지 이후에도 남아 있던 백정에 대한 사회적 차별 철폐를 주장했다."}],"timeline":[{"year":"1923","event":"조선 형평사 창립·암태도 소작 쟁의 시작"},{"year":"1926","event":"6·10 만세 운동"},{"year":"1927","event":"근우회 창립"},{"year":"1929","event":"원산 총파업·광주 학생 항일 운동"}],"pitfalls":["조선 형평사는 백정 차별 철폐, 근우회는 여성 운동과 연결한다.","6·10 만세 운동의 계기는 고종이 아닌 순종의 장례이다.","근대적 시설의 증가가 민족 차별의 해소를 뜻하지 않는다."],"sourcePages":[27,28,29,30,31],"blank":{"prompt":"1923년 진주에서 조직되어 백정에 대한 차별 철폐를 주장한 단체는 ____이다.","answer":"조선 형평사","explanation":"형평 운동은 신분제의 법적 폐지 이후에도 남아 있던 사회적 차별에 저항했다."},"essay":{"prompt":"일제 강점기 농민 운동과 노동 운동의 요구를 각각 설명하고 공통점을 쓰시오.","model":"농민은 소작료 인하와 소작권 보장을 요구했고 노동자는 임금 인상과 노동 조건 개선을 요구했다. 두 운동은 열악한 생활 조건과 식민지 경제의 차별에 맞서 생존권과 권익을 지키려 했다는 공통점이 있다.","criteria":["소작료 인하·소작권 보장","임금 인상·노동 조건 개선","생존권과 권익 보호라는 공통점"]},"ox":{"statement":"조선 형평사는 법적으로 신분제가 폐지된 뒤에도 남아 있던 백정에 대한 사회적 차별을 없애려 했다.","answer":true,"explanation":"1894년 신분제의 법적 폐지와 사회적 차별의 소멸은 다르다. 1923년 진주에서 조직된 조선 형평사는 차별 철폐와 권리 보장을 주장했다."}},{"id":7,"group":1,"title":"사회·문화의 변화와 대중운동 ②","summary":"언어·역사 연구를 통한 민족 문화 수호와 대중문화의 확산을 살펴본다.","keywords":["조선어 학회","한글 맞춤법 통일안","박은식","신채호","백남운"],"sections":[{"title":"우리말을 지키는 활동","body":"조선어 연구회는 가갸날을 정하고 잡지 한글을 발행했다. 이를 계승한 조선어 학회는 1933년 한글 맞춤법 통일안을 마련하고 우리말 큰사전 편찬을 추진했다. 말과 글의 정비는 민족의 문화와 정체성을 지키는 활동이었다. 일제는 1942년 조선어 학회 사건으로 회원들을 탄압했으며 사전은 해방 이후 간행되었다."},{"title":"식민 사관에 맞선 한국사 연구","body":"박은식은 국혼을 강조하며 한국통사와 한국독립운동지혈사를 썼다. 신채호는 민족의 주체성과 고대사를 중시하며 조선사연구초와 조선상고사를 남겼다. 백남운은 사회 경제 사학의 관점에서 한국사도 세계사의 보편적 발전 법칙에 따라 전개되었다고 주장하여 정체성론을 비판했다. 민족주의 사학과 사회 경제 사학은 방법이 달라도 식민 사관을 비판했다는 공통점이 있다."},{"title":"대중문화와 저항 문학","body":"신문·잡지·라디오와 극장 문화가 확산되고 연극·영화·대중가요가 인기를 얻었다. 토월회는 근대 연극 활동을 전개했으며 나운규의 영화 아리랑은 민족의 현실과 정서를 담았다. 이육사와 윤동주 등은 문학을 통해 식민지 현실에 대한 저항과 성찰을 표현했다. 대중문화의 확산 속에서도 일제의 검열과 통제가 지속되었다."}],"timeline":[{"year":"1926","event":"가갸날 제정·영화 아리랑 발표"},{"year":"1931","event":"조선어 학회로 개편"},{"year":"1933","event":"한글 맞춤법 통일안 제정"},{"year":"1942","event":"조선어 학회 사건"}],"pitfalls":["박은식의 국혼과 백남운의 보편적 발전 법칙을 구별한다.","조선어 학회는 일제 강점기에 큰사전 편찬을 완료·출판한 것이 아니다.","한국통사는 박은식, 조선상고사는 신채호의 저술이다."],"sourcePages":[32,33,34,35,36],"blank":{"prompt":"한국사도 세계사의 보편적 발전 법칙에 따라 발전했다고 주장한 사회 경제 사학자는 ____이다.","answer":"백남운","explanation":"백남운은 조선사회경제사 등을 통해 식민 사관의 정체성론을 비판했다."},"essay":{"prompt":"조선어 학회의 두 가지 활동과 그 역사적 의미를 설명하시오.","model":"조선어 학회는 한글 맞춤법 통일안을 제정하고 우리말 큰사전 편찬을 추진했다. 일제의 민족 말살 정책에 맞서 우리말과 글을 정비하고 민족의 문화와 정체성을 지키려는 활동이었다.","criteria":["한글 맞춤법 통일안 제정","우리말 큰사전 편찬 추진","민족 문화와 정체성 수호"]},"ox":{"statement":"백남운은 한국사가 세계사의 보편적 발전 법칙에서 벗어나 정체되어 있었다고 주장했다.","answer":false,"explanation":"백남운은 한국사도 세계사의 보편적 발전 법칙에 따라 발전했다고 보았다. 이는 식민 사관의 정체성론을 반박한 것이다."}},{"id":8,"group":1,"title":"독립 국가 건설 노력 ①","summary":"1930년대 한중 연합 작전과 의열 활동, 조선 의용대의 분화를 정리한다.","keywords":["한국 독립군","조선 혁명군","한인 애국단","윤봉길","조선 의용대"],"sections":[{"title":"만주의 한중 연합 작전","body":"일제의 만주 침략 이후 한국과 중국의 항일 세력이 연합했다. 북만주에서는 지청천의 한국 독립군이 중국 호로군과 협력하여 쌍성보·사도하자·대전자령 등에서 싸웠다. 남만주에서는 양세봉의 조선 혁명군이 중국 의용군과 영릉가·흥경성 전투 등을 전개했다. 사료 속 지휘관·지역·전투 장소를 묶어 기억하면 비슷한 이름의 부대를 구별할 수 있다."},{"title":"한인 애국단과 임시 정부의 활로","body":"김구는 침체된 독립운동에 활기를 주기 위해 1931년 한인 애국단을 조직했다. 이봉창은 1932년 도쿄에서 일왕을 공격하려 했고, 윤봉길은 같은 해 상하이 훙커우 공원에서 의거를 일으켰다. 윤봉길 의거는 중국 국민당 정부가 대한민국 임시 정부를 적극 지원하는 계기가 되었다. 의열단과 한인 애국단은 지도자와 창립 시기가 다르다."},{"title":"조선 의용대의 창설과 분화","body":"김원봉 등은 1938년 중국 한커우에서 조선 의용대를 창설했다. 중국 국민당 정부의 지원 아래 정보 수집·선전·포로 심문 등을 담당했다. 화북으로 이동한 세력은 조선 의용대 화북 지대를 거쳐 1942년 조선 의용군으로 개편되었다. 김원봉 등 잔류 세력은 한국광복군에 합류했다. 전체가 한 경로로 이동한 것으로 단순화하지 않는다."}],"timeline":[{"year":"1931","event":"한인 애국단 조직"},{"year":"1932","event":"이봉창·윤봉길 의거"},{"year":"1938","event":"조선 의용대 창설"},{"year":"1942","event":"의용대 일부 광복군 합류·화북 지대의 의용군 개편"}],"pitfalls":["한국 독립군은 지청천·북만주, 조선 혁명군은 양세봉·남만주이다.","한국 독립군과 1940년 창설된 한국광복군을 혼동하지 않는다.","조선 의용대의 일부는 광복군, 화북 세력은 조선 의용군으로 이어진다."],"sourcePages":[37,38,39,40,41],"blank":{"prompt":"김구가 1931년 조직하고 이봉창·윤봉길이 활동한 단체는 ____이다.","answer":"한인 애국단","explanation":"1919년 김원봉 등이 조직한 의열단과 지도자·창립 연도를 구별한다."},"essay":{"prompt":"한국 독립군과 조선 혁명군의 지휘관·활동 지역을 비교하고 공통된 투쟁 방식을 설명하시오.","model":"지청천의 한국 독립군은 북만주에서 활동했고 양세봉의 조선 혁명군은 남만주에서 활동했다. 두 부대는 중국의 항일 세력과 연합하여 일본군에 맞서는 한중 연합 작전을 전개했다.","criteria":["지청천·한국 독립군·북만주","양세봉·조선 혁명군·남만주","중국 항일 세력과 연합"]},"ox":{"statement":"조선 의용대는 분화 없이 전체가 한국광복군에 합류했다.","answer":false,"explanation":"김원봉 등 잔류 세력은 한국광복군에 합류했으나 화북 이동 세력은 조선 의용대 화북 지대를 거쳐 조선 의용군으로 개편되었다."}},{"id":9,"group":1,"title":"독립 국가 건설 노력 ②","summary":"한국광복군의 활동과 건국 구상, 국제 회담의 한국 독립 약속을 연결한다.","keywords":["한국광복군","삼균주의","건국 강령","카이로 선언","국내 진공 작전"],"sections":[{"title":"한국광복군과 연합 작전","body":"대한민국 임시 정부는 1940년 충칭에서 한국광복군을 창설하고 지청천을 총사령관으로 삼았다. 광복군은 인도·미얀마 전선에서 영국군과 함께 선전과 포로 심문 등의 활동을 전개했다. 미국 전략 정보국인 OSS와 국내 진공 작전을 준비하고 대원을 훈련했지만, 일본의 항복으로 실제 국내 진공은 이루어지지 못했다."},{"title":"해방 이후 국가를 준비하다","body":"임시 정부는 1941년 대한민국 건국 강령을 발표했다. 조소앙의 삼균주의를 반영하여 정치·경제·교육의 균등과 민주 공화국 건설을 지향했다. 중국 화북의 조선 독립 동맹도 민주 공화국 건설을 구상했다. 국내에서는 여운형 등이 1944년 조선 건국 동맹을 조직했다. 독립운동은 일제에 대한 저항뿐 아니라 새 국가의 제도와 사회 질서를 준비하는 과정이었다."},{"title":"국제 사회의 독립 약속","body":"1943년 미국·영국·중국의 카이로 선언은 적절한 시기에 한국을 독립시킬 것을 약속했다. 1945년 얄타 회담에서는 미국·영국·소련이 전후 문제를 논의하고 소련의 대일전 참전을 합의했다. 같은 해 포츠담 선언은 일본의 항복을 요구하고 카이로 선언의 이행을 확인했다. 회담의 참가국과 한국 독립 약속이 처음 나온 선언을 구분한다."}],"timeline":[{"year":"1940","event":"한국광복군 창설"},{"year":"1941","event":"대한민국 건국 강령 발표"},{"year":"1943","event":"카이로 선언"},{"year":"1944","event":"조선 건국 동맹 조직"},{"year":"1945","event":"포츠담 선언·광복"}],"pitfalls":["한국광복군의 국내 진공 작전은 준비했지만 실행되지 못했다.","카이로 회담에는 중국, 얄타 회담에는 소련이 참여했다.","삼균주의의 세 영역은 정치·경제·교육이다."],"sourcePages":[42,43,44,45,46],"blank":{"prompt":"1943년 미국·영국·중국이 한국의 독립을 약속한 선언은 ____이다.","answer":"카이로 선언","explanation":"1945년 포츠담 선언은 카이로 선언의 이행을 확인했다."},"essay":{"prompt":"한국광복군의 대외 협력 활동 두 가지와 국내 진공 작전이 실행되지 못한 이유를 설명하시오.","model":"한국광복군은 인도·미얀마 전선에서 영국군과 협력하여 선전과 포로 심문 등에 참여했다. 미국 OSS와는 국내 진공 작전을 준비했지만 작전 실행 전에 일본이 항복하여 국내 진공은 이루어지지 못했다.","criteria":["영국군과 인도·미얀마 전선 협력","미국 OSS와 국내 진공 준비","일본 항복으로 작전 미실행"]},"ox":{"statement":"한국광복군은 미국 OSS와 국내 진공 작전을 준비했지만 일본의 항복으로 실행하지 못했다.","answer":true,"explanation":"국내 진공 작전을 위한 훈련은 실시했지만 실행 이전에 일본이 항복했다. 준비와 실제 작전 수행을 구별한다."}},{"id":10,"group":2,"title":"냉전 체제와 대한민국 정부 수립 ①","summary":"광복 이후 분단과 신탁 통치 논쟁, 통일 정부 수립 노력을 시간순으로 살펴본다.","keywords":["38도선","건국 준비 위원회","모스크바 3국 외상 회의","좌우 합작","남북 협상"],"sections":[{"title":"광복과 새로운 질서","body":"1945년 8월 15일 일본의 항복으로 광복을 맞았다. 지속적인 독립운동과 연합국의 승리가 함께 배경이 되었다. 여운형 등은 조선 건국 동맹을 토대로 건국 준비 위원회를 조직하여 치안과 질서 유지에 힘썼다. 그러나 일본군의 무장 해제를 위해 미군과 소련군이 38도선을 경계로 진주하면서 남북에 서로 다른 정치 질서가 형성되었다."},{"title":"모스크바 회의와 신탁 통치 갈등","body":"1945년 12월 모스크바 3국 외상 회의는 한국의 민주주의 임시 정부 수립, 이를 협의할 미소 공동 위원회 설치, 최고 5년의 4개국 신탁 통치 협약 마련을 결정했다. 신탁 통치 문제를 둘러싸고 국내 정치 세력의 대립이 격화되었다. 회의 참가국인 미국·영국·소련과 신탁 통치 구상의 미국·영국·소련·중국을 구별한다."},{"title":"통일 정부 수립을 위한 시도","body":"미소 공동 위원회가 협의 대상 문제 등으로 난항을 겪자 여운형·김규식 등 중도 세력이 좌우 합작 위원회를 조직하고 7원칙을 발표했다. 그러나 좌우 대립과 여운형 피살 등으로 성과를 내기 어려웠다. 남한만의 선거가 추진되자 김구와 김규식은 1948년 평양의 남북 협상에 참여하여 단독 정부 수립 반대와 미소 양군 철수 등을 주장했다."}],"timeline":[{"year":"1945.8","event":"광복·건국 준비 위원회 조직"},{"year":"1945.12","event":"모스크바 3국 외상 회의"},{"year":"1946","event":"좌우 합작 위원회 결성·7원칙 발표"},{"year":"1948.4","event":"김구·김규식의 남북 협상 참여"}],"pitfalls":["모스크바 회의는 신탁 통치만이 아니라 임시 정부 수립도 결정했다.","좌우 합작의 여운형·김규식과 남북 협상의 김구·김규식을 구별한다.","38도선과 1953년에 정해진 군사 분계선은 다르다."],"sourcePages":[47,48,49,50,51],"blank":{"prompt":"1946년 여운형과 김규식 등이 중도 세력을 중심으로 추진한 운동은 ____ 운동이다.","answer":"좌우 합작","explanation":"좌우 합작 위원회는 통일 정부 수립을 위해 좌우 합작 7원칙을 발표했다."},"essay":{"prompt":"모스크바 3국 외상 회의에서 한국 문제에 관해 결정한 세 가지 내용을 서술하시오.","model":"한국에 민주주의 임시 정부를 수립하고 이를 협의하기 위해 미소 공동 위원회를 설치하기로 했다. 또한 미국·영국·소련·중국 4개국에 의한 최고 5년의 신탁 통치 협약을 마련하기로 했다.","criteria":["민주주의 임시 정부 수립","미소 공동 위원회 설치","4개국·최고 5년 신탁 통치 구상"]},"ox":{"statement":"모스크바 3국 외상 회의는 한국의 임시 정부 수립은 논의하지 않고 신탁 통치만 결정했다.","answer":false,"explanation":"민주주의 임시 정부 수립과 미소 공동 위원회 설치, 최고 5년의 4개국 신탁 통치 협약 마련을 함께 결정했다."}},{"id":11,"group":2,"title":"냉전 체제와 대한민국 정부 수립 ②","summary":"5·10 총선거에서 정부 수립까지의 순서와 친일 청산·농지 개혁의 성과와 한계를 학습한다.","keywords":["5·10 총선거","제헌 국회","제헌 헌법","반민특위","농지 개혁"],"sections":[{"title":"선거·헌법·정부의 순서","body":"1948년 5월 10일 유엔 한국 임시 위원단이 접근할 수 있는 남한에서 총선거가 실시되어 제헌 국회가 구성되었다. 다만 제주도의 일부 선거구에서는 선거가 실시되지 못했다. 국회는 7월 17일 헌법을 공포하여 민주 공화국과 삼권 분립, 대통령 중심제를 규정했다. 국회에서 이승만을 대통령, 이시영을 부통령으로 선출했고 8월 15일 대한민국 정부가 수립되었다. 첫 대통령은 국민의 직접 선거로 선출된 것이 아니다."},{"title":"친일파 청산의 시도와 좌절","body":"제헌 국회는 1948년 반민족 행위 처벌법을 제정하고 반민족 행위 특별 조사 위원회를 구성했다. 반민특위는 친일 혐의자를 조사·체포했으나 정부의 비협조, 경찰의 반민특위 습격, 활동 기간과 처벌 범위를 줄이는 법 개정으로 제약을 받았다. 결국 친일 청산을 충분히 수행하지 못했다. 법 제정 자체와 실제 집행 성과를 구별해서 평가한다."},{"title":"농지 개혁의 원칙과 의미","body":"1949년 농지 개혁법이 제정되고 1950년 본격적인 시행이 이루어졌다. 정부가 지주에게 값을 주고 농지를 사들여 농민에게 값을 받고 나누는 유상 매수·유상 분배 방식이었다. 가구당 소유 상한은 3정보였으며 자작농 중심의 농지 소유 확대에 기여했다. 북한의 무상 몰수·무상 분배와 구별하고 모든 토지가 아닌 농지에 대한 개혁이라는 점을 기억한다."}],"timeline":[{"year":"1948.5.10","event":"제헌 국회 구성을 위한 총선거"},{"year":"1948.7.17","event":"제헌 헌법 공포"},{"year":"1948.8.15","event":"대한민국 정부 수립"},{"year":"1948.9","event":"반민족 행위 처벌법 제정"},{"year":"1949","event":"농지 개혁법 제정"}],"pitfalls":["5·10 총선거는 대통령 선거가 아닌 제헌 국회 의원 선거이다.","대한민국의 농지 개혁은 유상 매수·유상 분배이다.","제헌 헌법은 6·25 전쟁 이전에 공포되었다."],"sourcePages":[52,53,54,55,56],"blank":{"prompt":"대한민국 농지 개혁은 유상 매수·____의 원칙으로 실시되었다.","answer":"유상 분배","explanation":"정부가 보상하고 농지를 매입한 뒤 농민에게 대가를 받고 분배하는 방식이다."},"essay":{"prompt":"반민특위의 목적과 활동이 좌절된 배경을 설명하시오.","model":"반민특위는 반민족 행위 처벌법에 따라 친일 행위자를 조사하고 처벌하여 친일 잔재를 청산하려 했다. 그러나 이승만 정부의 비협조와 경찰의 습격, 활동 기간을 축소한 법 개정 등으로 활동이 약화되어 청산을 충분히 수행하지 못했다.","criteria":["친일 행위 조사·처벌 목적","정부 비협조 또는 경찰 습격","법 개정·활동 축소로 청산 좌절"]},"ox":{"statement":"대한민국 농지 개혁의 유상 매수·유상 분배 원칙에서 정부는 지주에게 보상하고 농민에게 대가를 받고 농지를 분배했다.","answer":true,"explanation":"무상 몰수·무상 분배와 구별한다. 농지 개혁은 농가당 소유 상한 3정보를 두어 자작농 중심의 농지 소유 확대에 기여했다."}},{"id":12,"group":2,"title":"6·25 전쟁과 남북 분단의 고착화","summary":"전쟁의 전개, 정전의 의미, 전후 정치·경제 변화를 함께 정리한다.","keywords":["6·25 전쟁","인천 상륙 작전","정전 협정","발췌 개헌","삼백 산업"],"sections":[{"title":"전쟁의 주요 흐름","body":"1950년 6월 25일 북한군의 남침으로 전쟁이 시작되었다. 국군과 유엔군은 낙동강 방어선을 지킨 뒤 인천 상륙 작전으로 반격하고 서울을 수복했다. 북진 이후 중국군이 개입하여 다시 후퇴했고 1951년 1월 서울을 내주었다. 이후 전선이 교착된 가운데 정전 회담이 이어졌다. 남침·반격·중국군 개입·전선 교착의 순서를 파악한다."},{"title":"정전과 분단의 고착","body":"1953년 7월 27일 정전 협정이 체결되어 군사 분계선과 비무장 지대가 설정되었다. 정전은 전투를 멈추는 합의이며 평화 조약이나 통일을 의미하지 않는다. 막대한 인명 피해와 시설 파괴, 이산가족과 전쟁고아가 발생했고 남북의 적대감이 깊어졌다. 전쟁 중 국가 폭력과 민간인 학살의 피해도 컸다."},{"title":"장기 집권과 전후 복구","body":"이승만 정부는 1952년 발췌 개헌으로 대통령 직선제를 도입하고, 1954년 사사오입 개헌으로 당시 대통령의 중임 제한을 없앴다. 미국의 원조 물자를 가공하는 제분·제당·면방직의 삼백 산업이 발달했지만 농산물 가격 하락 등 농촌의 어려움도 나타났다. 피란과 도시 중심 복구로 인구가 도시에 집중되면서 주거·취업·교육 문제가 심화되었다."}],"timeline":[{"year":"1950.6.25","event":"북한군 남침으로 전쟁 발발"},{"year":"1950.9.15","event":"인천 상륙 작전"},{"year":"1952","event":"발췌 개헌"},{"year":"1953.7.27","event":"정전 협정 체결"},{"year":"1954","event":"사사오입 개헌"}],"pitfalls":["정전 협정은 전쟁의 평화적 종결을 확정한 평화 조약이 아니다.","발췌 개헌은 대통령 직선제, 사사오입 개헌은 초대 대통령의 중임 제한 철폐이다.","삼백 산업은 철강·조선·화학이 아니라 제분·제당·면방직이다."],"sourcePages":[57,58,59,60,61],"blank":{"prompt":"1954년 당시 대통령 이승만의 중임 제한을 없앤 헌법 개정을 ____ 개헌이라고 한다.","answer":"사사오입","explanation":"의결 정족수에 사사오입 논리를 적용해 통과를 주장한 개헌으로 장기 집권의 기반이 되었다."},"essay":{"prompt":"6·25 전쟁이 한국 사회에 남긴 영향을 인구·생활과 남북 관계 측면에서 설명하시오.","model":"전쟁으로 많은 사람이 사망하거나 피란했고 이산가족과 전쟁고아가 발생했다. 산업 시설과 주거지가 파괴되어 생활이 어려워졌으며, 남북 간 적대감이 커지고 군사적 대치가 지속되면서 분단이 고착되었다.","criteria":["인명 피해·피란·이산가족","시설 파괴와 생활 어려움","적대감 심화와 분단 고착"]},"ox":{"statement":"1952년 발췌 개헌의 핵심은 당시 대통령에게만 중임 제한을 적용하지 않는 것이었다.","answer":false,"explanation":"발췌 개헌은 대통령 직선제 도입과 연결된다. 당시 대통령 이승만의 중임 제한 철폐는 1954년 사사오입 개헌의 내용이다."}},{"id":13,"group":2,"title":"민주화를 위한 노력 ①","summary":"4·19 혁명에서 장면 정부, 군사 정변과 박정희 정부로 이어지는 변화를 비교한다.","keywords":["3·15 부정 선거","4·19 혁명","내각 책임제","5·16 군사 정변","3선 개헌"],"sections":[{"title":"4·19 혁명의 원인과 전개","body":"이승만 정부의 장기 집권과 부정부패에 대한 불만 속에서 1960년 3·15 부정 선거가 발생했다. 마산 시위와 김주열의 시신 발견으로 저항이 확대되었고, 4월 19일 학생과 시민의 시위에 경찰이 발포하여 많은 사상자가 발생했다. 교수단까지 시위에 참여하자 이승만은 4월 26일 하야를 발표했다. 국민의 힘으로 독재 정권을 무너뜨린 민주주의 혁명이었다."},{"title":"장면 정부와 5·16 군사 정변","body":"4·19 혁명 이후 개헌으로 내각 책임제와 양원제가 채택되었다. 대통령 윤보선과 국무총리 장면이 있는 제2공화국이 출범했고 행정의 중심은 국무총리였다. 시민의 다양한 요구가 분출하는 가운데 1961년 박정희를 중심으로 한 군인들이 5·16 군사 정변을 일으켜 정권을 장악했다. 민주적 선거와 군사력에 의한 권력 장악의 차이를 구분한다."},{"title":"박정희 정부의 대외 정책과 장기 집권","body":"박정희 정부는 경제 개발에 필요한 자금 확보 등을 위해 한일 국교 정상화를 추진했고, 반대 시위 속에서 1965년 한일 협정을 체결했다. 베트남 파병은 경제적 특수와 함께 고엽제 피해 등 후유증도 남겼다. 1969년에는 대통령의 세 차례 연속 취임을 허용하는 3선 개헌을 추진하여 장기 집권의 길을 열었다."}],"timeline":[{"year":"1960.4","event":"4·19 혁명·이승만 하야"},{"year":"1960.8","event":"장면 내각 출범"},{"year":"1961.5.16","event":"군사 정변"},{"year":"1965","event":"한일 협정 체결"},{"year":"1969","event":"3선 개헌"}],"pitfalls":["장면 정부의 대통령은 장면이 아닌 윤보선이며 장면은 국무총리이다.","3선 개헌(1969)과 유신 헌법(1972)을 구별한다.","4·19 혁명의 직접 계기는 3·15 부정 선거이다."],"sourcePages":[62,63,64,65,66],"blank":{"prompt":"4·19 혁명 이후 장면 정부는 대통령 중심제 대신 ____를 채택했다.","answer":"내각 책임제","explanation":"국무총리가 이끄는 내각이 행정의 중심을 이루었고 국회는 양원제로 구성되었다."},"essay":{"prompt":"4·19 혁명의 직접적인 계기, 결과, 역사적 의의를 서술하시오.","model":"3·15 부정 선거에 대한 저항이 직접적인 계기가 되어 학생과 시민의 시위가 전국으로 확대되었다. 이승만이 하야했고, 국민의 힘으로 독재 정권을 무너뜨려 민주주의 발전의 기반을 마련했다.","criteria":["3·15 부정 선거","이승만 하야","학생·시민이 독재 정권을 무너뜨림"]},"ox":{"statement":"4·19 혁명 이후 출범한 장면 정부에서는 국무총리가 이끄는 내각이 행정의 중심이었다.","answer":true,"explanation":"제2공화국은 내각 책임제를 채택했다. 윤보선은 대통령, 장면은 국무총리였으며 국회는 양원제로 구성되었다."}},{"id":14,"group":2,"title":"민주화를 위한 노력 ②","summary":"유신 체제의 권력 집중과 5·18, 6월 민주 항쟁의 요구·결과를 구별한다.","keywords":["유신 헌법","통일 주체 국민 회의","5·18 민주화 운동","6월 민주 항쟁","대통령 직선제"],"sections":[{"title":"유신 체제의 구조","body":"박정희는 1972년 비상계엄을 선포하고 국회를 해산한 뒤 유신 헌법을 추진했다. 대통령은 통일 주체 국민 회의에서 간접 선거로 선출되었고 임기 6년에 중임 제한이 없어 장기 집권이 가능했다. 대통령에게 긴급 조치권과 국회 해산권 등을 부여하여 권력을 집중했다. 유신 반대 운동은 탄압을 받았고 1979년 부마 민주 항쟁과 10·26 사건으로 체제가 흔들렸다."},{"title":"신군부와 5·18 민주화 운동","body":"12·12 군사 반란으로 군권을 장악한 신군부는 1980년 5월 비상계엄을 전국으로 확대했다. 광주의 학생과 시민들은 신군부 퇴진과 계엄 철회를 요구했다. 계엄군의 폭력과 발포에 맞서 시민군이 조직되었으나 무력 진압으로 많은 희생자가 발생했다. 5·18은 이후 민주화 운동의 중요한 토대가 되었다."},{"title":"1987년 6월 민주 항쟁","body":"박종철 고문치사 사건과 은폐 시도, 개헌 논의를 중단한 4·13 호헌 조치로 저항이 커졌다. 이한열이 최루탄에 맞은 사건과 6·10 국민 대회 이후 시위가 전국으로 확대되었다. 시민들은 호헌 철폐와 대통령 직선제를 요구했다. 6·29 선언으로 직선제 개헌 요구가 수용되었고 5년 단임의 대통령 직선제 헌법이 마련되었다."}],"timeline":[{"year":"1972","event":"유신 헌법 제정"},{"year":"1979","event":"부마 민주 항쟁·10·26 사건·12·12 군사 반란"},{"year":"1980.5","event":"5·18 민주화 운동"},{"year":"1987.6","event":"6월 민주 항쟁·6·29 선언"},{"year":"1987.10","event":"대통령 직선제 개헌"}],"pitfalls":["유신 헌법은 6년 임기 간선제, 1987년 개헌은 5년 단임 직선제이다.","5·18은 1980년, 6월 민주 항쟁은 1987년이다.","4·13 호헌 조치는 직선제 개헌 수용이 아니라 기존 헌법 유지 방침이다."],"sourcePages":[67,68,69,70,71],"blank":{"prompt":"1987년 6월 민주 항쟁의 핵심 정치적 요구는 호헌 철폐와 ____ 도입이었다.","answer":"대통령 직선제","explanation":"6·29 선언 이후 개헌을 통해 5년 단임 대통령 직선제가 도입되었다."},"essay":{"prompt":"6월 민주 항쟁의 배경과 시민들의 요구, 제도적 결과를 연결하여 설명하시오.","model":"박종철 고문치사 사건과 4·13 호헌 조치로 국민의 불만이 커졌다. 시민들은 호헌 철폐와 대통령 직선제를 요구했고, 6·29 선언을 거쳐 5년 단임의 대통령 직선제 개헌이 이루어졌다.","criteria":["고문치사 사건·호헌 조치","호헌 철폐·대통령 직선제 요구","5년 단임 직선제 개헌"]},"ox":{"statement":"6월 민주 항쟁의 결과 통일 주체 국민 회의가 대통령을 뽑는 6년 임기의 간선제가 도입되었다.","answer":false,"explanation":"이 내용은 1972년 유신 헌법에 해당한다. 1987년 6월 민주 항쟁 이후에는 5년 단임 대통령 직선제로 개헌했다."}},{"id":15,"group":2,"title":"산업화의 성과와 사회·환경 문제","summary":"경제 개발의 산업별 변화와 성장의 성과, 노동·농촌·환경 문제를 함께 살펴본다.","keywords":["경제 개발 5개년 계획","경공업","중화학 공업","3저 호황","전태일"],"sections":[{"title":"수출 주도 성장과 산업 구조 변화","body":"1962년 시작된 경제 개발 5개년 계획은 외국 자본과 노동력을 활용한 수출 주도 성장을 추진했다. 제1·2차 계획 시기에는 섬유·신발 등 노동 집약적 경공업이 중심이었고 경부 고속 도로 등 기반 시설이 확대되었다. 제3·4차 계획 시기에는 철강·조선·석유 화학 등 중화학 공업을 육성했으며 1977년 수출 100억 달러를 달성했다."},{"title":"국제 환경과 경제의 등락","body":"석유 파동은 에너지 수입 의존도가 높은 한국 경제에 부담을 주었다. 1970년대에는 중동 건설 진출로 외화를 벌었지만 제2차 석유 파동과 중화학 공업 중복 투자 등으로 어려움도 겪었다. 1980년대 중반에는 저유가·저금리·저달러의 3저 호황이 성장과 수출에 유리한 환경을 제공했다. 국내 정책과 국제 경제 조건을 함께 읽는다."},{"title":"성장 이면의 과제","body":"저임금과 장시간 노동 속에서 노동자의 권리가 충분히 보호되지 못했다. 1970년 전태일은 근로 기준법 준수를 요구하며 분신했고 노동 현실에 대한 관심이 높아졌다. 농촌의 소득 격차와 인구 유출에 대응하여 새마을 운동이 추진되었으나 정치적 동원이라는 비판도 있었다. 공업화·도시화는 주거난, 수질·대기 오염 등 사회·환경 문제를 낳았다."}],"timeline":[{"year":"1962","event":"제1차 경제 개발 5개년 계획 시작"},{"year":"1970","event":"경부 고속 도로 개통·전태일 분신·새마을 운동 시작"},{"year":"1973","event":"중화학 공업 육성 선언·제1차 석유 파동"},{"year":"1977","event":"수출 100억 달러 달성"},{"year":"1980년대 중반","event":"3저 호황"}],"pitfalls":["1960년대의 경공업 중심과 1970년대의 중화학 공업 육성을 구분한다.","3저는 저유가·저금리·저달러이며 저임금은 포함되지 않는다.","경제 성장의 성과와 노동·환경 문제를 함께 서술한다."],"sourcePages":[72,73,74,75,76],"blank":{"prompt":"1980년대 중반의 3저 호황은 저유가·저금리·____를 가리킨다.","answer":"저달러","explanation":"국제 경제의 유리한 조건이 한국의 수출과 경제 성장에 도움을 주었다."},"essay":{"prompt":"한국의 산업화가 가져온 성과 한 가지와 사회적 과제 두 가지를 설명하시오.","model":"수출 확대와 중화학 공업의 성장으로 산업 기반과 국민 경제 규모가 커졌다. 그러나 저임금·장시간 노동 등 노동 문제, 도시와 농촌의 격차 및 환경 오염 같은 문제를 해결해야 했다.","criteria":["수출 확대 또는 산업 기반 성장","저임금·장시간 노동 문제","도농 격차 또는 환경 오염"]},"ox":{"statement":"한국의 경제 개발은 1960년대 경공업 중심에서 1970년대 중화학 공업 육성으로 무게 중심이 옮겨 갔다.","answer":true,"explanation":"제1·2차 경제 개발 계획은 노동 집약적 경공업과 수출에, 제3·4차 계획은 철강·조선·석유 화학 등 중화학 공업 육성에 중점을 두었다."}},{"id":16,"group":2,"title":"문화 변동과 일상생활","summary":"도시화·교육 확대·대중문화의 변화를 국가 통제와 시민의 대응까지 연결한다.","keywords":["도시화","광주 대단지 사건","중학교 무시험","자유 언론","청년 문화"],"sections":[{"title":"도시와 농촌의 생활 변화","body":"산업화로 일자리를 찾아 농촌 인구가 도시로 이동하면서 주택과 교통 수요가 급증했다. 아파트와 새로운 생활 방식이 확산되었지만 도시 빈민과 철거민의 주거 문제도 커졌다. 1971년 광주 대단지 사건은 무리한 이주 정책과 열악한 생활 여건에 대한 주민의 저항이었다. 이는 경기도 광주 지역의 사건이며 1980년 광주의 민주화 운동과 다르다."},{"title":"교육 기회의 확대","body":"1950년대 초등 의무 교육이 확대되고 학교와 학생 수가 증가했다. 1969년 중학교 무시험 진학 제도가 도입되면서 중등 교육의 기회가 넓어졌다. 이후 고교 평준화 등 입시 경쟁을 완화하려는 정책도 추진되었다. 교육 확대는 사회 이동과 인력 양성에 기여했으나 입시 경쟁과 교육 격차 문제가 완전히 해소된 것은 아니었다."},{"title":"문화의 확산과 표현의 자유","body":"라디오·텔레비전의 보급으로 대중가요·영화·방송의 영향력이 커졌다. 1970년대 청바지·통기타 등 청년 문화가 확산되었지만 정부는 장발 단속, 금지곡 지정과 검열로 문화를 통제했다. 1974년 동아일보 기자들의 자유 언론 실천 선언과 백지 광고 사태는 언론 자유 문제를 보여 준다. 1980년대에는 프로 스포츠와 민중 문화 활동이 함께 성장했다."}],"timeline":[{"year":"1969","event":"중학교 무시험 진학 제도 도입"},{"year":"1971","event":"광주 대단지 사건"},{"year":"1974","event":"자유 언론 실천 선언"},{"year":"1982","event":"프로 야구 출범"}],"pitfalls":["광주 대단지 사건과 5·18 민주화 운동은 장소·시기·배경이 다르다.","대중문화의 확산 속에서도 국가의 검열과 통제가 존재했다.","교육 기회의 확대가 입시 경쟁의 소멸을 의미하지 않는다."],"sourcePages":[77,78,79,80,81],"blank":{"prompt":"1969년 도입되어 중학교 진학 단계의 입학시험을 없앤 제도는 ____ 제도이다.","answer":"중학교 무시험 진학","explanation":"중등 교육의 기회를 넓히고 과도한 입시 경쟁을 완화하기 위한 정책이었다."},"essay":{"prompt":"산업화에 따른 도시화가 일상생활에 가져온 변화와 문제점을 설명하시오.","model":"농촌 인구가 도시로 이동하고 아파트·대중교통 등 도시 생활이 확대되었다. 그러나 급속한 인구 집중으로 주택 부족과 교통 혼잡, 도시 빈민 문제가 발생했으며 농촌은 인구 감소와 고령화, 도농 격차를 겪었다.","criteria":["농촌에서 도시로 인구 이동","주택·교통·도시 빈민 문제","농촌 인구 감소 또는 도농 격차"]},"ox":{"statement":"1970년대 텔레비전과 청년 문화가 확산되었으므로 정부의 문화 검열과 언론 통제는 사라졌다.","answer":false,"explanation":"문화의 확산과 국가 통제는 병존했다. 금지곡·장발 단속·검열이 있었으며 1974년 자유 언론 실천 선언은 언론 통제에 맞선 움직임이었다."}},{"id":17,"group":3,"title":"6월 민주 항쟁 이후 민주화 과정","summary":"직선제 이후 제도 개혁과 평화적 정권 교체, 시민 사회의 성장으로 민주화의 범위를 넓혀 본다.","keywords":["여소야대","금융 실명제","지방 자치","평화적 정권 교체","시민 단체"],"sections":[{"title":"직선제 이후의 정치 변화","body":"1987년 개헌 이후 대통령 직선제가 시행되었다. 1988년 총선에서는 야당 의석이 여당보다 많은 여소야대 국회가 구성되어 전두환 정부의 비리와 5·18 진상 규명을 위한 청문회가 열렸다. 1990년에는 3당 합당으로 민주 자유당이 출범했다. 대통령 선출 방식의 변화 이후에도 권력 감시와 책임성 확보를 위한 과제가 남아 있었다."},{"title":"개혁과 정권 교체","body":"김영삼 정부는 1993년 금융 실명제를 실시하고 1995년 지방 자치 단체장까지 뽑는 지방 선거로 지방 자치를 전면 시행했다. 역사 바로 세우기를 추진하여 전두환·노태우의 책임을 물었다. 1997년 대선에서 김대중이 당선되어 선거를 통한 최초의 여야 간 평화적 정권 교체가 이루어졌다. 김대중 정부 시기 국가 인권 위원회가 설치되었다."},{"title":"시민 사회와 참여의 확대","body":"경제 정의 실천 시민 연합·참여 연대 등 시민 단체가 성장했고 노동·농민·환경·여성·인권 운동이 다양해졌다. 시민은 선거뿐 아니라 단체 활동, 토론, 집회와 정책 감시를 통해 공적 문제에 참여했다. 인터넷과 누리 소통망 서비스는 정보 공유와 참여를 확대했다. 민주화는 제도의 변화에 더해 시민의 지속적 참여와 기본권 보장을 통해 발전한다."}],"timeline":[{"year":"1988","event":"여소야대 국회와 청문회"},{"year":"1990","event":"3당 합당"},{"year":"1993","event":"금융 실명제 실시"},{"year":"1995","event":"지방 자치 전면 실시"},{"year":"1997","event":"대선으로 여야 간 평화적 정권 교체 결정"}],"pitfalls":["금융 실명제와 지방 자치 전면 실시는 김영삼 정부 시기의 정책이다.","1997년은 김대중의 당선, 1998년은 정부 출범 시점이다.","민주화의 진전을 대통령 직선제 하나로만 설명하지 않는다."],"sourcePages":[82,83,84,85,86],"blank":{"prompt":"1993년 김영삼 정부가 실제 명의로 금융 거래를 하도록 실시한 제도는 ____이다.","answer":"금융 실명제","explanation":"금융 거래의 투명성을 높이고 부정한 자금 거래를 줄이기 위한 제도였다."},"essay":{"prompt":"6월 민주 항쟁 이후 민주주의가 발전한 사례를 제도와 시민 참여 측면에서 설명하시오.","model":"대통령 직선제와 지방 자치 전면 실시로 국민의 정치적 선택과 참여가 확대되었다. 선거를 통한 여야 간 평화적 정권 교체가 이루어졌으며, 시민 단체와 인권·환경 운동이 성장하여 권력을 감시하고 사회 문제 해결에 참여했다.","criteria":["직선제 또는 지방 자치 확대","선거를 통한 평화적 정권 교체","시민 단체 성장과 권력 감시"]},"ox":{"statement":"지방 자치의 전면 실시와 시민 단체의 성장은 대통령 직선제 이후 정치 참여가 넓어졌음을 보여 준다.","answer":true,"explanation":"1995년 지방 자치가 전면 실시되었으며 시민은 선거뿐 아니라 단체 활동·집회·정책 감시 등으로 공적 의사 결정에 참여했다."}},{"id":18,"group":3,"title":"외환 위기의 극복과 사회·문화 변동","summary":"1997년 외환 위기의 발생과 극복, 세계화·정보화가 남긴 과제를 균형 있게 정리한다.","keywords":["외환 위기","IMF","구조 조정","금 모으기","정보화","다문화"],"sections":[{"title":"외환 위기의 발생","body":"기업의 과도한 차입과 부실, 금융 부문의 취약성에 국제 금융 불안이 겹쳤다. 외국 자금이 빠져나가고 외환 보유액이 부족해지면서 기업과 금융 기관이 위기에 빠졌다. 1997년 김영삼 정부는 국제 통화 기금인 IMF에 구제 금융을 요청했다. 위기를 단순히 국민의 소비 습관 하나로 설명하지 않고 기업·금융 구조와 국제 환경을 함께 파악한다."},{"title":"극복 노력과 사회적 비용","body":"김대중 정부는 기업·금융·공공 부문 등의 구조 조정과 외국 자본 유치를 추진했다. 시민들도 금 모으기 운동에 참여했고 2001년 IMF 지원금을 조기에 상환했다. 그러나 구조 조정 과정에서 실업이 증가하고 비정규직 확대와 소득 격차 등의 문제가 심화되었다. 위기의 극복은 경제 지표의 회복과 함께 고용·생활 안정의 과제도 남겼다."},{"title":"세계화·정보화와 새로운 사회","body":"자유 무역 협정 체결과 첨단 산업 발전으로 국제 경제와의 연결이 확대되었다. 정보 통신 기술은 일상생활과 소통 방식을 바꾸었고 한국 대중문화의 해외 확산에도 기여했다. 한편 대외 의존과 정보 격차, 계층 간 격차를 해결할 필요가 커졌다. 이주민 증가에 따른 다문화 사회의 변화와 저출산·고령화에 대응하는 사회적 제도도 중요한 과제가 되었다."}],"timeline":[{"year":"1997","event":"IMF 구제 금융 요청"},{"year":"1998","event":"금 모으기 운동·구조 조정 추진"},{"year":"2001","event":"IMF 지원금 조기 상환"},{"year":"2000년대 이후","event":"FTA 확대·정보화와 대중문화의 해외 확산"}],"pitfalls":["구제 금융 요청은 김영삼 정부, 극복 정책과 조기 상환은 김대중 정부와 연결한다.","금 모으기 운동만으로 외환 위기를 극복한 것은 아니다.","경제 회복과 실업·불평등 해소는 같은 의미가 아니다."],"sourcePages":[87,88,89,90,91],"blank":{"prompt":"1997년 한국 정부가 구제 금융을 요청한 국제기구의 약칭은 ____이다.","answer":"IMF","explanation":"국제 통화 기금으로, 한국은 구조 조정과 외자 유치 등을 추진한 뒤 2001년 지원금을 조기 상환했다."},"essay":{"prompt":"외환 위기를 극복하기 위한 노력 두 가지와 그 과정에서 나타난 사회 문제를 설명하시오.","model":"정부는 기업과 금융 기관의 구조 조정 및 외국 자본 유치를 추진했고 국민은 금 모으기 운동에 참여했다. 그러나 구조 조정 과정에서 실업과 고용 불안이 커지고 비정규직 및 소득 격차 문제가 심화되었다.","criteria":["구조 조정·외국 자본 유치","금 모으기 운동","실업·고용 불안 또는 소득 격차"]},"ox":{"statement":"1997년 IMF 구제 금융 요청은 김대중 정부가, 2001년 지원금 조기 상환은 김영삼 정부가 추진했다.","answer":false,"explanation":"정부의 순서가 바뀌었다. 구제 금융 요청은 김영삼 정부, 구조 조정 등 위기 극복과 조기 상환은 김대중 정부 시기에 이루어졌다."}},{"id":19,"group":3,"title":"한반도 분단 극복과 동아시아 평화 ①","summary":"북한 사회의 변화와 남북 합의의 이름·연도·정부·핵심 내용을 구분한다.","keywords":["7·4 남북 공동 성명","남북 기본 합의서","6·15 공동 선언","햇볕 정책","판문점 선언"],"sections":[{"title":"북한 사회의 변화","body":"북한에서는 김일성이 주체사상을 강조하며 권력을 집중했고 이후 김정일·김정은으로 권력이 세습되었다. 김정일 시기에는 군을 우선하는 선군 정치가 강조되었다. 경제난 속에서 합작 회사 관련 법과 제한적 개방 정책이 추진되었으며 일부 시장 경제 요소가 도입되기도 했다. 정치적 권력 집중과 경제적 대응을 구분해서 살핀다."},{"title":"대화의 원칙과 제도","body":"1972년 박정희 정부 시기 7·4 남북 공동 성명은 자주·평화·민족 대단결의 통일 원칙을 제시했고 남북 조절 위원회가 설치되었다. 1985년 전두환 정부 시기에는 이산가족 고향 방문과 예술 공연단 교환 방문이 이루어졌다. 1991년 노태우 정부 시기 남북한이 유엔에 동시에 가입하고 남북 기본 합의서를 채택하여 화해·불가침·교류 협력을 약속했다."},{"title":"정상 회담과 협력","body":"김대중 정부는 대북 화해 협력 정책을 추진했고 1998년 금강산 관광이 시작되었다. 2000년 최초의 남북 정상 회담에서 6·15 남북 공동 선언이 발표되어 통일 방안의 공통점과 인도적 문제 해결 등을 논의했다. 2007년 노무현 정부에서는 10·4 선언, 2018년 문재인 정부에서는 판문점 선언이 발표되었다. 합의의 발표와 지속적인 이행은 구분해 평가해야 한다."}],"timeline":[{"year":"1972","event":"7·4 남북 공동 성명"},{"year":"1991","event":"남북한 유엔 동시 가입·남북 기본 합의서"},{"year":"2000","event":"최초 남북 정상 회담·6·15 공동 선언"},{"year":"2007","event":"10·4 남북 공동 선언"},{"year":"2018","event":"판문점 선언"}],"pitfalls":["7·4 공동 성명은 1972년, 최초 남북 정상 회담은 2000년이다.","유엔 동시 가입과 남북 기본 합의서는 모두 1991년 노태우 정부 시기이다.","통일 3원칙은 자주·평화·민족 대단결이다."],"sourcePages":[92,93,94,95,96],"blank":{"prompt":"1972년 7·4 남북 공동 성명이 제시한 통일 원칙은 자주·평화·____이다.","answer":"민족 대단결","explanation":"사상과 이념, 제도의 차이를 넘어 민족의 단결을 도모한다는 원칙이다."},"essay":{"prompt":"7·4 남북 공동 성명과 남북 기본 합의서의 발표 시기 및 핵심 내용을 비교하시오.","model":"1972년 7·4 남북 공동 성명은 자주·평화·민족 대단결이라는 통일 3원칙을 제시했다. 1991년 남북 기본 합의서는 서로의 체제를 인정·존중하고 화해·불가침·교류 협력을 추진하기로 한 합의였다.","criteria":["1972년 공동 성명과 통일 3원칙","1991년 남북 기본 합의서","상호 체제 존중·화해·불가침·교류 협력"]},"ox":{"statement":"남북한 유엔 동시 가입과 남북 기본 합의서 채택은 모두 1991년 노태우 정부 시기에 이루어졌다.","answer":true,"explanation":"1972년 7·4 공동 성명 및 2000년 최초 남북 정상 회담과 구분한다. 남북 기본 합의서는 화해·불가침·교류 협력을 약속했다."}},{"id":20,"group":3,"title":"한반도 분단 극복과 동아시아 평화 ②","summary":"독도 관련 자료와 동아시아 역사 갈등을 읽고 근거와 대화를 통한 평화의 방법을 생각한다.","keywords":["독도","평화선","동북공정","역사 갈등","공동 역사 연구"],"sections":[{"title":"독도 관련 자료 읽기","body":"독도에 관한 주장은 역사 기록과 지리 자료, 정부의 행정 조치 등을 함께 검토하여 이해한다. 해방 후 연합국 최고 사령관 각서 제677호는 독도를 일본의 행정 관할에서 제외했고, 제1033호는 일본 선박 등의 독도 주변 접근을 제한했다. 1952년 대한민국 정부는 인접 해양에 대한 주권 선언인 평화선을 발표했다. 각서의 행정적 조치와 최종 영유권 결정의 성격을 동일시하지 않도록 문서의 범위를 읽어야 한다."},{"title":"역사 인식을 둘러싼 갈등","body":"일본의 일부 역사 교과서에서 침략과 식민 지배가 축소되거나 강제 동원의 피해가 충분히 다루어지지 않는 문제가 제기되었다. A급 전범이 합사된 야스쿠니 신사에 대한 정치인의 참배도 주변국과의 갈등 요인이다. 중국의 동북공정은 고구려·발해 등의 역사를 중국사의 일부로 서술하려는 문제로 한국과 역사 인식의 갈등을 일으켰다. 특정 정부 정책과 그 사회 전체를 구별한다."},{"title":"평화를 위한 구체적 실천","body":"갈등 해결에는 사료에 근거한 역사 연구와 피해자의 경험에 대한 존중이 필요하다. 공동 역사 연구와 교재 집필, 청소년 교류, 시민 사회의 협력은 서로 다른 인식을 확인하고 대화를 넓히는 방법이다. 1995년 무라야마 담화는 식민 지배와 침략에 대한 반성·사죄를 표명했다. 사실 확인과 인권 존중, 지속적 소통을 연결하여 평화 방안을 제시한다."}],"timeline":[{"year":"1946","event":"독도 관련 연합국 최고 사령관 각서"},{"year":"1952","event":"인접 해양에 대한 주권 선언"},{"year":"1995","event":"무라야마 담화"},{"year":"2002","event":"중국의 동북공정 시작"}],"pitfalls":["평화선 선언은 1952년 이승만 정부 시기이다.","동북공정은 중국의 역사 연구 사업과 관련하며 일본의 교과서 문제와 구별한다.","행정 관할을 정한 문서를 최종 영유권 결정 문서라고 단정하지 않는다."],"sourcePages":[97,98,99,100,101],"blank":{"prompt":"2002년부터 중국이 추진하여 고구려·발해 등의 역사 해석을 둘러싼 갈등을 일으킨 사업은 ____이다.","answer":"동북공정","explanation":"동북 지역의 역사를 연구한다는 명목 아래 한국 고대사의 귀속을 둘러싼 문제가 제기되었다."},"essay":{"prompt":"동아시아의 역사 갈등 사례 한 가지와 이를 평화적으로 해결하기 위한 방법 두 가지를 제안하시오.","model":"중국의 동북공정이나 일본 일부 교과서의 침략 역사 축소 등이 역사 갈등의 사례이다. 관련국 연구자들이 사료에 근거한 공동 연구와 교재 집필을 진행하고, 청소년·시민 교류를 통해 피해자의 경험과 서로의 인식을 이해하며 대화를 이어갈 수 있다.","criteria":["구체적인 역사 갈등 사례","사료에 근거한 공동 역사 연구","청소년·시민 교류와 피해자 존중"]},"ox":{"statement":"1952년 평화선 선언과 2002년 동북공정은 모두 한일 간 역사 교과서 공동 집필 사업이었다.","answer":false,"explanation":"평화선은 대한민국의 인접 해양에 대한 주권 선언이고, 동북공정은 중국이 추진한 역사 연구 사업이다. 공동 역사 교재 집필은 갈등 해결을 위한 별도의 협력 방식이다."}}],"questions":[{"id":"ebs-01-01","unit":1,"number":1,"type":"choice","title":"1. 다음 법령의 명칭으로 옳은 것은?","text":"1. 다음 법령의 명칭으로 옳은 것은?\n\n\n 제1조  3개월 이하의 징역 또는 구류에 처하여야\n\n     하는 자는 그 사정에 따라 태형에 처할 수\n\n      있다.\n\n 제11조 태형은 감옥 또는 즉결 관서에서 비밀리에\n\n      행한다.\n\n 제13조 본령은 조선인에 한하여 적용한다.\n\n\n① 대동법‌\n\n② ‌연분9등법\n\n③ ‌노비안검법\n\n④ ‌조선 태형령\n\n⑤ ‌국민 징용령","image":"assets/questions/ebs-01-01.webp","answer":"④","explanation":"해설\t| 태형에 처할 수 있다는 점, 조선인에게만 적용한다\n는 점 등을 통해 자료는 1910년대에 제정된 조선 태형령\n임을 알 수 있다.\n오답\t피하기\t|\t①, ② 조선 시대, ③ 고려 시대에 해당한다. \n⑤ 국민 징용령은 1930년대에 제정되었다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":2,"printedPage":1,"answerPage":4},{"id":"ebs-01-02","unit":1,"number":2,"type":"choice","title":"2. (가)에 들어갈 질문으로 가장 적절한 것은?","text":"2. (가)에 들어갈 질문으로 가장 적절한 것은?\n\n\n       3·1 운동 이후   한국인의 신문\n    변화된 일제의   발행을 허용한\n                                                 (가)\n     식민 통치 방식   목적은 무엇인\n     에 대해 궁금한   가요?\n     점이 있으면 질\n      문하세요.\n\n\n\n\n\n① 집강소는‌    어떤 역할을 했나요?\n\n② ‌무단 통치는 어떻게 전개되었나요?\n\n③ ‌이른바 문화 정치의 본질은 무엇인가요?\n\n④ ‌군국기무처의 개혁 법령에는 어떤 것이 있나요?\n\n⑤ ‌교사에게 제복을 착용하게 한 이유는 무엇인가요?","image":"assets/questions/ebs-01-02.webp","answer":"③","explanation":"해설\t|\t3·1 운동 이후 변화된 일제의 식민 통치 방식, 한\n국인의 신문 발행 허용 등의 내용을 통해 자료는 1920년\n대 일제의 식민 통치에 대한 것임을 알 수 있다. 일제는 \n3·1 운동을 계기로 식민 통치 방식을 무단 통치에서 이\n른바 문화 정치로 바꾸었다. 이른바 문화 정치는 한국인\n에게 기본권을 제한적으로 허용해 식민지 지배에 대한 반\n발을 무마하고, 친일파를 길러 민족 분열을 도모하는 것\n이었다.\n오답\t피하기\t|\t① 집강소, ④ 군국기무처는 조선 후기와 관\n련이 있다. ②, ⑤ 1910년대 무단 통치 시기에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":2,"printedPage":1,"answerPage":4},{"id":"ebs-01-03","unit":1,"number":3,"type":"choice","title":"3. 다음 자료를 활용한 탐구 주제로 가장 적절한 것은?","text":"3. 다음 자료를 활용한 탐구 주제로 가장 적절한 것은?\n\n\n 일제는 3·1 운동 이후 무단 통치의 한계를 깨닫고\n\n 식민 통치 방식을 바꾸었다. 헌병 경찰제는 보통\n\n 경찰제로 바꾸었지만, 경찰력을 강화하여 경찰 인\n\n 원과 기관, 비용 등이 3·1 운동 이전보다 크게 증\n\n 가하였다.\n\n\n① ‌의정부의 설치 계기\n\n② ‌호포제 실시의 배경\n\n③ ‌민족 말살 통치의 목적\n\n④ ‌기만적인 ‘문화 정치’의 실상\n\n⑤ ‌소학교의 명칭이 국민학교로 바뀐 시기","image":"assets/questions/ebs-01-03.webp","answer":"④","explanation":"해설\t|\t자료에서 3·1 운동 이후 무단 통치의 한계를 깨달\n았다는 점, 보통 경찰제를 실시하였으나 경찰력이 강화되\n었다는 점 등을 통해 기만적인 ‘문화 정치’의 실상을 탐구 \n주제로 하는 것이 가장 적절함을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":2,"printedPage":1,"answerPage":4},{"id":"ebs-01-04","unit":1,"number":4,"type":"choice","title":"4. 다음 훈시에 따라 시행된 정책으로 옳은 것은?","text":"4. 다음 훈시에 따라 시행된 정책으로 옳은 것은?\n\n\n    <사이토 마코토 총독의 시정 방침 훈시>\n\n 문화적 제도 혁신으로 조선인을 유도함으로써 조\n\n 선인의 행복·이익의 증진을 도모하며, 장차 문화\n\n 의 발달과 민력(民力)의 충실을 기하고, 정치상·\n\n 사회상의 대우에 있어서도 내지인(內地人, 일본인)\n\n 과 똑같이 취급을 해야 한다는 것이 궁극의 목적이\n\n 며 이것이 달성되기를 간절히 바란다.\n\n\n① ‌통감부가 설치되었다.\n\n② ‌보통 경찰제가 실시되었다.\n\n③ ‌미국인 외교 고문이 파견되었다.\n\n④ ‌보통 학교의 수업 연한이 4년으로 단축되었다.\n\n⑤ ‌근대적 토지 소유권을 증명하는 지계가 발급되었다.","image":"assets/questions/ebs-01-04.webp","answer":"②","explanation":"해설\t|\t자료는 3·1 운동(1919) 직후 조선 총독으로 파견된 \n사이토 마코토의 시정 방침 훈시 내용의 일부이다. 이 훈\n시에서 일제가 식민 통치 방식을 무단 통치에서 이른바 \n문화 정치로 전환하였음을 알 수 있다. 일제는 이른바 문\n화 정치를 시행하면서 헌병 경찰제를 보통 경찰제로 개편\n하였다.\n오답\t피하기\t|\t①, ③, ④, ⑤ 모두 3·1 운동 이전에 있었던 \n사실이다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":2,"printedPage":1,"answerPage":4},{"id":"ebs-01-05","unit":1,"number":5,"type":"choice","title":"5. 다음 설명에 해당하는 법령으로 옳은 것은?","text":"5. 다음 설명에 해당하는 법령으로 옳은 것은?\n\n\n 일본이 국가 체제 변혁 또는 사유 재산 제도를 부\n\n 정하는 자를 처벌할 목적으로 제정한 법률이다. 이\n\n 법률은 사회주의 세력은 물론 우리 민족의 독립운\n\n 동을 탄압하는 데도 이용되었다.\n\n\n① 방곡령‌\n\n② ‌치안 유지법\n\n③ ‌토지 조사령\n\n④ ‌경찰범 처벌 규칙\n\n⑤ ‌제1차 조선 교육령","image":"assets/questions/ebs-01-05.webp","answer":"②","explanation":"해설\t|\t국가 체제 변혁 또는 사유 재산 제도를 부정하는 자\n를 처벌할 목적에서 제정한 법률이라는 점 등을 통해 자\n료는 치안 유지법에 해당함을 알 수 있다. 일제는 1925년 \n치안 유지법을 제정하여 사회주의자는 물론 독립운동가\n를 탄압하였다.\n오답\t피하기\t|\t① 조선 시대에 해당한다. ③, ④, ⑤ 1910년\n대에 만들어졌으며, 제시된 자료와 관련이 없다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":3,"printedPage":2,"answerPage":4},{"id":"ebs-01-06","unit":1,"number":6,"type":"choice","title":"6. 다음 주장과 부합하는 일제의 정책으로 옳은 것은?","text":"6. 다음 주장과 부합하는 일제의 정책으로 옳은 것은?\n\n\n 지리적 중요성에서 봤을 때 일본과 조선의 일원화,\n\n 즉 우리 조선인이 일본인과 똑같이 동양 건설을 위\n\n 해 동등한 국민적 의무와 자격을 갖고 매진하도록\n\n 해야 한다.               - 윤치호, 1939 -\n\n\n① 원수부를‌    설치하였다.\n\n② ‌조선 태형령을 제정하였다.\n\n③ ‌교육입국 조서를 반포하였다.\n\n④ ‌헌병 경찰 제도를 실시하였다.\n\n⑤ ‌궁성 요배, 신사 참배를 강요하였다.","image":"assets/questions/ebs-01-06.webp","answer":"⑤","explanation":"해설\t|\t일본과 조선의 일원화를 주장하고, 조선인이 일본\n인과 똑같이 동양 건설을 위해 동등한 의무와 자격을 지\n녀야 한다고 한 점 등을 통해 자료는 1930년대 후반 황국 \n신민화 정책의 추진과 관련된 내용임을 알 수 있다. 궁성 \n요배와 신사 참배는 일제가 일왕에 대한 충성을 맹세하도\n록 하기 위해 강요하였다.\n오답\t피하기\t|\t①, ③ 국권 피탈 이전, ②, ④ 1910년대에 해\n당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":3,"printedPage":2,"answerPage":4},{"id":"ebs-01-07","unit":1,"number":7,"type":"choice","title":"7. 다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?","text":"7. 다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?\n\n\n 미국과 영국이 대동아에 대해서 침략, 착취를 자행\n\n 하여 대동아를 예속화하고 안정을 해치려고 하였\n\n 다. 이것이 대동아 전쟁의 원인이다. …… 대동아\n\n 를 미국과 영국의 속박에서 벗어나 공존공영, 자주\n\n 독립, 인종적 차별이 없는 지역으로 건설함으로써\n\n 세계 평화의 확립에 이바지하고자 한다.\n\n                        - 도조 히데키 -\n\n\n① ‌청일 전쟁의 전개 과정을 조사한다.\n\n② ‌일제의 침략 전쟁 확대 논리를 찾아본다.\n\n③ ‌미국이 추진한 뉴딜 정책의 내용을 알아본다.\n\n④ ‌윌슨이 민족 자결주의를 주창한 배경을 살펴본다.\n\n⑤ ‌유길준의 조선 중립화론이 갖는 특징을 분석한다.","image":"assets/questions/ebs-01-07.webp","answer":"②","explanation":"해설\t|\t대동아를 미국과 영국의 속박에서 벗어나게 한다는 \n내용 등을 통해 자료는 일제가 침략 전쟁을 확대하는 과\n정에서 제기한 대동아 공영권임을 알 수 있다. 일제는 침\n략 전쟁을 확대하면서 인력과 자원을 약탈하였다. 이러한 \n행위를 정당화하고자 대동아 공영권 논리를 제시하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":3,"printedPage":2,"answerPage":4},{"id":"ebs-01-08","unit":1,"number":8,"type":"choice","title":"8. 다음 정책이 실시된 시기에 있었던 사실로 옳은 것은?","text":"8. 다음 정책이 실시된 시기에 있었던 사실로 옳은 것은?\n\n\n  1. ‌일본식으로 성명을 고치지 않는 사람은 자제를\n\n  학교에 입학시킬 수 없다.\n\n  2. ‌일본인 교사는 아동을 이유 없이 구타해 아동이\n\n  부모에게 애원해 일본식 성명으로 고치게 한다.\n\n  4. ‌일본식으로 성명을 고치지 않은 사람에 대해서\n\n  는 행정 기관에서 행하는 모든 사무를 취급하지\n\n   않는다.\n\n\n① ‌대성 학교가 설립되었다.\n\n② ‌독립 협회가 창립되었다.\n\n③ ‌서경 천도 운동이 전개되었다.\n\n④ ‌여자 정신 근로령이 제정되었다.\n\n⑤ ‌광주 학생 항일 운동이 발생하였다.","image":"assets/questions/ebs-01-08.webp","answer":"④","explanation":"해설\t|\t자료는 일제가 1939년부터 실시한 일본식 성명 사\n용 강요, 즉 창씨개명 정책에 해당되는 내용을 담고 있다. \n일제는 황국 신민화 정책의 일환으로 창씨개명을 강요하\n였다. 또한 1944년 여자 정신 근로령을 제정하여 한국인 \n여성 노동력을 전쟁터에 강제 동원하였다.\n오답\t피하기\t|\t①, ②, ③, ⑤ 모두 1930년대 이전에 있었던 \n사실이다. ","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":3,"printedPage":2,"answerPage":4},{"id":"blank-01","unit":1,"number":9,"type":"blank","title":"1925년에 제정되어 사회주의 운동과 항일 운동 탄압에 이용된 법은 ____이다.","text":"1925년에 제정되어 사회주의 운동과 항일 운동 탄압에 이용된 법은 ____이다.","answer":"치안 유지법","explanation":"문화 정치의 외형과 달리 감시와 탄압이 계속되었음을 보여 주는 법이다.","criteria":[],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":2},{"id":"essay-01","unit":1,"number":10,"type":"essay","title":"문화 정치가 기만적이었다는 평가의 근거를 경찰과 언론 정책을 포함하여 설명하시오.","text":"문화 정치가 기만적이었다는 평가의 근거를 경찰과 언론 정책을 포함하여 설명하시오.","answer":"일제는 3·1 운동 이후 문화 정치를 내세웠으나 식민 통치를 유지하려 했다. 헌병 경찰제를 보통 경찰제로 바꾸면서도 경찰 인원과 기관을 늘렸고, 신문 발행을 허용하면서 검열과 기사 삭제를 실시했다.","explanation":"일제는 3·1 운동 이후 문화 정치를 내세웠으나 식민 통치를 유지하려 했다. 헌병 경찰제를 보통 경찰제로 바꾸면서도 경찰 인원과 기관을 늘렸고, 신문 발행을 허용하면서 검열과 기사 삭제를 실시했다.","criteria":["3·1 운동 이후 통치 방식 변화","보통 경찰제 전환과 경찰력 증가","신문 발행 허용과 검열 병행"],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":2},{"id":"ebs-02-01","unit":2,"number":1,"type":"choice","title":"1. 다음 법령의 명칭으로 옳은 것은?","text":"1. 다음 법령의 명칭으로 옳은 것은?\n\n\n 제1조 회사의 설립은 조선 총독의 허가를 받아야\n\n     한다.\n\n 제5조 회사가 본령 또는 본령에 의한 명령과 허가\n\n    의 조건에 위반하거나 공공질서 및 선량한\n\n    풍속에 반하는 행위를 한 경우에는 조선 총\n\n    독은 사업의 정지·금지, 지점의 폐쇄 또는\n\n    회사의 해산을 명령할 수 있다.\n\n\n① 회사령‌\n\n② ‌토지 조사령\n\n③ ‌조선 광업령\n\n④ ‌조선 태형령\n\n⑤ ‌국민 징용령","image":"assets/questions/ebs-02-01.webp","answer":"①","explanation":"해설\t| 회사의 설립은 조선 총독의 허가를 받아야 한다는 \n점, 조선 총독이 회사의 해산을 명령할 수 있다는 점 등을 \n통해 자료는 회사령임을 알 수 있다. 일제는 1910년 회사\n령을 제정하여 한국인 기업의 설립을 통제하였다.\n오답\t피하기\t|\t②, ③, ④ 1910년대, ⑤ 1930년대에 제정되\n었으며, 모두 제시된 자료와는 관련이 없다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":5,"printedPage":4,"answerPage":7},{"id":"ebs-02-02","unit":2,"number":2,"type":"choice","title":"2. 밑줄 친 ‘이 사업’의 영향으로 옳지 않은 것은?","text":"2. 밑줄 친 ‘이 사업’의 영향으로 옳지 않은 것은?\n\n\n 이 사업은 소유자들이 땅의 소재지, 면적 등을 기\n\n 재한 신고서를 정해진 기간 내에 직접 제출하면 토\n\n 지 조사국에서 토지 가격, 지형 등을 조사, 측량하\n\n 여 토지와 그 소유권자를 확정하는 방법으로 진행\n\n 되었다. 이 사업으로 미신고 토지와 소유권이 불분\n\n 명한 공유지, 황무지나 미개간지 등은 모두 국유지\n\n 로 편입되었다.\n\n\n① 조선‌  총독부 소유 토지가 늘어났다.\n\n② ‌조선 총독부의 지세 수입이 증가하였다.\n\n③ ‌관습적 경작권을 상실한 농민이 늘어났다.\n\n④ ‌자기 땅을 가진 자영농이 크게 증가하였다.\n\n⑤ ‌만주나 연해주로 이주하는 농민이 증가하였다.","image":"assets/questions/ebs-02-02.webp","answer":"④","explanation":"해설\t|\t자료에서 소유자가 토지 조사국에 신고한다는 점, \n미신고 토지와 소유권이 불분명한 공유지 등이 국유지로 \n편입되었다는 점 등을 통해 밑줄 친 ‘이 사업’이 토지 조사 \n사업임을 알 수 있다. 미신고 토지와 소유주가 불분명한 \n토지, 황무지나 미개간지 등이 국유지로 편입되면서 조\n선 총독부 소유 토지가 늘어났다. 이 사업으로 토지 대장\n에서 누락된 토지가 파악됨으로써 조선 총독부의 지세 수\n입이 증가하였다. 소작농의 관습적 권리를 인정하지 않아 \n많은 농민이 관습적 경작권을 상실하게 되었다. 이에 살\n기가 어려워진 많은 농민이 만주나 연해주 등지로 이주하\n였다.\n오답\t피하기\t|\t④ 토지 조사 사업은 토지의 소유권을 확인하\n는 것에 불과해 농민의 토지 소유 규모를 재조정하여 자\n영농을 확대하는 토지 개혁과는 관련이 없다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":5,"printedPage":4,"answerPage":7},{"id":"ebs-02-03","unit":2,"number":3,"type":"choice","title":"3. 다음 법령이 발표된 시기를 연표에서 옳게 고른 것은?","text":"3. 다음 법령이 발표된 시기를 연표에서 옳게 고른 것은?\n\n\n  1. ‌토지의 조사 및 측량은 이 명령에 따른다.\n\n  4. ‌토지의 소유자는 조선 총독이 정하는 기간 내에\n\n  그 주소, 성명 또는 명칭 및 소유지의 소재, 지\n\n   목, 자번호, 사방의 경계, 등급, 지적, 결수를 임\n\n  시 토지 조사 국장에게 신고하여야 한다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n  을사   국권     3·1   치안  중일 전쟁   8·15\n  늑약   피탈   운동   유지법   발발   광복\n                 제정\n\n① (가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-02-03.webp","answer":"②","explanation":"해설\t|\t자료에서 토지 소유자는 조선 총독이 정하는 기간 \n내에 신고해야 한다는 내용 등을 통해 법령이 1912년에 \n공포된 토지 조사령임을 알 수 있다. 국권 피탈은 1910년, \n3·1 운동은 1919년에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":5,"printedPage":4,"answerPage":7},{"id":"ebs-02-04","unit":2,"number":4,"type":"short","title":"4. 다음 법령의 명칭을 쓰시오.","text":"4. 다음 법령의 명칭을 쓰시오.\n\n\n 제1조 제국 신민 또는 제국 법령에 따라 성립한\n\n     법인이 아니면 광업권을 가질 수 없다.\n\n 제7조 ① 광업을 하고자 하는 자는 원서에 광구\n\n     도를 첨부하여 조선 총독에게 출원하여 허\n\n     가를 받아야 한다.\n\n 제10조 공익을 해하는 것으로 인정하는 때 또는\n\n     광업의 가치가 없다고 인정하는 때에는 광\n\n     업 출원을 허가하지 아니한다.\n\n\n                                      (                        )","image":"assets/questions/ebs-02-04.webp","answer":"조선\t광업령","explanation":"해설\t|\t자료에서 광업을 하고자 하는 자는 조선 총독의 허\n가를 받아야 한다는 점 등을 통해 법령이 1910년대에 제\n정된 조선 광업령임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":5,"printedPage":4,"answerPage":7},{"id":"ebs-02-05","unit":2,"number":5,"type":"choice","title":"5. 다음 그래프와 같은 변화를 가져 온 원인으로 가장 적절","text":"5. 다음 그래프와 같은 변화를 가져 온 원인으로 가장 적절\n한 것은?\n\n          (석)\n          0.8\n                  0.63    0.63   0.60\n          0.6                          0.53    0.54\n                                                        0.45\n          0.4\n\n\n           0.2\n\n\n          0\n              1920  1922  1924  1926  1928  1930(년)\n                            -「조선 미곡 요람」, 1936-\n\n            ▲한국인 1인당 쌀 소비량\n\n① 방곡령이‌    내려졌다.\n\n② ‌모내기법이 확대 보급되었다.\n\n③ ‌토지 조사 사업이 추진되었다.\n\n④ ‌상품 작물 재배가 확대되었다.\n\n⑤ ‌산미 증식 계획이 진행되었다.","image":"assets/questions/ebs-02-05.webp","answer":"⑤","explanation":"해설\t|\t자료는 1920년대 한국인의 1인당 쌀 소비량 변화를 \n나타낸 그래프이다. 1920년부터 1930년까지 한국인의 1\n인당 쌀 소비량은 감소하는 경향을 보이고 있다. 일제는 \n1920년부터 일본의 쌀 부족 문제를 해결하기 위해 산미 \n증식 계획을 추진하였다. 하지만 증산량보다 많은 쌀을 \n일본으로 반출해 갔기 때문에 한국에서는 쌀 부족 문제가 \n나타났다.\n오답\t피하기\t|\t①, ②, ④ 조선 시대, ③ 1910년대에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":6,"printedPage":5,"answerPage":7},{"id":"ebs-02-06","unit":2,"number":6,"type":"choice","title":"6. 다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?","text":"6. 다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?\n\n\n 수리 조합의 조합비는 지주가 부담하는데, 그 일부 혹\n\n 은 전부를 소작인에게 전가하기 위하여 소작료를 6~7\n\n 할로 올리는 풍습이 있다. …… 이는 수확량의 반을 소\n\n 작료로 내던 종래의 관습과 다를 뿐만 아니라 …… 소\n\n 작인의 수입이 종래의 절반보다 적은 이유이다.\n\n                      - 동아일보(1929) -\n\n\n① 회사령‌   제정 목적을 파악한다.\n\n② ‌산미 증식 계획의 영향을 알아본다.\n\n③ ‌황국 신민화 정책의 내용을 정리한다.\n\n④ ‌임시 토지 조사국의 역할을 찾아본다.\n\n⑤ ‌헌병 경찰 제도의 시행 방식을 조사한다.","image":"assets/questions/ebs-02-06.webp","answer":"②","explanation":"해설\t|\t자료에서 지주가 수리 조합비를 전가하기 위해 소\n작료를 올리고 있다는 내용 등을 통해 산미 증식 계획의 \n영향을 알아보는 것이 가장 적절한 탐구 활동임을 알 수 \n있다. \n오답\t피하기\t|\t① 회사령 제정은 1910년대, ③ 황국 신민화 \n정책은 1930년대, ④ 임시 토지 조사국은 1910년대, ⑤ 헌\n병 경찰 제도는 1910년대에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":6,"printedPage":5,"answerPage":7},{"id":"ebs-02-07","unit":2,"number":7,"type":"choice","title":"7. 다음 대화의 소재가 된 정책으로 옳은 것은?","text":"7. 다음 대화의 소재가 된 정책으로 옳은 것은?\n\n\n 1920년대 일본이 본국의        맞아. 한국에서 쌀을 확\n 식량 부족 문제를 해결하      보하여 해결하려고 하였\n 기 위해 한반도에서 실시          지. 증산량 이상의 쌀을\n 하였어.              일본으로 가져갔어.\n\n\n\n\n\n① ‌통공 정책\n\n② ‌화폐 정리 사업\n\n③ ‌토지 조사 사업\n\n④ ‌산미 증식 계획\n\n⑤ ‌병참 기지화 정책","image":"assets/questions/ebs-02-07.webp","answer":"④","explanation":"해설\t|\t자료에서 1920년대 일본이 본국의 식량 부족 문제\n를 해결하기 위해 한반도에서 실시하였다는 점, 증산량 \n이상의 쌀을 일본으로 가져갔다는 점 등을 통해 대화의 \n소재가 된 정책은 산미 증식 계획임을 알 수 있다.\n오답\t피하기\t|\t① 조선 후기, ② 대한 제국 시기, ③ 1910년\n대, ⑤ 1930년대 이후에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":6,"printedPage":5,"answerPage":7},{"id":"ebs-02-08","unit":2,"number":8,"type":"choice","title":"8. (가)에 들어갈 내용으로 적절하지 않은 것은?","text":"8. (가)에 들어갈 내용으로 적절하지 않은 것은?\n\n\n        ◯◯ ◯◯ 계획 실시\n\n    배경  일본의 공업화 진전에 따른 식량 부족\n\n    목적  한국에서 쌀을 확보하여 해결\n\n    내용                  (가)\n\n\n① ‌토지 개간\n\n② ‌품종 개량\n\n③ ‌모내기법 금지\n\n④ ‌수리 조합 조직\n\n⑤ ‌수리 시설 확충","image":"assets/questions/ebs-02-08.webp","answer":"③","explanation":"해설\t|\t일본의 공업화 진전에 따른 식량 부족이 배경이 되\n었다는 점, 한국에서 쌀을 확보하여 해결하는 것이 목적\n이었다는 점 등을 통해 자료는 산미 증식 계획에 대한 것\n임을 알 수 있다. 일제는 1920년대 이 계획을 실시하면서 \n토지 개간, 품종 개량, 수리 시설 확충과 이를 위한 수리 \n조합 조직 등을 추진하였다.\n오답\t피하기\t|\t③ 조선 전기에 해당한다. ","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":6,"printedPage":5,"answerPage":7},{"id":"blank-02","unit":2,"number":9,"type":"blank","title":"1920년부터 일본의 쌀 부족을 해결하기 위해 추진한 정책은 ____이다.","text":"1920년부터 일본의 쌀 부족을 해결하기 위해 추진한 정책은 ____이다.","answer":"산미 증식 계획","explanation":"품종 개량과 수리 시설 확충으로 증산을 추진했지만 반출과 비용 부담으로 농민 생활은 악화되었다.","criteria":[],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":7},{"id":"essay-02","unit":2,"number":10,"type":"essay","title":"산미 증식 계획으로 생산량이 늘었는데도 한국 농민의 생활이 어려워진 이유를 설명하시오.","text":"산미 증식 계획으로 생산량이 늘었는데도 한국 농민의 생활이 어려워진 이유를 설명하시오.","answer":"산미 증식 계획의 목적은 일본의 쌀 부족 해결이었다. 증산량보다 많은 쌀이 일본으로 반출되어 국내 식량 사정이 악화되었고, 수리 조합비 등 증산 비용도 농민이 부담하여 생활이 더욱 어려워졌다.","explanation":"산미 증식 계획의 목적은 일본의 쌀 부족 해결이었다. 증산량보다 많은 쌀이 일본으로 반출되어 국내 식량 사정이 악화되었고, 수리 조합비 등 증산 비용도 농민이 부담하여 생활이 더욱 어려워졌다.","criteria":["일본의 쌀 부족 해결 목적","증산량을 넘는 쌀 반출","농민의 증산 비용 부담"],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":7},{"id":"ebs-03-01","unit":3,"number":1,"type":"short","title":"1. 밑줄 친 ㉠에 해당하는 역사적 사실을 쓰시오.","text":"1. 밑줄 친 ㉠에 해당하는 역사적 사실을 쓰시오.\n\n\n 베르사유 체제하에서 세계 경제는 향상된 공업 생\n\n 산력을 소비가 따라가지 못하는 불균형이 갈수록\n\n 심화되었다. 이는 결국 1929년 미국을 시작으로 한\n\n 대공황으로 이어졌고, 그 영향은 동아시아에도 미\n\n 쳤다. 이에 일본은 ㉠ 경제 침체를 극복하고자 1931\n\n 년에 대외 침략을 실행하였다.\n\n\n                                      (                        )","image":"assets/questions/ebs-03-01.webp","answer":"만주\t사변","explanation":"해설\t| 자료에서 대공황의 영향으로 일본도 경제적 어려움\n을 겪게 되었으며, 이를 극복하기 위해 1931년에 대외 침\n략을 실행하였다는 점 등을 통해 밑줄 친 ㉠에 해당하는 \n역사적 사실은 만주 사변임을 알 수 있다. 만주 사변은 일\n본이 남만주 철도 폭파 사건을 조작하여 만주를 무력으로 \n침공한 사건이었다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":8,"printedPage":7,"answerPage":10},{"id":"ebs-03-02","unit":3,"number":2,"type":"choice","title":"2. 다음 자료의 정책이 추진된 시기를 연표에서 옳게 고른 ","text":"2. 다음 자료의 정책이 추진된 시기를 연표에서 옳게 고른\n것은?\n\n\n               사진은 한반도 남\n\n               부 지방의 한 농촌\n\n               에서 일제의 강요\n\n               에 의해 공업 원료\n\n               로 쓰일 면화 재배\n\n 에 나선 한국인들의 모습을 보여 준다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n 대한 제국 화폐 정리  회사령   치안   대공황 중일 전쟁\n  수립  사업 실시  공포   유지법   발생   발발\n                 제정\n\n① (가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-03-02.webp","answer":"⑤","explanation":"해설\t|\t자료에서 한반도 남부 지역에서 일제의 강요에 의\n해 면화 재배가 이루어졌다는 점 등을 통해 해당 정책은 \n남면북양 정책임을 알 수 있다. 남면북양 정책은 대공황\n의 여파로 일본 본국의 면방직 공업이 어려워지자 이를 \n극복하기 위해 원료 공급을 목적으로 추진되었다. 대공황 \n발생은 1929년, 중일 전쟁 발발은 1937년에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":8,"printedPage":7,"answerPage":10},{"id":"ebs-03-03","unit":3,"number":3,"type":"choice","title":"3. (가)에 들어갈 내용으로 옳은 것은?","text":"3. (가)에 들어갈 내용으로 옳은 것은?\n\n\n 이곳은 제주도에 있는 알뜨르 비행장입니다. 일제는 1937년\n\n       (가)     을/를 일으키고 침략 전쟁을 확대해 나갔습니다.\n\n 이 과정에서 한반도에 군사 기지를 건설하였습니다.\n\n\n\n\n\n① ‌갑신정변\n\n② ‌을미사변\n\n③ ‌중일 전쟁\n\n④ ‌러일 전쟁\n\n⑤ ‌운요호 사건","image":"assets/questions/ebs-03-03.webp","answer":"③","explanation":"해설\t|\t자료에서 일제가 1937년에 일으켰다는 점, 침략 전\n쟁을 확대하고 한반도에 군사 기지를 건설하였다는 점 등\n을 통해 (가)는 중일 전쟁임을 알 수 있다. 일제는 1937년 \n중일 전쟁을 일으킨 후 한반도를 전쟁 물자와 인력 공급 \n기지로 만들어갔다.\n오답\t피하기\t|\t① 1884년, ② 1895년, ④ 1904년, ⑤ 1875년\n에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":8,"printedPage":7,"answerPage":10},{"id":"ebs-03-04","unit":3,"number":4,"type":"choice","title":"4. 다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?","text":"4. 다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?\n\n\n 이번 사변(중일 전쟁)에서 …… 상당량의 군수 물\n\n 자를 공출하여 어느 정도 효과를 올렸다. …… 그\n\n 러나 아직 불충분하며 중국 대륙 작전군에 대해 일\n\n 본으로부터의 해상 수송이 차단당하는 경우가 있더\n\n 라도, 조선의 힘만으로 보충할 수 있도록 조선 산\n\n 업 분야를 다각화하며 특히 군수 공업의 육성에 역\n\n 점을 두어야 한다.\n\n\n① ‌병인양요의 원인을 파악한다.\n\n② ‌황국 중앙 총상회의 활동을 조사한다.\n\n③ ‌동학 농민 운동의 전개 과정을 정리한다.\n\n④ ‌화폐 정리 사업을 주도한 인물을 검색한다.\n\n⑤ ‌병참 기지화 정책의 추진 과정을 알아본다.","image":"assets/questions/ebs-03-04.webp","answer":"⑤","explanation":"해설\t|\t자료에서 중일 전쟁에서 군수 물자를 공출하여 어\n느 정도 효과를 올렸다는 점, 조선의 힘만으로 보충할 수 \n있도록 조선 산업 분야를 다각화하며 특히 군수 공업의 \n육성에 역점을 두어야 한다는 점 등을 통해 병참 기지화 \n정책의 추진 과정을 알아보는 탐구 활동이 가장 적절하다\n는 것을 알 수 있다. \n오답\t피하기\t|\t① 병인양요는 병인박해가 원인이 되어 1866\n년에 일어났다. ② 황국 중앙 총상회의 활동, ③ 동학 농민 \n운동, ④ 화폐 정리 사업은 국권 피탈 이전에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":8,"printedPage":7,"answerPage":10},{"id":"ebs-03-05","unit":3,"number":5,"type":"choice","title":"5. 다음 법령에 대한 설명으로 옳은 것은?","text":"5. 다음 법령에 대한 설명으로 옳은 것은?\n\n\n 제1조 본 법에서 국가 총동원이란 전시에 국방 목\n\n    적 달성을 위해 국가의 전력을 가장 유효하\n\n    게 발휘하도록 인적·물적 자원을 통제 운\n\n    용하는 것을 가리킨다.\n\n 제4조 정부는 전시에 국가 총동원상 필요한 경우\n\n    에는 칙령이 정하는 바에 따라 제국 신민을\n\n    징용하여 총동원 업무에 종사시킬 수 있다.\n\n\n① 동아일보,‌    조선일보 창간에 영향을 끼쳤다.\n\n② ‌동양 척식 주식회사의 설립 계기가 되었다.\n\n③ ‌미곡 공출 제도를 실시하는 근거가 되었다.\n\n④ ‌통상 수교 거부 정책 실시의 배경이 되었다.\n\n⑤ ‌국채 보상 운동이 일어나는 결과를 가져왔다.","image":"assets/questions/ebs-03-05.webp","answer":"③","explanation":"해설\t|\t자료는 중일 전쟁을 일으킨 일제가 1938년에 제\n정·공포한 국가 총동원법이다. 이 법령에 따라 일제는 \n전쟁에 필요한 인력과 물자를 강제로 동원할 수 있었고, \n그로 인해 한국인들이 많은 희생을 치러야 했다. 일제가 \n국가 총동원법을 실시하면서 한반도에서 인적·물적 자\n원을 강제 동원할 수 있도록 함에 따라 금속과 미곡이 공\n출되었다.\n오답\t피하기\t|\t① 동아일보, 조선일보 창간은 1920년대에 \n해당한다. ② 동양 척식 주식회사 설립, ④ 통상 수교 거\n부 정책 실시, ⑤ 국채 보상 운동은 국권 피탈 이전에 해\n당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":9,"printedPage":8,"answerPage":10},{"id":"ebs-03-06","unit":3,"number":6,"type":"choice","title":"6. 다음 포스터가 제작된 시기를 연표에서 옳게 고른 것","text":"6. 다음 포스터가 제작된 시기를 연표에서 옳게 고른 것\n은?\n\n\n\n\n\n 자료는 조선 총독부 농상국에서 제작한 공동 작업\n\n 과 미곡 공출 장려 포스터이다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n  을사   국권     3·1   치안  중일 전쟁   8·15\n  늑약   피탈   운동   유지법   발발   광복\n                 제정\n\n① (가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-03-06.webp","answer":"⑤","explanation":"해설\t|\t자료에서 조선 총독부에서 제작하였다는 점, 공동 \n작업과 미곡 공출을 장려하는 내용이 있다는 점 등을 통\n해 포스터가 제작된 시기는 중일 전쟁 이후임을 알 수 있\n다. 중일 전쟁 발발은 1937년, 8·15 광복은 1945년에 해\n당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":9,"printedPage":8,"answerPage":10},{"id":"ebs-03-07","unit":3,"number":7,"type":"choice","title":"7. (가)에 들어갈 내용으로 옳은 것은?","text":"7. (가)에 들어갈 내용으로 옳은 것은?\n\n\n [한국사 학습 내용 요약]\n\n    일제 강점기 ◯◯◯ 지역의 민족 운동\n\n •국권 피탈 이후 신한촌을 중심으로 독립운동 기\n\n  지 건설\n\n •이상설 등이      (가)    을/를 조직하고 권업\n\n  신문을 발간\n\n •대한 광복군 정부 조직\n\n •중일 전쟁 발발 이후 소련에 의해 한인들이 중\n\n  앙아시아로 강제 이주(1937)\n\n\n\n① ‌보안회\n\n② ‌신민회\n\n③ ‌권업회\n\n④ ‌독립 협회\n\n⑤ ‌대한 자강회","image":"assets/questions/ebs-03-07.webp","answer":"③","explanation":"해설\t|\t자료에서 신한촌을 중심으로 독립운동 기지가 건설\n되었다는 점, 권업신문을 발간하였다는 점, 대한 광복군 \n정부가 조직되었다는 점 등을 통해 연해주 지역의 민족 \n운동 관련 내용이며, (가)는 권업회임을 알 수 있다.\n오답\t피하기\t|\t①, ②, ④, ⑤ 모두 국권 피탈 이전에 국내에\n서 조직된 단체이다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":9,"printedPage":8,"answerPage":10},{"id":"ebs-03-08","unit":3,"number":8,"type":"choice","title":"8. (가)에 들어갈 지역으로 옳은 것은?","text":"8. (가)에 들어갈 지역으로 옳은 것은?\n\n\n 1900년대 초      (가)   사탕수수 농장으로 한국\n\n 인들이 노동자로 일하러 가면서 미주 지역으로의\n\n 이주가 시작되었다. 이후      (가)    에서 상대적\n\n 으로 가까운 미국 서부 지역으로 한국인들이 이주\n\n 하면서 한인 사회를 형성하였다.      (가)    에서\n\n 는 박용만 등을 중심으로 대조선 국민 군단이 조직\n\n 되었다.\n\n\n① ‌하와이\n\n② ‌멕시코\n\n③ ‌서간도\n\n④ ‌북간도\n\n⑤ ‌상하이","image":"assets/questions/ebs-03-08.webp","answer":"①","explanation":"해설\t|\t자료에서 1900년대 초 사탕수수 농장으로 한국인들\n이 노동자로 일하러 가면서 미주 지역으로의 이주가 시작\n되었다는 점, 박용만 등을 중심으로 대조선 국민 군단이 \n조직되었다는 점 등을 통해 (가) 지역은 하와이임을 알 수 \n있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":9,"printedPage":8,"answerPage":10},{"id":"blank-03","unit":3,"number":9,"type":"blank","title":"일제가 한국을 침략 전쟁에 필요한 군수 물자의 공급 기지로 만든 정책을 ____ 정책이라고 한다.","text":"일제가 한국을 침략 전쟁에 필요한 군수 물자의 공급 기지로 만든 정책을 ____ 정책이라고 한다.","answer":"병참 기지화","explanation":"북부 지역의 중화학 공업과 군수 산업 확대가 대표적인 모습이다.","criteria":[],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":12},{"id":"essay-03","unit":3,"number":10,"type":"essay","title":"일제의 병참 기지화가 산업 구조와 주민의 경제생활에 미친 영향을 설명하시오.","text":"일제의 병참 기지화가 산업 구조와 주민의 경제생활에 미친 영향을 설명하시오.","answer":"일제는 전쟁 물자 공급을 위해 북부 지역의 중화학 공업과 군수 산업을 육성했다. 이 과정에서 주민들은 노동력 동원에 시달렸으며, 미곡·금속류 공출과 생필품 배급으로 일상생활이 어려워졌다.","explanation":"일제는 전쟁 물자 공급을 위해 북부 지역의 중화학 공업과 군수 산업을 육성했다. 이 과정에서 주민들은 노동력 동원에 시달렸으며, 미곡·금속류 공출과 생필품 배급으로 일상생활이 어려워졌다.","criteria":["전쟁 물자 공급 목적","북부 중화학·군수 산업 육성","공출·배급 또는 노동력 동원의 피해"],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":12},{"id":"ebs-04-01","unit":4,"number":1,"type":"choice","title":"1. 밑줄 친 ‘이 단체’에 대한 설명으로 옳은 것은?","text":"1. 밑줄 친 ‘이 단체’에 대한 설명으로 옳은 것은?\n\n\n 이 단체는 고종의 밀명을 받은 의병장 출신 임병찬\n\n 등의 주도로 결성되었다. 나라를 되찾아 고종을 복\n\n 위시키려는 목표를 세웠으나 일제에 국권 반환 요\n\n 구서를 보내려고 계획하던 중 조직이 발각되어 해\n\n 체되었다.\n\n\n① 의병‌  전쟁을 계획하였다.\n\n② ‌105인 사건으로 해체되었다.\n\n③ ‌국채 보상 운동을 주도하였다.\n\n④ ‌파리 강화 회의에 대표를 파견하였다.\n\n⑤ ‌고종의 강제 퇴위 반대 운동을 벌였다.","image":"assets/questions/ebs-04-01.webp","answer":"①","explanation":"해설\t| 자료에서 임병찬 등의 주도로 결성되었다는 점, 고\n종을 복위시키려는 목표를 세웠다는 점 등을 통해 밑줄 \n친 ‘이 단체’가 1912년에 조직된 독립 의군부임을 알 수 있\n다. 독립 의군부는 전국적인 의병 전쟁을 추진하였다.\n오답\t피하기\t|\t② 신민회, ③ 국채 보상 기성회 등, ④ 신한 \n청년당 등, ⑤ 대한 자강회에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":11,"printedPage":10,"answerPage":13},{"id":"ebs-04-02","unit":4,"number":2,"type":"choice","title":"2. (가)에 해당하는 단체로 옳은 것은?","text":"2. (가)에 해당하는 단체로 옳은 것은?\n\n\n 1910년대에 활동했던 대표적 비밀 결사인\n\n       (가)    은/는 박상진을 총사령으로 군대식 조\n\n 직을 갖추고 다음과 같은 강령을 발표하였다.\n\n  1. 부호의‌   의연금 및 일본인이 불법 징수하는 세금\n\n  을 압수하여 무장을 준비한다.\n\n  2. ‌남북 만주에 사관 학교를 세워 독립 전사를 양성\n\n   한다.\n\n  3. ‌종래의 의병 및 해산 군인과 만주 이주민을 소집\n\n  하여 훈련한다.\n\n\n① 보안회‌\n\n② ‌신민회\n\n③ ‌독립 협회\n\n④ ‌대한 자강회\n\n⑤ ‌대한 광복회","image":"assets/questions/ebs-04-02.webp","answer":"⑤","explanation":"해설\t|\t자료에서 박상진을 총사령으로 군대식 조직을 갖추\n었다는 점과 강령의 내용 등을 통해 (가) 단체는 1915년에 \n조직된 대한 광복회임을 알 수 있다. 대한 광복회는 국권 \n회복 후 공화정 형태의 근대 국가 건설을 추구하였다.\n오답\t피하기\t|\t①, ②, ③, ④ 모두 국권 피탈 이전에 조직되\n었으며, 제시된 자료와 관련이 없다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":11,"printedPage":10,"answerPage":13},{"id":"ebs-04-03","unit":4,"number":3,"type":"short","title":"3. (가)에 들어갈 내용을 쓰시오.","text":"3. (가)에 들어갈 내용을 쓰시오.\n\n\n 제1차 세계 대전의 전후 처리 문제를 두고 미국 대\n\n 통령 윌슨이 민족 자결주의를 제창하였다. 이에 독\n\n 립운동가들은 우리 민족의 독립 의지를 알리고자\n\n 파리 강화 회의에 대표를 파견하거나 독립 선언서\n\n 를 발표하였다. 특히 일본에 유학 중이던 한국 청\n\n 년들은 조선 청년 독립단의 이름으로 도쿄에서\n\n       (가)    을/를 발표하였다.\n\n\n\n                                      (                        )","image":"assets/questions/ebs-04-03.webp","answer":"2·8\t독립\t선언","explanation":"해설\t|\t자료에서 일본에 유학 중이던 한국 청년들이 조선 \n청년 독립단의 이름으로 발표하였다는 점 등을 통해 (가)\n는 2·8 독립 선언임을 알 수 있다. 1918년 제1차 세계 대\n전의 전후 처리 문제를 두고 미국 대통령 윌슨이 민족 자\n결주의를 제창하였다. 이에 독립운동가들은 파리 강화 회\n의에 대표를 파견하거나 독립 선언서를 발표하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":11,"printedPage":10,"answerPage":13},{"id":"ebs-04-04","unit":4,"number":4,"type":"choice","title":"4. 밑줄 친 ‘이 운동’에 대한 설명으로 옳지 않은 것은?","text":"4. 밑줄 친 ‘이 운동’에 대한 설명으로 옳지 않은 것은?\n\n\n 이 운동은 손병희 등 민족 대표가 독립 선언서를\n\n 발표하고, 탑골 공원에서는 학생과 시민이 모여 ‘대\n\n 한 독립 만세’를 외치며 시위를 벌이면서 본격적으\n\n 로 시작되었다. 이후 만세 시위는 주요 도시로 빠\n\n 르게 확산되었다.\n\n\n① ‌을사늑약 체결을 계기로 일어났다.\n\n② ‌중국의 5·4 운동에 영향을 주었다.\n\n③ ‌대한민국 임시 정부 수립으로 이어졌다.\n\n④ ‌일제 강점기 최대 규모의 항일 운동이었다.\n\n⑤ ‌일제의 식민 통치 방식에 변화를 가져왔다.","image":"assets/questions/ebs-04-04.webp","answer":"①","explanation":"해설\t|\t자료에서 손병희 등 민족 대표가 독립 선언서를 발\n표하였다는 점, 학생과 시민이 만세 시위를 벌였다는 점 \n등을 통해 밑줄 친 ‘이 운동’이 3·1 운동임을 알 수 있다. \n3·1 운동은 일제 강점기 최대 규모의 민족 운동이었다. \n이 운동을 계기로 일제는 식민 통치 방식을 이른바 문화 \n정치로 바꾸었으며, 상하이에서는 대한민국 임시 정부가 \n수립되었다. 또한 같은 해 일어난 중국의 5·4 운동에 영\n향을 주었다.\n오답\t피하기\t|\t① 을사의병 등에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":11,"printedPage":10,"answerPage":13},{"id":"ebs-04-05","unit":4,"number":5,"type":"choice","title":"5. 밑줄 친 ‘이 운동’이 있었던 시기를 연표에서 옳게 고른 ","text":"5. 밑줄 친 ‘이 운동’이 있었던 시기를 연표에서 옳게 고른\n것은?\n\n\n  우리는 오늘 우리 조선이 독립국임과 조선인이\n\n  자주민임을 선언하노라. 우리는 이를 세계 모\n\n  든 나라에 알려 인류가 모두 평등하다는 큰 뜻\n\n  을 분명히 하고, 우리 후손이 민족 스스로 살\n\n  아갈 정당한 권리를 영원히 누리게 할 것이다.\n\n  [해설] 자료는 1919년에 있었던 이 운동에서 발표한\n\n 독립 선언문의 일부이다. 민족 대표 33인의 이름으\n\n 로 작성되었다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n  을미   국권  대한민국  만주  중일 전쟁   8·15\n  사변   피탈  임시 정부  사변   발발   광복\n            수립\n\n① (가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-04-05.webp","answer":"②","explanation":"해설\t|\t자료에서 1919년에 있었다는 점, 민족 대표 33인\n의 이름으로 작성된 독립 선언문이라는 점 등을 통해 밑\n줄 친 ‘이 운동’이 3·1 운동임을 알 수 있다. 국권 피탈은 \n1910년에 해당하며, 대한민국 임시 정부는 1919년 3·1 \n운동을 계기로 수립되었다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":12,"printedPage":11,"answerPage":13},{"id":"ebs-04-06","unit":4,"number":6,"type":"choice","title":"6. 다음 헌법을 공포한 정부의 활동으로 옳지 않은 것은?","text":"6. 다음 헌법을 공포한 정부의 활동으로 옳지 않은 것은?\n\n\n 제1조 대한민국은 대한 인민으로 조직함.\n\n 제2조 대한민국의 주권은 대한 인민 전체에 있음.\n\n 제3조 대한민국의 강토는 구한국의 판도로 함.\n\n 제4조 대한민국의 인민은 일체 평등함.\n\n 제5조 대한민국의 입법권은 의정원이, 행정권은\n\n     국무원이, 사법권은 법원이 행사함.\n\n\n① 독립신문을‌      발간하였다.\n\n② ‌독립 공채를 발행하였다.\n\n③ ‌구미 위원부를 설치하였다.\n\n④ ‌국채 보상 운동을 주도하였다.\n\n⑤ ‌연통제와 교통국을 운영하였다.","image":"assets/questions/ebs-04-06.webp","answer":"④","explanation":"해설\t|\t자료는 1919년 9월 공포된 대한민국 임시 정부의 임\n시 헌법이다. 1919년 3·1 운동을 계기로 연해주, 상하이, \n서울 등에 세워진 임시 정부는 곧바로 통합 운동을 전개\n해 1919년 9월에 통합된 대한민국 임시 정부가 세워졌다. \n대한민국 임시 정부는 국내외 독립운동 소식을 알리기 위\n해 독립신문을 발간하였으며, 독립운동 자금 마련을 위해 \n독립 공채를 발행하였다. 또한 외교 활동을 위해 구미 위\n원부를 설치하였으며, 국내와의 연락을 위해 연통제와 교\n통국을 운영하였다.\n오답\t피하기\t|\t④ 국채 보상 운동은 대한 제국이 일본에 진 \n빚을 갚아 경제적 주권을 지키자는 운동으로 1907년에 전\n개되었다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":12,"printedPage":11,"answerPage":13},{"id":"ebs-04-07","unit":4,"number":7,"type":"choice","title":"7. (가)에 들어갈 내용으로 옳은 것은?","text":"7. (가)에 들어갈 내용으로 옳은 것은?\n\n\n\n\n\n 자료는 대한민국 임시 정부가 국제 연맹에 한국 독\n\n 립의 당위성을 호소하기 위해 편찬한      (가)       \n\n 이다. 여기에는 삼국 시대 이후의 한일 관계사가\n\n 기록되어 있으며, 특히 일제의 잔혹한 식민 통치\n\n 방식 등이 잘 정리되어 있다.\n\n\n① ‌독립신문\n\n② ‌독사신론\n\n③ ‌조선왕조실록\n\n④ ‌한일 관계 사료집\n\n⑤ ‌한국독립운동지혈사","image":"assets/questions/ebs-04-07.webp","answer":"④","explanation":"해설\t|\t자료에서 대한민국 임시 정부가 편찬하였다는 점, \n한일 관계사가 기록되어 있다는 점 등을 통해 (가)는 『한\n일 관계 사료집』임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":12,"printedPage":11,"answerPage":13},{"id":"ebs-04-08","unit":4,"number":8,"type":"choice","title":"8. (가), (나) 시기 사이에 있었던 사실로 옳은 것은?","text":"8. (가), (나) 시기 사이에 있었던 사실로 옳은 것은?\n\n\n  (가) ‌임시 의정원은 대한민국 임시 헌법을 공포하\n\n   고 임시 대통령에 이승만, 국무총리에 이동휘\n\n   를 선임하였다.\n\n  (나) ‌제2대 임시 대통령에 취임한 박은식은 개헌을\n\n   단행해 대한민국 임시 정부를 국무령 중심의\n\n   내각 책임제로 개편하였다.\n\n\n① ‌신미양요가 일어났다.\n\n② ‌대한 제국이 수립되었다.\n\n③ ‌백두산 정계비가 세워졌다.\n\n④ ‌국민 대표 회의가 개최되었다.\n\n⑤ ‌민족 대표들이 태화관에서 독립 선언서를 낭독하였다.","image":"assets/questions/ebs-04-08.webp","answer":"④","explanation":"해설\t|\t(가)는 통합된 대한민국 임시 정부가 출범한 1919년 \n9월의 사실이고, (나)는 제2대 대통령에 취임한 박은식이 \n개헌을 했다는 것을 통해 1925년의 사실임을 알 수 있다. \n1923년에 독립운동의 새로운 방향을 모색하기 위해 국민 \n대표 회의가 개최되었다.\n오답\t피하기\t|\t①, ②, ③, ⑤ 모두 (가) 시기 이전에 해당한다. ","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":12,"printedPage":11,"answerPage":13},{"id":"blank-04","unit":4,"number":9,"type":"blank","title":"대한민국 임시 정부가 국내외를 연결하기 위해 운영한 비밀 행정 조직은 ____이다.","text":"대한민국 임시 정부가 국내외를 연결하기 위해 운영한 비밀 행정 조직은 ____이다.","answer":"연통제","explanation":"통신 기관인 교통국과 함께 임시 정부의 국내외 연락과 활동을 뒷받침했다.","criteria":[],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":17},{"id":"essay-04","unit":4,"number":10,"type":"essay","title":"3·1 운동이 독립운동과 일제의 통치 방식에 미친 영향을 세 가지 서술하시오.","text":"3·1 운동이 독립운동과 일제의 통치 방식에 미친 영향을 세 가지 서술하시오.","answer":"3·1 운동은 독립운동을 이끌 통합 지도부의 필요성을 높여 대한민국 임시 정부 수립을 촉진했다. 무장 투쟁 등 다양한 민족 운동을 활성화했고, 일제는 무단 통치의 한계를 깨닫고 문화 정치를 표방했다.","explanation":"3·1 운동은 독립운동을 이끌 통합 지도부의 필요성을 높여 대한민국 임시 정부 수립을 촉진했다. 무장 투쟁 등 다양한 민족 운동을 활성화했고, 일제는 무단 통치의 한계를 깨닫고 문화 정치를 표방했다.","criteria":["대한민국 임시 정부 수립 촉진","다양한 독립운동 활성화","문화 정치로의 전환"],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":17},{"id":"ebs-05-01","unit":5,"number":1,"type":"choice","title":"1. (가)에 대한 탐구 활동으로 가장 적절한 것은?","text":"1. (가)에 대한 탐구 활동으로 가장 적절한 것은?\n\n\n 백두산 방향으로 이동하던 독립군은 1920년 10월\n\n 21일부터 26일까지 백운평, 완루구, 어랑촌 등지에\n\n 서 이어진 10여 차례의 크고 작은 전투에서 일본군\n\n 을 크게 무찔렀다. 이것이      (가)    이다.\n\n\n① 병자호란의‌     영향을 파악한다.\n\n② ‌정묘호란의 내용을 조사한다.\n\n③ ‌한산도 대첩의 성과를 분석한다.\n\n④ ‌북로 군정서군의 활약상을 살펴본다.\n\n⑤ ‌13도 창의군의 창설 배경을 알아본다.","image":"assets/questions/ebs-05-01.webp","answer":"④","explanation":"해설\t| 자료에서 1920년 10월에 발생한 전투라는 점, 6일 동\n안에 벌어진 10여 차례의 전투에서 독립군이 승리하였다는 \n점 등을 통해 (가)가 청산리 대첩임을 알 수 있다. 청산리 대\n첩에서는 김좌진이 이끄는 북로 군정서와 홍범도가 이끄는 \n대한 독립군 등 독립군 연합 부대가 활약하였다.\n오답\t피하기\t|\t①, ②, ③ 조선 시대에 해당한다. ⑤ 13도 창\n의군은 정미의병 당시 창설된 의병 연합 부대로 1908년에 \n서울 진공 작전을 벌였으나 실패하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":14,"printedPage":13,"answerPage":16},{"id":"ebs-05-02","unit":5,"number":2,"type":"choice","title":"2. 다음 선언을 활동 지침으로 삼은 단체에 대한 설명으로 ","text":"2. 다음 선언을 활동 지침으로 삼은 단체에 대한 설명으로\n옳은 것은?\n\n\n 강도 일본을 쫓아내려면 오직 혁명으로만 가능하\n\n 며, 혁명이 아니고는 강도 일본을 쫓아낼 방법이\n\n 없는 바이다. …… 우리는 민중 속으로 가서 민중\n\n 과 손을 맞잡아 끊임없는 폭력-암살, 파괴, 폭동-\n\n 으로써 강도 일본의 통치를 타도하고, 우리 생활에\n\n 불합리한 일체의 제도를 개조하여, 인류로써 인류\n\n 를 압박하지 못하며, 사회로써 사회를 박탈하지 못\n\n 하는 이상적 조선을 건설할지니라.\n\n\n① 윤관의‌   건의로 조직되었다.\n\n② ‌고종 황제의 복위를 목표로 활동하였다.\n\n③ ‌삼정이정청이 설치되는 계기를 마련하였다.\n\n④ ‌김원봉을 중심으로 의열 투쟁을 전개하였다.\n\n⑤ ‌교조 최제우의 억울함을 풀기 위한 운동을 벌였다.","image":"assets/questions/ebs-05-02.webp","answer":"④","explanation":"해설\t|\t자료는 김원봉의 요청으로 신채호가 1923년에 작성\n한 「조선 혁명 선언」 의 일부이다. 「조선 혁명 선언」 은 의열 \n투쟁을 전개하던 의열단의 활동 지침이 되었다. 의열단은 \n1919년 만주에서 조직되어 김원봉을 중심으로 활발한 의\n열 투쟁을 전개하였다.\n오답\t피하기\t|\t① 별무반, ② 독립 의군부, ③ 임술 농민 봉\n기, ⑤ 동학교도에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":14,"printedPage":13,"answerPage":16},{"id":"ebs-05-03","unit":5,"number":3,"type":"choice","title":"3. (가)에 해당하는 단체로 옳은 것은?","text":"3. (가)에 해당하는 단체로 옳은 것은?\n\n\n                  (가)   단원의 의거 활동\n\n    김익상 조선 총독부에 폭탄 투척\n\n    김상옥 종로 경찰서에 폭탄 투척\n\n    김지섭 도쿄 궁성에 폭탄 투척\n\n        동양 척식 주식회사와 조선 식산 은행\n    나석주\n        에 폭탄 투척\n\n\n\n① ‌보안회\n\n② ‌신민회\n\n③ ‌의열단\n\n④ ‌독립 협회\n\n⑤ ‌대한 광복회","image":"assets/questions/ebs-05-03.webp","answer":"③","explanation":"해설\t|\t자료에서 김익상, 김상옥, 김지섭, 나석주가 단원으\n로 활동하였다는 점 등을 통해 (가) 단체가 의열단임을 알 \n수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":14,"printedPage":13,"answerPage":16},{"id":"ebs-05-04","unit":5,"number":4,"type":"choice","title":"4. 다음 자료를 활용한 탐구 주제로 가장 적절한 것은?","text":"4. 다음 자료를 활용한 탐구 주제로 가장 적절한 것은?\n\n\n\n\n\n 첫째 조선 사람은 조선 사람이 지은 것을 사 쓰고,\n\n 둘째 조선 사람은 단결하여 그 쓰는 물건을 스스로\n\n 제작하여 공급하기를 목적하노라.\n\n\n① ‌브나로드 운동의 성과\n\n② ‌토지 조사 사업의 영향\n\n③ ‌국채 보상 운동의 전개\n\n④ ‌조선 물산 장려회의 활동\n\n⑤ ‌경성 제국 대학의 설립 배경","image":"assets/questions/ebs-05-04.webp","answer":"④","explanation":"해설\t|\t자료는 경성 방직 주식회사의 토산품 애용 선전 광\n고와 조선 물산 장려회의 취지서 내용의 일부로 모두 물\n산 장려 운동과 관련된 것이다. 물산 장려 운동은 1920년\n대 초에 전개된 토산품 애용 운동이다. 조만식 등은 1920\n년 평양에서 조선 물산 장려회를 조직하여 물산 장려 운\n동을 시작하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":14,"printedPage":13,"answerPage":16},{"id":"ebs-05-05","unit":5,"number":5,"type":"choice","title":"5. 다음 취지에 따라 전개된 민족 운동에 대한 설명으로 옳","text":"5. 다음 취지에 따라 전개된 민족 운동에 대한 설명으로 옳\n은 것은?\n\n\n 우리의 운명을 어떻게 개척할까? 정치냐, 외교냐,\n\n 산업이냐? 물론 이와 같은 일이 모두 필요하도다.\n\n 그러나 그 기초가 되고 요건이 되며, 가장 급한 일\n\n 이 되고, 가장 먼저 해결해야 할 필요가 있으며, 가\n\n 장 힘 있고, 필요한 수단은 교육이 아니면 아니된\n\n 다. …… 오늘날 조선인이 세계 문화 민족의 일원\n\n 으로 남과 어깨를 견주고 우리의 생존을 유지하며\n\n 문화의 창조와 향상을 기도하려면, 대학의 설립이\n\n 아니고는 다른 방도가 없도다.\n\n\n① 대한‌  자강회의 지원을 받았다.\n\n② ‌개혁을 위해 집강소를 설치하였다.\n\n③ ‌성균관을 세워 유교 교육을 실시하였다.\n\n④ ‌대구에서 시작되어 전국으로 확산되었다.\n\n⑤ ‌1천만 원 마련을 위한 모금 활동을 벌였다.","image":"assets/questions/ebs-05-05.webp","answer":"⑤","explanation":"해설\t|\t자료는 1923년에 발표된 민립 대학 설립 기성회 발\n기 취지서의 내용 중 일부이다. 일제는 1922년 제2차 조\n선 교육령을 제정해 한국인에 대한 교육을 확대하겠다고 \n발표하였으나 고등 교육 기관은 설립하지 않았다. 이에 \n한국인 본위의 교육을 실시하고 한국인의 힘으로 대학을 \n세우려는 민립 대학 설립 운동이 전개되었다. 민립 대학 \n설립 운동은 대학 설립에 필요한 자금 1천만 원을 마련하\n기 위해 모금 활동을 벌였다.\n오답\t피하기\t|\t① 대한 자강회는 국권 피탈 이전에 해산되었\n다. ② 동학 농민 운동에 해당한다. ③ 성균관은 고려·조\n선 시대의 교육 기관이다. ④ 국채 보상 운동에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":15,"printedPage":14,"answerPage":16},{"id":"ebs-05-06","unit":5,"number":6,"type":"short","title":"6. 다음 설명에 해당하는 민족 운동을 쓰시오.","text":"6. 다음 설명에 해당하는 민족 운동을 쓰시오.\n\n\n •동아일보사의 주도로 문맹 퇴치와 미신 타파를\n\n  목적으로 전개되었다.\n\n •19세기 후반 러시아의 청년 지식인들이 민중 계\n\n  몽을 위해 농촌으로 들어가면서 내세웠던 구호로\n\n  운동의 이름을 지었다.\n\n\n                                      (                        )","image":"assets/questions/ebs-05-06.webp","answer":"브나로드\t운동","explanation":"해설\t|\t동아일보사가 주도하였다는 점, 문맹 퇴치와 미신 \n타파를 목적으로 한다는 점, 러시아 청년 지식인들이 사\n용하던 구호로 운동의 이름을 지었다는 점 등을 통해 자\n료에서 설명하는 민족 운동은 브나로드 운동임을 알 수 있\n다. 동아일보사는 러시아어로 ‘민중 속으로’라는 뜻을 가\n진 브나로드라는 이름으로 농촌 계몽 운동을 전개하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":15,"printedPage":14,"answerPage":16},{"id":"ebs-05-07","unit":5,"number":7,"type":"choice","title":"7. 다음 강령을 내세운 단체에 대한 설명으로 옳은 것은?","text":"7. 다음 강령을 내세운 단체에 대한 설명으로 옳은 것은?\n\n\n  1. ‌우리는 정치적·경제적 각성을 촉진함.\n\n  2. ‌우리는 단결을 공고히 함.\n\n  3. ‌우리는 기회주의를 일체 부인함.\n\n\n① ‌독립문을 건립하였다.\n\n② ‌3·1 운동을 지원하였다.\n\n③ ‌비밀 결사 형태로 조직되었다.\n\n④ ‌고종의 강제 퇴위 반대 운동을 벌였다.\n\n⑤ ‌비타협적 민족주의 세력과 사회주의 세력의 연대로\n\n  결성되었다.","image":"assets/questions/ebs-05-07.webp","answer":"⑤","explanation":"해설\t|\t단결을 공고히 하고 기회주의를 일체 부인한다는 \n점 등을 통해 자료는 1927년에 창립된 신간회의 강령임을 \n알 수 있다. 신간회는 비타협적 민족주의 세력과 사회주\n의 세력의 연대로 결성되었다.\n오답\t피하기\t|\t① 독립 협회에 해당한다. ② 3·1 운동은 \n1919년에 일어났다. ③ 신민회 등, ④ 대한 자강회에 해당\n한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":15,"printedPage":14,"answerPage":16},{"id":"ebs-05-08","unit":5,"number":8,"type":"choice","title":"8. 다음 대화의 소재가 된 단체로 옳은 것은?","text":"8. 다음 대화의 소재가 된 단체로 옳은 것은?\n\n\n 정우회 선언을 계기로        맞아. 다양한 사회 운동을\n 1927년에 결성된 이 단체      지원하다가 사회주의 세\n 는 전국 순회 강연회 등      력의 해소 주장으로 결국\n 을 개최하였어.                1931년에 해체되었어.\n\n\n\n\n\n① ‌신간회\n\n② ‌황국 협회\n\n③ ‌대한 자강회\n\n④ ‌독립 의군부\n\n⑤ ‌조선 물산 장려회","image":"assets/questions/ebs-05-08.webp","answer":"①","explanation":"해설\t|\t정우회 선언을 계기로 1927년에 결성되었다는 점, \n사회주의 세력의 해소 주장으로 1931년에 해체되었다는 \n점 등을 통해 자료는 신간회에 대한 것임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":15,"printedPage":14,"answerPage":16},{"id":"blank-05","unit":5,"number":9,"type":"blank","title":"1927년 비타협적 민족주의 세력과 사회주의 세력이 함께 결성한 대표적 민족 협동 전선 단체는 ____이다.","text":"1927년 비타협적 민족주의 세력과 사회주의 세력이 함께 결성한 대표적 민족 협동 전선 단체는 ____이다.","answer":"신간회","explanation":"신간회는 기회주의 배격과 단결을 내세우고 농민·노동·학생 운동을 지원했다.","criteria":[],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":22},{"id":"essay-05","unit":5,"number":10,"type":"essay","title":"물산 장려 운동과 민립 대학 설립 운동의 공통 목표 및 각각의 방법을 설명하시오.","text":"물산 장려 운동과 민립 대학 설립 운동의 공통 목표 및 각각의 방법을 설명하시오.","answer":"두 운동은 민족의 실력을 길러 독립의 토대를 마련하려 했다. 물산 장려 운동은 토산품 애용으로 민족 기업과 자본을 보호하려 했고, 민립 대학 설립 운동은 모금을 통해 한국인의 고등 교육 기관을 세우려 했다.","explanation":"두 운동은 민족의 실력을 길러 독립의 토대를 마련하려 했다. 물산 장려 운동은 토산품 애용으로 민족 기업과 자본을 보호하려 했고, 민립 대학 설립 운동은 모금을 통해 한국인의 고등 교육 기관을 세우려 했다.","criteria":["독립을 위한 실력 양성","토산품 애용과 민족 기업 보호","모금을 통한 고등 교육 기관 설립"],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":22},{"id":"ebs-06-01","unit":6,"number":1,"type":"short","title":"1. (가)에 들어갈 알맞은 내용을 쓰시오.","text":"1. (가)에 들어갈 알맞은 내용을 쓰시오.\n\n\n 일제 강점기에는 도시\n\n 를 중심으로 의식주와\n\n 같은 일상생활에 많은\n\n 변화가 나타났다. 특히\n\n 신문·잡지와 같은 매\n\n 체에 새로운 대중문화\n\n 가 소개되어 유행하였다. 이에 그림과 같이 서양식\n\n 옷차림에 쇼핑과 외식을 즐기는      (가)      (이)\n\n 라 불리는 사람들이 등장하였다.\n\n\n                                      (                        )","image":"assets/questions/ebs-06-01.webp","answer":"모던\t보이,\t모던\t걸","explanation":"해설\t| 자료에서 일제 강점기에 나타난 의식주 생활의 변\n화를 언급하고 있으며, 이에 영향을 받은 새로운 계층이 \n출현하였음을 이야기하고 있다. 서양식 옷차림에 쇼핑과 \n외식을 즐기는 사람들을 당시에 모던 보이, 모던 걸이라\n고 불렀다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":17,"printedPage":16,"answerPage":19},{"id":"ebs-06-02","unit":6,"number":2,"type":"choice","title":"2. 밑줄 친 ㉠에 해당하는 내용으로 옳은 것은?","text":"2. 밑줄 친 ㉠에 해당하는 내용으로 옳은 것은?\n\n\n 일제의 토지 조사 사업과 산미 증식 계획으로 농민\n\n 들의 생활이 갈수록 어려워졌다. 농민들은 관습적\n\n 경작권을 보장받지 못하였으며, 지주들은 더 많은\n\n 이익을 올리기 위해 고율의 소작료를 농민들에게\n\n 징수하였다. 이러한 열악한 상황을 개선하기 위해\n\n 농민들은 ㉠ 지주의 횡포와 일제의 농촌 정책에 저\n\n 항하였다.\n\n\n① 집강소를‌    설치하였다.\n\n② ‌임술 농민 봉기를 일으켰다.\n\n③ ‌물산 장려 운동을 전개하였다.\n\n④ ‌사창제를 자치적으로 운영하였다.\n\n⑤ ‌소작인 조합, 농민 조합을 결성하였다.","image":"assets/questions/ebs-06-02.webp","answer":"⑤","explanation":"해설\t|\t자료는 일제의 경제 정책으로 농민들의 생활이 어\n려워졌음을 언급하고 있다. 일제 강점기 농민들은 관습적 \n경작권을 보장받지 못하였으며, 고율의 소작료를 부담해\n야 했다. 이에 저항하며 농민들은 소작 쟁의와 같은 농민 \n운동을 전개하였다. 농민들은 일제의 경제 정책과 지주들\n의 횡포에 저항하기 위해 소작인 조합, 농민 조합 등을 조\n직하여 생존권 투쟁을 벌였다.\n오답\t피하기\t|\t①, ②, ④ 국권 피탈 이전에 있었던 사실이\n다. ③ 물산 장려 운동은 1920년대 초반부터 일본 상품의 \n진출에 대응하여 토산품 애용을 주장한 경제적 실력 양성 \n운동이다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":17,"printedPage":16,"answerPage":19},{"id":"ebs-06-03","unit":6,"number":3,"type":"short","title":"3. (가)에 들어갈 단체의 명칭을 쓰시오.","text":"3. (가)에 들어갈 단체의 명칭을 쓰시오.\n\n\n 조선 노농 총동맹에서 갈라져 나와 1927년에 결성\n\n 된      (가)    은/는 각 지방의 노동 쟁의를 이끌\n\n 면서 노동 운동의 활성화에 기여하였다. 노동 쟁의\n\n 의 성격도 생존권 투쟁에서 일제의 식민 통치에 반\n\n 대하는 항일 투쟁으로 변화해 갔다. 그리고 1930년\n\n 대 노동 운동은 사회주의 혁명을 지향하는 비합법\n\n 적, 혁명적 노동조합을 중심으로 전개되었다.\n\n\n                                      (                        )","image":"assets/questions/ebs-06-03.webp","answer":"조선\t노동\t총동맹","explanation":"해설\t|\t자료에서 조선 노농 총동맹에서 갈라져 나와 1927\n년에 결성되었다는 점, 각 지방의 노동 쟁의를 이끌면서 \n노동 운동의 활성화에 기여하였다는 점 등을 통해 (가)에 \n해당하는 단체는 조선 노동 총동맹임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":17,"printedPage":16,"answerPage":19},{"id":"ebs-06-04","unit":6,"number":4,"type":"choice","title":"4. 다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?","text":"4. 다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?\n\n\n\n\n\n 자료는 원산에서 있었던 노동자들의 총파업 모습이\n\n 담긴 사진이다. 한 석유 회사에서 일본인 감독이\n\n 한국인 노동자를 구타한 사건을 계기로 1929년 1월\n\n 원산 노동자들이 총파업하였다. 일제의 탄압에도\n\n 불구하고 3,000여 명의 노동자가 4개월 동안 투쟁\n\n 을 계속하였다.\n\n\n① ‌임오군란의 결과를 분석한다.\n\n② ‌만적의 난이 추진된 원인을 알아본다.\n\n③ ‌원산 총파업의 전개 과정을 정리한다.\n\n④ ‌홍경래의 난이 발생한 배경을 찾아본다.\n\n⑤ ‌동학 농민 운동이 일어난 시기를 파악한다.","image":"assets/questions/ebs-06-04.webp","answer":"③","explanation":"해설\t|\t자료에서 원산에서 있었던 노동자들이 총파업을 일\n으켰다는 점, 일본인 감독이 한국인 노동자를 구타한 사\n건을 계기로 일어났다는 점 등을 통해 원산 총파업의 전\n개 과정을 정리하는 탐구 활동이 가장 적절하다는 것을 \n알 수 있다.\n오답\t피하기\t|\t① 임오군란, ④ 홍경래의 난, ⑤ 동학 농민 \n운동은 조선 시대에 해당한다. ② 만적의 난은 고려 시대\n에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":17,"printedPage":16,"answerPage":19},{"id":"ebs-06-05","unit":6,"number":5,"type":"choice","title":"5. 다음 상황이 있었던 시기를 연표에서 옳게 고른 것은?","text":"5. 다음 상황이 있었던 시기를 연표에서 옳게 고른 것은?\n\n\n 순종의 인산으로 전국 각처에서 수십만의 추모객\n\n 이 운집한 것을 기회로 인산 행렬이 지나갈 때 경\n\n 성 각지에서는 삼엄한 경계 아래서도 조선 독립 만\n\n 세 운동이 일어났다. 즉, 황제의 상여가 관수교를\n\n 지나갈 무렵인 오전 8시 40분경 보성 전문학교 학\n\n 생 수십 명이 활판으로 인쇄한 독립을 고취하는 격\n\n 문 수만 매를 뿌리며 조선 독립 만세를 부르고, 그\n\n 부근에 줄 서 있던 연희 전문학교 학생들도 호응하\n\n 다가 학생 30여 명이 체포되었다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n  갑신   국권     3·1   만주  중일 전쟁   8·15\n  정변   피탈   운동   사변   발발   광복\n\n① (가)‌   ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-06-05.webp","answer":"③","explanation":"해설\t|\t순종의 인산으로 추모객이 운집한 것을 계기로 독\n립 만세 운동이 일어났다는 점, 학생 수십 명이 격문을 뿌\n리며 독립 만세를 외쳤다는 점 등을 통해 자료는 1926년\n에 있었던 6·10 만세 운동임을 알 수 있다. 3·1 운동은 \n1919년, 만주 사변은 1931년에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":18,"printedPage":17,"answerPage":19},{"id":"ebs-06-06","unit":6,"number":6,"type":"choice","title":"6. 다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?","text":"6. 다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?\n\n\n 나는 피가 머리로 거꾸로 치솟는 듯한 분노를 느꼈\n\n 다. …… 그자들이 우리 여학생을 희롱하였으니 나\n\n 로서는 당연히 감정적으로 대응할 수밖에 없었다.\n\n …… “후쿠다, 너는 명색이 중학생인 녀석이 야비\n\n 하게 여학생을 희롱해?” 그러자 후쿠다는 “뭐라고\n\n 센징 놈이 까불어!” 이 센징이란 말이 후쿠다의 입\n\n 에서 떨어지기가 무섭게 내 주먹은 그자의 얼굴에\n\n 날아가 작렬하였다.\n\n\n① 독립‌  협회의 활동을 조사한다.\n\n② ‌서경 천도 운동의 결과를 분석한다.\n\n③ ‌강화도 조약의 체결 배경을 파악한다.\n\n④ ‌한성 사범학교의 설립 목표를 알아본다.\n\n⑤ ‌광주 학생 항일 운동의 전개 과정을 살펴본다.","image":"assets/questions/ebs-06-06.webp","answer":"⑤","explanation":"해설\t|\t자료에서 일본인 학생이 한국인 여학생을 희롱하였\n다는 점, 한국인 학생과 일본인 학생이 싸우고 있다는 점 \n등을 통해 광주 학생 항일 운동의 전개 과정을 살펴보는 \n탐구 활동이 가장 적절하다는 것을 알 수 있다. 1929년 일\n본인 학생이 한국인 여학생을 희롱한 일을 계기로 양국 \n학생 사이에 싸움이 일어났다. 이에 대해 경찰이 일본인 \n학생만 두둔하자, 차별에 분노한 광주 지역 학생들이 대\n규모 가두시위를 전개하면서 광주 학생 항일 운동이 일어\n났다. \n오답\t피하기\t|\t① 독립 협회, ③ 강화도 조약, ④ 한성 사범\n학교는 조선 시대에 해당한다. ② 서경 천도 운동은 고려 \n시대에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":18,"printedPage":17,"answerPage":19},{"id":"ebs-06-07","unit":6,"number":7,"type":"choice","title":"7. 다음 자료에 해당하는 사회 운동에 대한 설명으로 옳은 ","text":"7. 다음 자료에 해당하는 사회 운동에 대한 설명으로 옳은\n것은?\n\n\n            공평은 사회의 근본이고\n\n            애정은 인류의 본령이다.\n\n            그러한 까닭으로 우리는\n\n            계급을 타파하고 모욕적\n\n            칭호를 폐지하며 교육을\n\n              장려하여, 우리도 참다운\n\n            인간이 되는 것을 기하자\n\n            는 것이 우리의 주장이다.\n\n\n① ‌신간회 창립을 계기로 시작되었다.\n\n② ‌조선 형평사의 주도로 전개되었다.\n\n③ ‌대한매일신보 등의 언론이 지원하였다.\n\n④ ‌주도 세력이 정부와 전주 화약을 체결하였다.\n\n⑤ ‌조선 총독부가 회사령을 철폐하는 결과를 가져왔다.","image":"assets/questions/ebs-06-07.webp","answer":"②","explanation":"해설\t|\t자료에서 공평, 계급 타파, 모욕적 칭호 폐지 등을 \n주장하고 있다는 점, 포스터에 ‘형평’이라는 글자가 있는 \n점 등을 통해 해당 사회 운동이 형평 운동임을 알 수 있\n다. 형평 운동은 1923년 진주에서 결성된 조선 형평사를 \n중심으로 전개되었다.\n오답\t피하기\t|\t① 신간회는 1927년에 창립되었다. ③ 국채 \n보상 운동, ④ 동학 농민 운동에 해당한다. ⑤ 회사령 철\n폐는 1920년에 해당하며, 형평 운동과는 관련이 없다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":18,"printedPage":17,"answerPage":19},{"id":"ebs-06-08","unit":6,"number":8,"type":"choice","title":"8. (가)에 해당하는 인물로 옳은 것은?","text":"8. (가)에 해당하는 인물로 옳은 것은?\n\n\n         한국사 인물 카드\n\n           •이름:     (가)\n\n           •출생~사망: 1899~1931년\n\n           •호: 소파\n\n           •주요 활동\n\n             　- 어린이날 제정 주도\n\n             　- 잡지 『어린이』 창간 주도\n\n\n\n① ‌김원봉\n\n② ‌방정환\n\n③ ‌홍범도\n\n④ ‌윤동주\n\n⑤ ‌이순신","image":"assets/questions/ebs-06-08.webp","answer":"②","explanation":"해설\t|\t자료에서 어린이날 제정과 잡지 『어린이』 창간을 주\n도하였다는 점 등을 통해 (가) 인물은 방정환임을 알 수 \n있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":18,"printedPage":17,"answerPage":19},{"id":"blank-06","unit":6,"number":9,"type":"blank","title":"1923년 진주에서 조직되어 백정에 대한 차별 철폐를 주장한 단체는 ____이다.","text":"1923년 진주에서 조직되어 백정에 대한 차별 철폐를 주장한 단체는 ____이다.","answer":"조선 형평사","explanation":"형평 운동은 신분제의 법적 폐지 이후에도 남아 있던 사회적 차별에 저항했다.","criteria":[],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":27},{"id":"essay-06","unit":6,"number":10,"type":"essay","title":"일제 강점기 농민 운동과 노동 운동의 요구를 각각 설명하고 공통점을 쓰시오.","text":"일제 강점기 농민 운동과 노동 운동의 요구를 각각 설명하고 공통점을 쓰시오.","answer":"농민은 소작료 인하와 소작권 보장을 요구했고 노동자는 임금 인상과 노동 조건 개선을 요구했다. 두 운동은 열악한 생활 조건과 식민지 경제의 차별에 맞서 생존권과 권익을 지키려 했다는 공통점이 있다.","explanation":"농민은 소작료 인하와 소작권 보장을 요구했고 노동자는 임금 인상과 노동 조건 개선을 요구했다. 두 운동은 열악한 생활 조건과 식민지 경제의 차별에 맞서 생존권과 권익을 지키려 했다는 공통점이 있다.","criteria":["소작료 인하·소작권 보장","임금 인상·노동 조건 개선","생존권과 권익 보호라는 공통점"],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":27},{"id":"ebs-07-01","unit":7,"number":1,"type":"choice","title":"1. (가)에 해당하는 단체로 옳은 것은?","text":"1. (가)에 해당하는 단체로 옳은 것은?\n\n\n               1921년 결성된      (가)    은/는\n\n            ‘가갸날’을 제정하고 잡지 『한글』\n\n         을 창간하는 등 한글 연구와 보\n\n         급에 나섰다.      (가)    은/는\n\n               1931년 조선어 학회로 이름을 바\n\n          꾸었다.\n\n\n① 보안회‌\n\n② ‌신간회\n\n③ ‌독립 협회\n\n④ ‌진단 학회\n\n⑤ ‌조선어 연구회","image":"assets/questions/ebs-07-01.webp","answer":"⑤","explanation":"해설\t| 자료에서 1921년에 결성되었다는 점, ‘가갸날’을 제\n정하였다는 점, 잡지 『한글』을 창간하는 등 한글 연구를 \n하였다는 점, 조선어 학회로 이름을 바꾸었다는 점 등을 \n통해 (가) 단체가 조선어 연구회임을 알 수 있다.\n오답\t피하기\t|\t① 1904년에 조직된 보안회는 일제의 황무지 \n개간권 요구 반대 운동을 벌여 이를 철회시켰다. ②, ④ \n일제 강점기에 활동하였으나, 제시된 자료와 관련이 없\n다. ③ 독립 협회는 독립문 건립을 위해 1896년에 창립되\n었다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":20,"printedPage":19,"answerPage":22},{"id":"ebs-07-02","unit":7,"number":2,"type":"choice","title":"2. 밑줄 친 ‘이 단체’에 대한 설명으로 옳은 것은?","text":"2. 밑줄 친 ‘이 단체’에 대한 설명으로 옳은 것은?\n\n\n\n\n\n 한글 맞춤법 통일안을 발표한 이 단체는 『우리말\n\n (조선말) 큰사전』 편찬을 시도하였으나 일제의 탄\n\n 압으로 중단되었다.\n\n\n① 한성순보를‌      발간하였다.\n\n② ‌수원 화성을 축조하였다.\n\n③ ‌잡지 근우를 발행하였다.\n\n④ ‌표준어 표기법을 제정하였다.\n\n⑤ ‌6·10 만세 운동을 주도하였다.","image":"assets/questions/ebs-07-02.webp","answer":"④","explanation":"해설\t|\t자료에서 한글 맞춤법 통일안을 발표하였다는 점, \n『우리말(조선말) 큰사전』 편찬을 시도하였으나 일제의 탄\n압으로 중단되었다는 점 등을 통해 밑줄 친 ‘이 단체’는 조\n선어 학회임을 알 수 있다. 조선어 학회는 표준어 표기법\n을 제정하였다.\n오답\t피하기\t|\t① 한성순보는 1883년 박문국에서 발간하였\n다. ② 수원 화성은 조선 정조 시기에 축조되었다. ③ 잡\n지 『근우』는 근우회에서 발행하였다. ⑤ 6·10 만세 운동\n은 학생들의 주도로 전개되었다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":20,"printedPage":19,"answerPage":22},{"id":"ebs-07-03","unit":7,"number":3,"type":"choice","title":"3. 다음 사건이 일어난 시기를 연표에서 옳게 고른 것은?","text":"3. 다음 사건이 일어난 시기를 연표에서 옳게 고른 것은?\n\n\n 일제는 한글 연구로 민족의식이 고취되는 것을 막\n\n 기 위해 조선어 학회를 독립운동 단체로 규정하여,\n\n 19△△년 조선어 학회 회원을 대거 검거해 재판에\n\n 회부한 사건이 일어났다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n  을미   국권     3·1   만주  중일 전쟁   8·15\n  사변   피탈   운동   사변   발발   광복\n\n① (가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-07-03.webp","answer":"⑤","explanation":"해설\t|\t일제가 한글 연구로 민족의식이 고취되는 것을 막\n기 위해 조선어 학회를 독립운동 단체로 규정하였다는 \n점, 조선어 학회 회원을 대거 검거해 재판에 회부하였다\n는 점 등을 통해 자료는 1940년대에 있었던 조선어 학회 \n사건임을 알 수 있다. 중일 전쟁 발발은 1937년, 8·15 광\n복은 1945년에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":20,"printedPage":19,"answerPage":22},{"id":"ebs-07-04","unit":7,"number":4,"type":"short","title":"4. (가)에 해당하는 인물을 쓰시오.","text":"4. (가)에 해당하는 인물을 쓰시오.\n\n\n       (가)    이/가 자신이 지은 『한국통사』를 주어\n\n 읽게 하고 또 말하기를 “내가 『한국독립운동지혈\n\n 사』를 저술하여 이미 완성하였으니 선생께서 나를\n\n 위해 서문을 써 주시오.”라고 하였다. 이미 그 사람\n\n 을 만나 보고, 말하는 것을 듣고, 또 쓴 책을 읽으\n\n 니, 슬픔과 기쁨을 어찌할 수 없다. 슬퍼한 것은 한\n\n 국에 ‘아픈 역사[통사(痛史)]’가 있기 때문이고, 기\n\n 뻐한 것은 한국에 ‘독립운동사’가 있기 때문이다.\n\n\n                                      (                        )","image":"assets/questions/ebs-07-04.webp","answer":"박은식","explanation":"해설\t|\t자료에서 아픈 역사라는 의미가 담긴 『한국통사』를 \n지었다는 점, 『한국독립운동지혈사』를 저술하였다는 점 \n등을 통해 (가) 인물은 박은식임을 알 수 있다. 박은식은 \n역사 연구에서 민족과 민족정신을 강조하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":20,"printedPage":19,"answerPage":22},{"id":"ebs-07-05","unit":7,"number":5,"type":"choice","title":"5. 다음을 저술한 인물의 활동으로 옳은 것은?","text":"5. 다음을 저술한 인물의 활동으로 옳은 것은?\n\n\n 역사란 무엇인가? 인류 사회의 아(我)와 비아(非我)\n\n 의 투쟁이 시간부터 발전하며 공간부터 확대하는\n\n 심적 활동 상태의 기록이니 …… 조선사라 하면 조\n\n 선 민족이 그리되어 온 상태의 기록이다.\n\n                       - 『조선상고사』 -\n\n\n① 동학을‌   창시하였다.\n\n② ‌어린이날을 제정하였다.\n\n③ ‌조선사연구초를 지었다.\n\n④ ‌헤이그 특사로 파견되었다.\n\n⑤ ‌청산리 전투를 승리로 이끌었다.","image":"assets/questions/ebs-07-05.webp","answer":"③","explanation":"해설\t|\t자료에서 역사를 아와 비아의 투쟁으로 보았다는 \n점, 『조선상고사』의 내용이라는 점 등을 통해 해당 인물이 \n신채호임을 알 수 있다. 민족주의 사학을 발전시킨 신채\n호는 『조선사연구초』를 지었다.\n오답\t피하기\t|\t① 최제우, ② 방정환 등을 중심으로 한 천도\n교 소년회, ④ 이상설, 이준, 이위종, ⑤ 김좌진이 이끄는 \n북로 군정서와 홍범도가 이끄는 대한 독립군 등 독립군 \n연합 부대에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":21,"printedPage":20,"answerPage":22},{"id":"ebs-07-06","unit":7,"number":6,"type":"choice","title":"6. (가)에 들어갈 내용으로 옳은 것은?","text":"6. (가)에 들어갈 내용으로 옳은 것은?\n\n\n 일제는 식민 통치를 정당화하기 위해 우리의 역사\n\n 를 왜곡하였다. 조선사 편수회를 통해 식민 사관\n\n 을 유포하여 식민 통치의 정당화를 시도하였다.\n\n       (가)    은/는 한국이 중세 봉건 사회로 발전\n\n 하지 못한 채 고대 사회 수준에 머물러 있다는 내용\n\n 이다.\n\n\n① 당파성론‌\n\n② ‌타율성론\n\n③ ‌정체성론\n\n④ ‌동도서기론\n\n⑤ ‌왜양일체론","image":"assets/questions/ebs-07-06.webp","answer":"③","explanation":"해설\t|\t자료에서 일제가 식민 통치를 정당화하기 위해 우리 \n역사를 왜곡하였다는 점, 조선사 편수회를 통해 식민 사관\n을 유포하였다는 점, 한국이 중세 봉건 사회로 발전하지 \n못한 채 고대 사회 수준에 머물러 있다는 내용 등을 통해 \n(가)에는 정체성론이 들어가야 한다는 것을 알 수 있다.\n오답\t피하기\t|\t①, ② 일제의 식민 사관에 해당하는 내용이\n지만, 제시된 자료와는 관련이 없다. ④, ⑤ 조선 시대에 \n제기되었다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":21,"printedPage":20,"answerPage":22},{"id":"ebs-07-07","unit":7,"number":7,"type":"short","title":"7. (가)에 들어갈 인물을 쓰시오.","text":"7. (가)에 들어갈 인물을 쓰시오.\n\n    ▒ 인물 카드 - 일제 강점기 독립운동가 편\n\n •이름:      (가)\n\n •주요 활동\n\n     - 의열단에 가입하는 등 독립운동을 함.\n\n     - 대구 형무소에서 수감 생활을 함.\n\n     - 청포도, 광야 등의 시를 남김.\n\n\n                                      (                        )","image":"assets/questions/ebs-07-07.webp","answer":"이육사","explanation":"해설\t|\t자료에서 독립운동을 했다는 점, 수감 생활을 했\n다는 점, 청포도·광야 등의 시를 남겼다는 점 등을 통해 \n(가) 인물은 이육사임을 알 수 있다. 일제 강점기 이육사\n는 저항 문학 작품을 남겼다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":21,"printedPage":20,"answerPage":22},{"id":"ebs-07-08","unit":7,"number":8,"type":"choice","title":"8. (가)에 들어갈 내용으로 옳은 것은?","text":"8. (가)에 들어갈 내용으로 옳은 것은?\n\n\n\n\n\n 영화      (가)     의 출연진 모습이 담긴 사진이\n\n 다. 사진 속에는      (가)    을/를 제작한 나운규\n\n 의 모습도 찍혀 있다. 이 영화는 우리 민족의 슬픔\n\n 과 정서를 상징적으로 반영하여 크게 흥행하였다.\n\n\n① ‌반달\n\n② ‌서시\n\n③ ‌아리랑\n\n④ ‌삼천리\n\n⑤ ‌봉오동 전투","image":"assets/questions/ebs-07-08.webp","answer":"③","explanation":"해설\t|\t자료에서 출연진의 모습이 담긴 사진이라는 점, 나\n운규가 제작하였다는 점, 우리 민족의 슬픔과 정서를 상\n징적으로 반영하였다는 점 등을 통해 (가)는 아리랑임을 \n알 수 있다.\n오답\t피하기\t|\t① 반달은 윤극영이 만든 동요이다. ② 서시\n는 윤동주가 남긴 시이다. ④ 삼천리는 일제 강점기에 발\n행된 잡지이다. ⑤ 봉오동 전투는 1920년 독립군 연합 부\n대가 일본군에 승리한 전투이다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":21,"printedPage":20,"answerPage":22},{"id":"blank-07","unit":7,"number":9,"type":"blank","title":"한국사도 세계사의 보편적 발전 법칙에 따라 발전했다고 주장한 사회 경제 사학자는 ____이다.","text":"한국사도 세계사의 보편적 발전 법칙에 따라 발전했다고 주장한 사회 경제 사학자는 ____이다.","answer":"백남운","explanation":"백남운은 조선사회경제사 등을 통해 식민 사관의 정체성론을 비판했다.","criteria":[],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":32},{"id":"essay-07","unit":7,"number":10,"type":"essay","title":"조선어 학회의 두 가지 활동과 그 역사적 의미를 설명하시오.","text":"조선어 학회의 두 가지 활동과 그 역사적 의미를 설명하시오.","answer":"조선어 학회는 한글 맞춤법 통일안을 제정하고 우리말 큰사전 편찬을 추진했다. 일제의 민족 말살 정책에 맞서 우리말과 글을 정비하고 민족의 문화와 정체성을 지키려는 활동이었다.","explanation":"조선어 학회는 한글 맞춤법 통일안을 제정하고 우리말 큰사전 편찬을 추진했다. 일제의 민족 말살 정책에 맞서 우리말과 글을 정비하고 민족의 문화와 정체성을 지키려는 활동이었다.","criteria":["한글 맞춤법 통일안 제정","우리말 큰사전 편찬 추진","민족 문화와 정체성 수호"],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":32},{"id":"ebs-08-01","unit":8,"number":1,"type":"choice","title":"1. (가) 독립군에 대한 설명으로 옳은 것은?","text":"1. (가) 독립군에 대한 설명으로 옳은 것은?\n\n\n\n\n                     하얼빈\n              (가)  의 전투 지역\n         (총사령관 지청천)\n                창춘     닝안\n                       (장춘) 지린 (영안)  블라디보스토크\n                             (길림)  옌지\n                                   (연길)\n                    펑톈(봉천)\n                          청진\n\n\n                 신의주\n\n\n            황 해            동 해\n\n\n① 신흥‌  강습소를 설립하였다.\n\n② ‌청산리 대첩에서 활약하였다.\n\n③ ‌신미양요에서 미군에 항전하였다.\n\n④ ‌쌍성보 전투에서 일본군을 격퇴하였다.\n\n⑤ ‌최초로 중국 관내에서 결성된 무장 부대였다.","image":"assets/questions/ebs-08-01.webp","answer":"④","explanation":"해설\t| 자료에서 중국 북만주 지역에서 여러 전투들을 치\n른 점 등을 통해 (가) 독립군은 지청천이 지휘한 한국 독\n립군임을 알 수 있다. 한국 독립군은 쌍성보 전투에서 중\n국 호로군과 연합하여 일본군을 격퇴하였다.\n오답\t피하기\t|\t① 신민회에 해당한다. ② 청산리 대첩에서\n는 김좌진이 이끄는 북로 군정서와 홍범도가 이끄는 대한 \n독립군 등 독립군 연합 부대가 활약하였다. ③ 어재연이 \n이끄는 부대 등, ⑤ 조선 의용대에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":23,"printedPage":22,"answerPage":25},{"id":"ebs-08-02","unit":8,"number":2,"type":"choice","title":"2. (가)에 해당하는 독립군에 대한 설명으로 옳은 것은?","text":"2. (가)에 해당하는 독립군에 대한 설명으로 옳은 것은?\n\n\n       국민부(남만주)     조선 혁명당 산하    (가)\n\n\n     혁신 의회(북만주)    한국 독립당 산하 한국 독립군\n\n\n① 지청천이‌    지휘하였다.\n\n② ‌전주성을 점령하였다.\n\n③ ‌13도 창의군을 결성하였다.\n\n④ ‌한산도 대첩에서 활약하였다.\n\n⑤ ‌흥경성 전투에서 일본군을 격퇴하였다.","image":"assets/questions/ebs-08-02.webp","answer":"⑤","explanation":"해설\t|\t자료에서 조선 혁명당 산하의 독립군으로 편성되어 \n있는 점 등을 통해 (가)는 조선 혁명군임을 알 수 있다. 조선 \n혁명군은 양세봉의 지휘로 항일 무장 투쟁을 전개하였다. \n조선 혁명군은 중국 의용 부대와 한중 연합 작전을 펼쳐 영\n릉가 전투, 흥경성 전투 등에서 일본군을 격퇴하였다.\n오답\t피하기\t|\t① 한국 독립군 등, ② 동학 농민군, ③ 정미\n의병, ④ 이순신이 이끄는 조선의 수군 등에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":23,"printedPage":22,"answerPage":25},{"id":"ebs-08-03","unit":8,"number":3,"type":"choice","title":"3. 다음 자료의 합의가 이루어진 시기를 연표에서 옳게 고","text":"3. 다음 자료의 합의가 이루어진 시기를 연표에서 옳게 고\n른 것은?\n\n\n   <한국 독립군과 항일 중국군의 합의 내용>\n\n •한중 양군은 최악의 상황이 오는 경우에도 장기\n\n  간 항전할 것을 맹세한다.\n\n •전시의 후방 전투 훈련은 한국 장교가 맡고 한국\n\n  군에 필요한 군수품 등은 중국군이 공급한다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n  운요호   을미   국권     3·1   만주    8·15\n  사건   사변   피탈   운동   사변   광복\n\n① (가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-08-03.webp","answer":"⑤","explanation":"해설\t|\t한국 독립군과 항일 중국군 사이의 합의 내용이라\n는 점, 전시 후방 전투 훈련은 한국 장교가 맡고 한국군에 \n필요한 군수품 등은 중국군이 공급한다는 점 등을 통해 \n자료는 1930년대 전반 만주 지역에서 독립군 부대의 한중 \n연합 작전과 관련된 것임을 알 수 있다. 만주 사변은 1931\n년, 8·15 광복은 1945년에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":23,"printedPage":22,"answerPage":25},{"id":"ebs-08-04","unit":8,"number":4,"type":"short","title":"4. (가)에 해당하는 단체의 명칭을 쓰시오.","text":"4. (가)에 해당하는 단체의 명칭을 쓰시오.\n\n\n\n\n\n 자료는 일제 감시 대상 인물 카드에 있는\n\n       (가)     의 단원 이봉창의 모습이다. 이봉창은\n\n 일본 도쿄에서 일본 국왕이 타고 가던 마차를 향해\n\n 수류탄을 던지는 의거를 단행하였다.\n\n\n                                      (                        )","image":"assets/questions/ebs-08-04.webp","answer":"한인\t애국단","explanation":"해설\t|\t자료에서 일제 감시 대상 인물 카드에 이봉창이 있\n다는 점, 이봉창이 단원이라는 점, 이봉창이 일본 도쿄에\n서 일본 국왕이 타고 가던 마차를 향해 수류탄을 던지는 \n의거를 단행하였다는 점 등을 통해 (가) 단체는 한인 애국\n단임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":23,"printedPage":22,"answerPage":25},{"id":"ebs-08-05","unit":8,"number":5,"type":"choice","title":"5. 밑줄 친 ‘의거’가 있었던 시기를 연표에서 옳게 고른 것","text":"5. 밑줄 친 ‘의거’가 있었던 시기를 연표에서 옳게 고른 것\n은?\n\n\n\n\n\n 자료는 윤봉길 의사의 상하이 훙커우 공원 의거 당\n\n 시 모습이 담긴 사진이다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n  을사   국권     3·1   만주  중일 전쟁   8·15\n  늑약   피탈   운동   사변   발발   광복\n\n① (가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-08-05.webp","answer":"④","explanation":"해설\t|\t자료에서 윤봉길 의사가 상하이 훙커우 공원에서 \n의거를 일으켰다는 점 등을 통해 밑줄 친 ‘의거’는 1932년\n에 있었던 사건임을 알 수 있다. 만주 사변은 1931년, 중\n일 전쟁 발발은 1937년에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":24,"printedPage":23,"answerPage":25},{"id":"ebs-08-06","unit":8,"number":6,"type":"choice","title":"6. 밑줄 친 ‘이 단체’에 대한 설명으로 옳은 것은?","text":"6. 밑줄 친 ‘이 단체’에 대한 설명으로 옳은 것은?\n\n\n 대한민국 임시 정부에 활기      맞아. 특히 윤봉길의 의거\n 를 불어넣기 위해 만들어진    는 중국 국민당 정부가 대\n 이 단체에서 이봉창과 윤봉    한민국 임시 정부를 지원\n 길이 단원으로 활동하였어.     하는 계기가 되었지.\n\n\n\n\n\n① 김구가‌   조직하였다.\n\n② ‌독립문을 건립하였다.\n\n③ ‌오산 학교를 설립하였다.\n\n④ ‌병인양요에서 항전하였다.\n\n⑤ ‌국채 보상 운동을 주도하였다.","image":"assets/questions/ebs-08-06.webp","answer":"①","explanation":"해설\t|\t자료에서 대한민국 임시 정부에 활기를 불어넣기 \n위해 만들어졌다는 점, 이봉창과 윤봉길이 단원으로 활동\n하였다는 점, 윤봉길의 의거는 중국 국민당 정부가 대한\n민국 임시 정부를 지원하는 계기가 되었다는 점 등을 통\n해 밑줄 친 ‘이 단체’는 한인 애국단임을 알 수 있다. 한인 \n애국단은 김구가 상하이에서 1931년에 조직하였다.\n오답\t피하기\t|\t② 독립 협회, ③ 신민회, ④ 양헌수가 이끄\n는 부대 등, ⑤ 국채 보상 기성회 등에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":24,"printedPage":23,"answerPage":25},{"id":"ebs-08-07","unit":8,"number":7,"type":"choice","title":"7. 밑줄 친 ‘이 부대’에 대한 설명으로 옳은 것은?","text":"7. 밑줄 친 ‘이 부대’에 대한 설명으로 옳은 것은?\n\n\n 중일 전쟁 발발 후 우리 당은 이 부대를 조직하여\n\n 직접 중국의 대일 항전에 참가해 빛나는 전적을 창\n\n 조하였고, …… 조선 민족의 자유 해방을 위해 영\n\n 웅적 투쟁을 할 뿐만 아니라, 중국의 승리를 위해\n\n 마땅히 노력을 다함을 증명하는 것이다.\n\n      - 민족 혁명당 창립 제8주년 기념 선언, 1943 -\n\n\n① ‌동북 9성을 축조하였다.\n\n② ‌우금치 전투에서 활약하였다.\n\n③ ‌양세봉을 총사령관으로 삼았다.\n\n④ ‌일부가 한국광복군에 합류하였다.\n\n⑤ ‌명군과 함께 평양성을 탈환하였다.","image":"assets/questions/ebs-08-07.webp","answer":"④","explanation":"해설\t|\t자료에서 민족 혁명당이 조직하였다는 점, 중일 전\n쟁 발발 이후로 시기가 제시된 점 등을 통해 밑줄 친 ‘이 \n부대’는 1938년에 결성된 조선 의용대임을 알 수 있다. 조\n선 의용대의 김원봉과 일부 대원은 한국광복군에 합류하\n였다.\n오답\t피하기\t|\t① 고려는 여진을 정벌하고 동북 9성을 쌓았\n다. ② 동학 농민군은 우금치에서 일본군과 관군으로 구\n성된 연합 부대와 전투를 벌였다. ③ 조선 혁명군은 양세\n봉을 총사령관으로 삼았다. ⑤ 임진왜란 당시 관군은 명\n군과 함께 평양성을 탈환하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":24,"printedPage":23,"answerPage":25},{"id":"ebs-08-08","unit":8,"number":8,"type":"choice","title":"8. (가) 부대의 명칭으로 옳은 것은?","text":"8. (가) 부대의 명칭으로 옳은 것은?\n\n\n 자료는 1938년 중국 관내의 최초 한인 무장 부대로 창설된\n\n       (가)      의 창설 기념 사진입니다. 사진에서 이 부대를 이\n\n 끌었던 김원봉의 모습도 확인할 수 있습니다.\n\n\n\n\n\n① ‌의열단\n\n② ‌별무반\n\n③ ‌별기군\n\n④ ‌조선 의용대\n\n⑤ ‌13도 창의군","image":"assets/questions/ebs-08-08.webp","answer":"④","explanation":"해설\t|\t자료에서 1938년 중국 관내의 최초 한인 무장 부대\n로 창설되었다는 점, 김원봉이 이끌었다는 점 등을 통해 \n(가) 부대는 조선 의용대임을 알 수 있다. ","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":24,"printedPage":23,"answerPage":25},{"id":"blank-08","unit":8,"number":9,"type":"blank","title":"김구가 1931년 조직하고 이봉창·윤봉길이 활동한 단체는 ____이다.","text":"김구가 1931년 조직하고 이봉창·윤봉길이 활동한 단체는 ____이다.","answer":"한인 애국단","explanation":"1919년 김원봉 등이 조직한 의열단과 지도자·창립 연도를 구별한다.","criteria":[],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":37},{"id":"essay-08","unit":8,"number":10,"type":"essay","title":"한국 독립군과 조선 혁명군의 지휘관·활동 지역을 비교하고 공통된 투쟁 방식을 설명하시오.","text":"한국 독립군과 조선 혁명군의 지휘관·활동 지역을 비교하고 공통된 투쟁 방식을 설명하시오.","answer":"지청천의 한국 독립군은 북만주에서 활동했고 양세봉의 조선 혁명군은 남만주에서 활동했다. 두 부대는 중국의 항일 세력과 연합하여 일본군에 맞서는 한중 연합 작전을 전개했다.","explanation":"지청천의 한국 독립군은 북만주에서 활동했고 양세봉의 조선 혁명군은 남만주에서 활동했다. 두 부대는 중국의 항일 세력과 연합하여 일본군에 맞서는 한중 연합 작전을 전개했다.","criteria":["지청천·한국 독립군·북만주","양세봉·조선 혁명군·남만주","중국 항일 세력과 연합"],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":37},{"id":"ebs-09-01","unit":9,"number":1,"type":"choice","title":"1. (가) 무장 부대에 대한 설명으로 옳은 것은?","text":"1. (가) 무장 부대에 대한 설명으로 옳은 것은?\n\n\n 드디어 3개월간의 제1기생 50명의 미국 전략 정보\n\n  국[OSS] 특수 공작 훈련이 끝났다. 나는 무전 기술\n\n 등의 시험에서 괜찮은 성적을 받았고 국내로 침투\n\n 하여 모든 공작을 훌륭하게 수행할 수 있는 자신을\n\n 얻었다. …… 제1기생 훈련이 성공적으로 끝나자\n\n 우리는 말할 것도 없고 미군도 대만족하여 즉각 국\n\n 내로 침투시킬 계획을 작성하였다.\n\n     -      (가)     의 국내 진공 작전 참가자 회고 -\n\n\n① 충칭에서‌    창설되었다.\n\n② ‌병인양요에서 활약하였다.\n\n③ ‌위화도 회군을 단행하였다.\n\n④ ‌조선 의용군으로 개편되었다.\n\n⑤ ‌김원봉의 주도로 만주에서 조직되었다.","image":"assets/questions/ebs-09-01.webp","answer":"①","explanation":"해설\t| 자료에서 ‘나’란 인물이 미국 전략 정보국[OSS]의 \n훈련 과정을 마쳤다고 한 점, 국내로 침투할 계획을 작성\n하였다는 점 등을 통해 (가) 무장 부대는 한국광복군임을 \n알 수 있다. 한국광복군은 1940년 충칭에서 창설되었다.\n오답\t피하기\t|\t② 병인양요는 조선 시대, ③ 위화도 회군은 \n고려 시대에 해당한다. ④ 조선 의용대 화북 지대는 조선 \n의용군으로 개편되었다. ⑤ 의열단은 김원봉의 주도로 만\n주에서 조직되었다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":26,"printedPage":25,"answerPage":28},{"id":"ebs-09-02","unit":9,"number":2,"type":"short","title":"2. 밑줄 친 ‘이 부대’의 명칭을 쓰시오.","text":"2. 밑줄 친 ‘이 부대’의 명칭을 쓰시오.\n\n\n\n\n\n 자료는 미얀마·인도 전선에 파견된 이 부대의 모\n\n 습이 담긴 사진이다. 이 부대는 영국군의 요청에\n\n 따라 미얀마·인도 전선에 파견되었다. 이곳에서\n\n 이 부대는 일본군 포로 심문과 선전 활동 등을 담\n\n 당하였다.\n\n\n\n                                      (                        )","image":"assets/questions/ebs-09-02.webp","answer":"한국광복군","explanation":"해설\t|\t자료에서 영국군의 요청에 따라 미얀마·인도 전선\n에 파견되었다는 점, 포로 심문과 선전 활동 등을 담당하\n였다는 점 등을 통해 밑줄 친 ‘이 부대’는 한국광복군임을 \n알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":26,"printedPage":25,"answerPage":28},{"id":"ebs-09-03","unit":9,"number":3,"type":"choice","title":"3. 밑줄 친 ‘창설’이 있었던 시기를 연표에서 옳게 고른 것","text":"3. 밑줄 친 ‘창설’이 있었던 시기를 연표에서 옳게 고른 것\n은?\n\n\n\n\n\n 자료는 ◯◯◯◯◯의 성립 전례식 사진이다. 대한\n\n 민국 임시 정부 산하 부대인 ◯◯◯◯◯은 중국 국\n\n 민당 정부의 후원을 받아 창설되었다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n  을사   국권     3·1   만주  중일 전쟁   8·15\n  늑약   피탈   운동   사변   발발   광복\n\n① ‌(가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-09-03.webp","answer":"⑤","explanation":"해설\t|\t대한민국 임시 정부 산하 부대라는 점, 중국 국민\n당 정부의 후원을 받아 창설되었다는 점 등을 통해 자료\n는 한국광복군에 대한 것임을 알 수 있다. 한국광복군은 \n1940년에 창설되었다. 중일 전쟁 발발은 1937년, 8·15 \n광복은 1945년에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":26,"printedPage":25,"answerPage":28},{"id":"ebs-09-04","unit":9,"number":4,"type":"choice","title":"4. 다음 성명을 발표한 단체에 대한 설명으로 옳은 것은?","text":"4. 다음 성명을 발표한 단체에 대한 설명으로 옳은 것은?\n\n\n 우리는 중국, 영국, 미국 등이 일본에 전쟁을 선포\n\n 한 것이 일본을 물리치고 동아시아를 재건하는 가\n\n 장 유효한 수단이 됨을 축하하며, 이에 다음과 같\n\n 이 성명하노라.\n\n  1. ‌한국 전 인민은 현재 이미 반침략 전선에 참가하\n\n  였으니 한 개의 전투 단위로서 선전한다.\n\n  3. ‌한국, 중국 및 서태평양으로부터 왜구를 완전히\n\n  구축하기 위하여 최후의 승리를 얻을 때까지 혈\n\n   전한다.\n\n\n① ‌모금을 통해 독립문을 건립하였다.\n\n② ‌김상옥 등의 의거 활동을 주도하였다.\n\n③ ‌삼원보에 독립운동 기지를 건설하였다.\n\n④ ‌조선 혁명 선언을 활동 지침으로 삼았다.\n\n⑤ ‌충칭에 정착한 후 건국 강령을 발표하였다.","image":"assets/questions/ebs-09-04.webp","answer":"⑤","explanation":"해설\t|\t자료는 1941년 태평양 전쟁이 발발하자 대한민국 \n임시 정부가 발표한 대일 선전 포고에 해당한다. 대한민\n국 임시 정부는 1940년 충칭에 정착하여 조직을 정비하였\n고 한국광복군을 창설하여 항일 전쟁을 전개하였다. 대한\n민국 임시 정부는 충칭에 정착한 이후 새로운 국가에 대\n한 구체적인 모습을 제시한 건국 강령을 발표하였다.\n오답\t피하기\t|\t① 독립문은 독립 협회가 건립하였다. ② 김\n상옥 등은 의열단의 단원으로 의거 활동을 전개하였다. \n③ 신민회는 만주 삼원보에 독립운동 기지를 건설하였다. \n④ 의열단은 신채호가 작성한 「조선 혁명 선언」 을 활동 지\n침으로 삼았다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":26,"printedPage":25,"answerPage":28},{"id":"ebs-09-05","unit":9,"number":5,"type":"choice","title":"5. 다음 강령을 발표한 단체에 대한 설명으로 옳은 것은?","text":"5. 다음 강령을 발표한 단체에 대한 설명으로 옳은 것은?\n\n\n 제3장 건국\n\n  2. ‌삼균 제도를 골자로 한 헌법을 실시하여 정치·\n\n  경제·교육의 민주적 시설로 실제상 균형을 도\n\n   모하며, 전국의 토지와 대생산 기관의 국유가\n\n  완성되고 ……\n\n  4. ‌보통 선거제는 만 18세 이상 남녀로 선거권을\n\n  행사하되 신앙, 교육, 거주 기간, 사회 출신, 재\n\n  정 상황과 과거 행동을 분별치 아니하며 ……\n\n\n① 원수부를‌    설치하였다.\n\n② ‌한국광복군을 창설하였다.\n\n③ ‌동학 농민 운동을 주도하였다.\n\n④ ‌국가 총동원법을 제정, 공포하였다.\n\n⑤ ‌조선 민족 전선 연맹을 조직하였다.","image":"assets/questions/ebs-09-05.webp","answer":"②","explanation":"해설\t|\t자료는 1941년에 대한민국 임시 정부가 발표한 건\n국 강령이다. 이를 통해 대한민국 임시 정부는 광복 이후\n에 건설될 새로운 국가의 모습을 구체적으로 제시하였다. \n대한민국 임시 정부는 적극적인 대일 항전을 위해 한국광\n복군을 창설하였다.\n오답\t피하기\t|\t① 대한 제국은 원수부를 설치하였다. ③ 전\n봉준 등이 이끄는 동학 농민군은 동학 농민 운동을 주도\n하였다. ④ 중일 전쟁을 일으킨 일제는 1938년 국가 총동\n원법을 제정, 공포하였다. ⑤ 조선 민족 전선 연맹은 민족 \n혁명당의 주도로 결성되었다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":27,"printedPage":26,"answerPage":28},{"id":"ebs-09-06","unit":9,"number":6,"type":"choice","title":"6. 밑줄 친 ‘동맹’에 해당하는 단체에 대한 설명으로 옳은 ","text":"6. 밑줄 친 ‘동맹’에 해당하는 단체에 대한 설명으로 옳은\n것은?\n\n\n     옌안에서 수립된 동맹의 강령, 1942\n\n   1. 본 동맹은 조선에 대한 일본 제국주의의 지배\n\n  를 전복하고 독립 자유의 조선 민주 공화국을\n\n  수립할 목적으로 다음 임무를 실현하기 위하여\n\n   싸운다.\n\n      (1) ‌전 국민의 보통 선거에 의한 민주 정권의 수립\n\n      (2) 조선에‌   있는 일본 제국주의자의 일체 자산\n\n    및 토지를 몰수하고, 일본 제국주의와 밀접\n\n    한 관계에 있는 대기업을 국영으로 귀속하\n\n      며, 토지 분배를 실행한다.\n\n\n① ‌정미의병을 일으켰다.\n\n② ‌관민 공동회를 개최하였다.\n\n③ ‌여운형의 주도로 조직되었다.\n\n④ ‌2·8 독립 선언을 발표하였다.\n\n⑤ ‌산하에 조선 의용군을 편성하였다.","image":"assets/questions/ebs-09-06.webp","answer":"⑤","explanation":"해설\t|\t자료에서 옌안에서 수립된 단체가 1942년에 강령\n을 발표하였다는 점 등을 통해 밑줄 친 ‘동맹’은 조선 독립 \n동맹임을 알 수 있다. 조선 독립 동맹은 조선 의용대 화북 \n지대를 개편하여 조선 의용군을 편성하였다.\n오답\t피하기\t|\t①, ② 국권 피탈 이전에 있었던 사실이다. \n③ 여운형의 주도로 국내에서 조선 건국 동맹이 조직되었\n다. ④ 1919년 일본 도쿄에서 한국인 유학생들이 2·8 독\n립 선언을 발표하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":27,"printedPage":26,"answerPage":28},{"id":"ebs-09-07","unit":9,"number":7,"type":"short","title":"7. 밑줄 친 ‘이 회담’의 명칭을 쓰시오.","text":"7. 밑줄 친 ‘이 회담’의 명칭을 쓰시오.\n\n\n 제2차 세계 대전 중인 1943년에 미국·영국·중국\n\n 의 정상이 이 회담을 개최하였다. 여기에서 3국 정\n\n 상은 일본이 무조건 항복할 때까지 싸우기로 하고,\n\n 적절한 절차를 거쳐 한국을 자유 독립하게 할 것을\n\n 확인하였다. 이 회담에서 한국의 독립이 처음 거론\n\n 된 것이었다.\n\n\n                                      (                        )","image":"assets/questions/ebs-09-07.webp","answer":"카이로\t회담","explanation":"해설\t|\t자료에서 1943년에 미국·영국·중국 정상이 모여 \n개최하였다는 점, 적절한 절차를 거쳐 한국을 독립시키기\n로 한 점, 한국의 독립이 처음으로 거론되었다는 점 등을 \n통해 밑줄 친 ‘이 회담’은 카이로 회담임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":27,"printedPage":26,"answerPage":28},{"id":"ebs-09-08","unit":9,"number":8,"type":"choice","title":"8. 다음 선언이 발표된 시기를 연표에서 옳게 고른 것은?","text":"8. 다음 선언이 발표된 시기를 연표에서 옳게 고른 것은?\n\n\n  6. ‌우리는 무책임한 군국주의가 세상에서 구축될 때\n\n  까지는 평화, 안전, 정의의 신질서가 존립할 수\n\n  없음을 주장하는 바이므로 일본 국민들을 기만하\n\n  여 세계 정복의 허용을 종용하는 과오를 범하게\n\n  한 권력 및 세력은 영구히 제거되어야 한다.\n\n  8. ‌카이로 선언의 조항은 이행될 것이며, 일본의\n\n  주권을 혼슈, 홋카이도, 규슈, 시코쿠 및 연합국\n\n  이 결정할 여러 작은 섬에 국한된다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n  강화도  국권     3·1   신간회   국가    8·15\n  조약   피탈   운동   결성  총동원법  광복\n                       제정\n\n① (가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-09-08.webp","answer":"⑤","explanation":"해설\t|\t카이로 선언의 조항이 이행될 것이라는 점, 일본의 \n주권 범위를 정했다는 점 등을 통해 자료는 1945년에 발\n표된 포츠담 선언임을 알 수 있다. 포츠담 선언 발표 이후 \n일본은 무조건 항복을 선언하였고, 우리는 8월 15일에 광\n복을 맞이하였다. 국가 총동원법 제정은 1938년, 8·15 \n광복은 1945년에 해당한다. ","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":27,"printedPage":26,"answerPage":28},{"id":"blank-09","unit":9,"number":9,"type":"blank","title":"1943년 미국·영국·중국이 한국의 독립을 약속한 선언은 ____이다.","text":"1943년 미국·영국·중국이 한국의 독립을 약속한 선언은 ____이다.","answer":"카이로 선언","explanation":"1945년 포츠담 선언은 카이로 선언의 이행을 확인했다.","criteria":[],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":42},{"id":"essay-09","unit":9,"number":10,"type":"essay","title":"한국광복군의 대외 협력 활동 두 가지와 국내 진공 작전이 실행되지 못한 이유를 설명하시오.","text":"한국광복군의 대외 협력 활동 두 가지와 국내 진공 작전이 실행되지 못한 이유를 설명하시오.","answer":"한국광복군은 인도·미얀마 전선에서 영국군과 협력하여 선전과 포로 심문 등에 참여했다. 미국 OSS와는 국내 진공 작전을 준비했지만 작전 실행 전에 일본이 항복하여 국내 진공은 이루어지지 못했다.","explanation":"한국광복군은 인도·미얀마 전선에서 영국군과 협력하여 선전과 포로 심문 등에 참여했다. 미국 OSS와는 국내 진공 작전을 준비했지만 작전 실행 전에 일본이 항복하여 국내 진공은 이루어지지 못했다.","criteria":["영국군과 인도·미얀마 전선 협력","미국 OSS와 국내 진공 준비","일본 항복으로 작전 미실행"],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":42},{"id":"ebs-10-01","unit":10,"number":1,"type":"choice","title":"1. (가) 단체의 명칭으로 옳은 것은?","text":"1. (가) 단체의 명칭으로 옳은 것은?\n\n\n 광복 직후 여운형은 조선 건국 동맹을 바탕으로 안\n\n 재홍과 함께 독립 국가 건설을 위한 준비 기관으로\n\n       (가)    을/를 결성하였다.      (가)    은/는\n\n 전국 각지에 지부를 두고 치안 유지와 행정 업무를\n\n 담당하였다.\n\n\n① 독립‌  협회\n\n② ‌관민 공동회\n\n③ ‌미소 공동 위원회\n\n④ ‌황국 중앙 총상회\n\n⑤ ‌조선 건국 준비 위원회","image":"assets/questions/ebs-10-01.webp","answer":"⑤","explanation":"해설\t| 자료에서 광복 직후 여운형이 조선 건국 동맹을 바\n탕으로 안재홍과 함께 독립 국가 건설을 위한 준비 기관\n으로 결성하였다는 점, 전국 각지에 지부를 두고 치안 유\n지와 행정 업무를 담당하였다는 점 등을 통해 (가) 단체는 \n조선 건국 준비 위원회임을 알 수 있다.\n오답\t피하기\t|\t①, ②, ④ 국권 피탈 이전에 있었다. ③ 미소 \n공동 위원회는 모스크바 3국 외상 회의에 따라 구성되었다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":29,"printedPage":28,"answerPage":31},{"id":"ebs-10-02","unit":10,"number":2,"type":"choice","title":"2. 밑줄 친 ‘이 회의’의 결정 사항으로 옳은 것만을 <보기>","text":"2. 밑줄 친 ‘이 회의’의 결정 사항으로 옳은 것만을 <보기>\n에서 고른 것은?\n\n\n 카이로·포츠담 선언과 국제 헌장으로 세계에 공\n\n 약한 한국의 독립 부여는 이번 모스크바에서 열린\n\n 이 회의에서 신탁 관리를 결의함으로써 수포로 돌\n\n 아갔다. …… 3천만의 모든 힘을 발휘하여 신탁 관\n\n 리제를 배격하는 국민운동을 전개하여 완전한 자주\n\n 독립을 이루는 날까지 3천만 전 민족의 최후의 피 한\n\n 방울까지라도 흘려서 싸우는 항쟁 개시를 선언한다.\n\n\n      < 보기 >\n ㄱ. ‌헌의 6조를 결의한다.\n\n ㄴ. ‌임시 정부를 수립한다.\n\n ㄷ. ‌미소 공동 위원회를 설치한다.\n\n ㄹ. ‌38도선 이남 지역에서 총선거를 실시한다.\n\n\n① ㄱ,‌ ㄴ    ② ㄱ, ㄷ    ③ ㄴ, ㄷ\n\n④ ‌ㄴ, ㄹ    ⑤ ㄷ, ㄹ","image":"assets/questions/ebs-10-02.webp","answer":"③","explanation":"해설\t|\t자료에서 모스크바에서 열렸다는 점, 신탁 관리를 \n결의했다는 점 등을 통해 밑줄 친 ‘이 회의’는 1945년에 열\n린 모스크바 3국 외상 회의임을 알 수 있다. ㄴ. 모스크\n바 3국 외상 회의에서는 한국인들의 임시 정부 수립을 결\n정하였다. ㄷ. 임시 정부 수립을 지원하기 위한 미소 공동 \n위원회 설치를 결정하였다.\n오답\t피하기\t|\tㄱ. 1898년 열린 관민 공동회에서 헌의 6조가 \n결의되었다. ㄹ. 1948년에 열린 유엔 소총회에서 38도선 \n이남 지역에서의 총선거를 결의하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":29,"printedPage":28,"answerPage":31},{"id":"ebs-10-03","unit":10,"number":3,"type":"choice","title":"3. (가) 위원회에 대한 설명으로 옳은 것은?","text":"3. (가) 위원회에 대한 설명으로 옳은 것은?\n\n\n 이제 무기 휴회된      (가)    이/가 재개될 기색\n\n 도 보이지 않으며, 통일 정부를 고대하나 여의케\n\n 되지 않으니, 우리는 남방(남쪽)만이라도 임시 정\n\n 부, 혹은 위원회 같은 것을 조직하여 38도선 이북\n\n 에서 소련이 철퇴하도록 세계 공론에 호소하여야\n\n 할 것이니, 여러분도 결심하여야 할 것입니다.\n\n\n① ‌독립신문을 발행하였다.\n\n② ‌대한국 국제를 발표하였다.\n\n③ ‌대한 제국 수립을 선포하였다.\n\n④ ‌조선 노농 총동맹을 바탕으로 결성되었다.\n\n⑤ ‌모스크바 3국 외상 회의에 따라 구성되었다.","image":"assets/questions/ebs-10-03.webp","answer":"⑤","explanation":"해설\t|\t자료에서 무기 휴회되었다는 점, 재개될 기색이 보\n이지 않는다는 점 등을 통해 (가) 위원회는 미소 공동 위\n원회임을 알 수 있다. 제1차 미소 공동 위원회가 결렬되\n자, 이승만은 정읍 발언을 통해 남쪽만이라도 먼저 정부\n를 세우자고 주장하였다. 미소 공동 위원회는 모스크바 3\n국 외상 회의에 따라 구성되었다.\n오답\t피하기\t|\t① 독립 협회 등, ② 대한 제국, ③ 고종에 해\n당한다. ④ 조선 노농 총동맹은 일제 강점기에 결성되었다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":29,"printedPage":28,"answerPage":31},{"id":"ebs-10-04","unit":10,"number":4,"type":"short","title":"4. 다음에 해당하는 인물을 쓰시오.","text":"4. 다음에 해당하는 인물을 쓰시오.\n\n\n            <주요 생애>\n\n\n •파리 강화 회의에 파견\n\n •대한민국 임시 정부 부주석 역임\n\n •좌우 합작 위원회 주도\n\n •남북 협상에 참여\n\n\n\n                                      (                        )","image":"assets/questions/ebs-10-04.webp","answer":"김규식","explanation":"해설\t|\t자료에서 파리 강화 회의에 파견된 점, 좌우 합작 \n위원회를 주도한 점, 남북 협상에 참여한 점 등을 통해 해\n당 인물이 김규식임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":29,"printedPage":28,"answerPage":31},{"id":"ebs-10-05","unit":10,"number":5,"type":"choice","title":"5. 다음 원칙이 발표된 시기를 연표에서 옳게 고른 것은?","text":"5. 다음 원칙이 발표된 시기를 연표에서 옳게 고른 것은?\n\n\n  1. ‌모스크바 3국 외상 회의 결정에 의하여 남북을\n\n  통한 좌우 합작으로 민주주의 임시 정부를 수립\n\n  할 것.\n\n  2. ‌미소 공동 위원회의 속개를 요청하는 공동 성명\n\n  을 발표할 것.\n\n  3. ‌몰수, 유조건 몰수, 체감 매상 등으로 토지를 회\n\n  수하여 농민에게 무상으로 분여할 것.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n  국권     3·1   만주    8·15  대한민국   4·19\n  피탈   운동   사변   광복  정부 수립  혁명\n\n① (가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-10-05.webp","answer":"④","explanation":"해설\t|\t자료에서 좌우 합작으로 민주주의 임시 정부를 수\n립할 것이라는 점, 미소 공동 위원회의 속개를 요청한다\n는 점, 토지 개혁을 실시할 것이라는 점 등을 통해 해당 \n원칙은 좌우 합작 7원칙임을 알 수 있다. 좌우 합작 위원\n회는 1946년 좌우 합작 7원칙을 발표하였다. 8·15 광복\n은 1945년, 대한민국 정부 수립은 1948년에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":30,"printedPage":29,"answerPage":31},{"id":"ebs-10-06","unit":10,"number":6,"type":"choice","title":"6. (가) 단체에 대한 설명으로 옳은 것은?","text":"6. (가) 단체에 대한 설명으로 옳은 것은?\n\n\n\n\n\n 가운데의 두 인물은 각각 여운형과 김규식이다. 둘은\n\n 손을 잡으려고 하나 극좌와 극우가 뒤에서 당기며 방\n\n 해하는 장면을 나타내고 있다. 이는      (가)     의\n\n 활동이 겪는 어려움을 풍자한 것이다.\n\n\n① 충칭에서‌    창설되었다.\n\n② ‌105인 사건으로 해체되었다.\n\n③ ‌국내 진공 작전을 계획하였다.\n\n④ ‌광주 학생 항일 운동을 지원하였다.\n\n⑤ ‌좌우 합작을 위한 7원칙을 발표하였다.","image":"assets/questions/ebs-10-06.webp","answer":"⑤","explanation":"해설\t|\t자료에서 여운형과 김규식이 그려져 있다는 점, 극\n좌와 극우가 등장한다는 점 등을 통해 (가) 단체는 좌우 \n합작 위원회임을 알 수 있다. 여운형과 김규식은 중도 세\n력을 중심으로 1946년 좌우 합작 위원회를 결성하였다. \n좌우 합작 위원회는 통일 임시 정부 수립, 유상 매입과 무\n상 분배 원칙에 따른 토지 개혁, 반민족 행위자 처벌 등의 \n내용을 담은 좌우 합작 7원칙을 발표하였다.\n오답\t피하기\t|\t①, ③ 한국광복군, ② 신민회, ④ 신간회에 \n해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":30,"printedPage":29,"answerPage":31},{"id":"ebs-10-07","unit":10,"number":7,"type":"choice","title":"7. 다음 결의가 이루어진 이후에 있었던 사실로 옳은 것","text":"7. 다음 결의가 이루어진 이후에 있었던 사실로 옳은 것\n은?\n\n\n •한국 국민 중에서 대표를 선출하고 한국 독립 문\n\n  제 해결에 참여시키기 위하여 유엔 한국 임시 위\n\n  원단을 설치한다.\n\n •보통 선거와 비밀 투표에 의해 대표를 선출하되\n\n  …… 선거는 위원단의 감시하에 시행되어야 한다.\n\n\n① ‌신간회가 결성되었다.\n\n② ‌을미사변이 일어났다.\n\n③ ‌강화도 조약이 체결되었다.\n\n④ ‌국가 총동원법이 제정되었다.\n\n⑤ ‌대한민국 정부가 수립되었다.","image":"assets/questions/ebs-10-07.webp","answer":"⑤","explanation":"해설\t|\t유엔 한국 임시 위원단을 설치한다는 점, 이들의 감\n시 아래 선거를 실시한다는 점 등을 통해 자료는 1947년\n에 이루어진 유엔 총회의 결의임을 알 수 있다. 제2차 미\n소 공동 위원회가 결렬된 후 유엔 총회에서 한국 문제를 \n다루었고, 자료의 내용이 결의되었다. 이후 1948년 대한\n민국 정부가 수립되었다.\n오답\t피하기\t|\t①, ④ 일제 강점기, ②, ③ 국권 피탈 이전에 \n해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":30,"printedPage":29,"answerPage":31},{"id":"ebs-10-08","unit":10,"number":8,"type":"choice","title":"8. 다음 자료가 발표된 이후의 상황으로 옳은 것은?","text":"8. 다음 자료가 발표된 이후의 상황으로 옳은 것은?\n\n\n 현재 남북에서 외세에 아부하는 자들은 서로 상대\n\n 방을 정벌하자며 전쟁을 열망하고 있다. …… 한국\n\n 이 있어야 한국 사람이 있고, 한국 사람이 있고야\n\n 민주주의도, 공산주의도, 무슨 단체도 존재할 수\n\n 있는 것이다. 자주독립적 통일 정부를 수립하려는\n\n 이때 어찌 개인이나 집단의 사리사욕을 탐하여 국\n\n 가 민족의 백년대계를 그르칠 수 있으랴? 나는 통\n\n 일된 조국을 건설하려다가 38도선을 베고 쓰러질\n\n 지언정 일신에 구차한 안일을 취하여 단독 정부를\n\n 세우는 데는 협력하지 아니하겠다.\n\n\n① ‌독립 협회가 창립되었다.\n\n② ‌조선 형평사가 조직되었다.\n\n③ ‌카이로 회담이 개최되었다.\n\n④ ‌6·10 만세 운동이 일어났다.\n\n⑤ ‌김구와 김규식이 남북 협상을 벌였다.","image":"assets/questions/ebs-10-08.webp","answer":"⑤","explanation":"해설\t|\t자료는 1948년 유엔 소총회에서 남한만의 단독 선\n거가 결정된 이후인 1948년 2월 김구가 발표한 ‘삼천만 동\n포에게 읍고함’이다. 이후 김구와 김규식은 1948년 4월 평\n양을 방문하여 남북 협상을 벌였다.\n오답\t피하기\t|\t①, ②, ③, ④ 모두 8·15 광복 이전에 있었\n던 사실이다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":30,"printedPage":29,"answerPage":31},{"id":"blank-10","unit":10,"number":9,"type":"blank","title":"1946년 여운형과 김규식 등이 중도 세력을 중심으로 추진한 운동은 ____ 운동이다.","text":"1946년 여운형과 김규식 등이 중도 세력을 중심으로 추진한 운동은 ____ 운동이다.","answer":"좌우 합작","explanation":"좌우 합작 위원회는 통일 정부 수립을 위해 좌우 합작 7원칙을 발표했다.","criteria":[],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":47},{"id":"essay-10","unit":10,"number":10,"type":"essay","title":"모스크바 3국 외상 회의에서 한국 문제에 관해 결정한 세 가지 내용을 서술하시오.","text":"모스크바 3국 외상 회의에서 한국 문제에 관해 결정한 세 가지 내용을 서술하시오.","answer":"한국에 민주주의 임시 정부를 수립하고 이를 협의하기 위해 미소 공동 위원회를 설치하기로 했다. 또한 미국·영국·소련·중국 4개국에 의한 최고 5년의 신탁 통치 협약을 마련하기로 했다.","explanation":"한국에 민주주의 임시 정부를 수립하고 이를 협의하기 위해 미소 공동 위원회를 설치하기로 했다. 또한 미국·영국·소련·중국 4개국에 의한 최고 5년의 신탁 통치 협약을 마련하기로 했다.","criteria":["민주주의 임시 정부 수립","미소 공동 위원회 설치","4개국·최고 5년 신탁 통치 구상"],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":47},{"id":"ebs-11-01","unit":11,"number":1,"type":"choice","title":"1. 밑줄 친 ‘이 선거’에 대한 설명으로 옳은 것은?","text":"1. 밑줄 친 ‘이 선거’에 대한 설명으로 옳은 것은?\n\n\n 이 선거는 1948년 38도선 이남 지역에서 유엔 한국\n\n 임시 위원단의 감시 아래 제헌 국회 의원을 선출하\n\n 기 위해 실시된 최초의 민주적인 총선거였다.\n\n\n① 대한국‌   국제를 제정하였다.\n\n② ‌사림 세력이 피해를 입었다.\n\n③ ‌집강소를 중심으로 추진되었다.\n\n④ ‌보통 선거의 원칙에 따라 치러졌다.\n\n⑤ ‌김옥균 등 급진 개화파가 주도하였다.","image":"assets/questions/ebs-11-01.webp","answer":"④","explanation":"해설\t| 자료에서 1948년 38도선 이남 지역에서 유엔 한국 \n임시 위원단의 감시 아래 제헌 국회 의원을 선출하기 위\n해 실시된 최초의 민주적인 총선거였다는 내용을 통해 밑\n줄 친 ‘이 선거’는 5·10 총선거임을 알 수 있다. 5·10 총\n선거는 보통 선거의 원칙에 따라 치러졌다.\n오답\t피하기\t|\t① 대한 제국 시기, ②, ③, ⑤ 조선 시대에 \n해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":32,"printedPage":31,"answerPage":34},{"id":"ebs-11-02","unit":11,"number":2,"type":"choice","title":"2. (가)에 들어갈 내용으로 가장 적절한 것은?","text":"2. (가)에 들어갈 내용으로 가장 적절한 것은?\n\n       <대한민국 정부 수립 과정>\n\n     유엔 소총회에서 남한만의 총선거 결정\n\n\n\n        평양에서 남북 협상 개최\n\n\n\n                 5·10 총선거\n\n\n\n                         (가)\n\n\n\n          대한민국 정부 수립\n\n\n① 원산‌  총파업\n\n② ‌대한민국 헌법 제정\n\n③ ‌좌우 합작 위원회 결성\n\n④ ‌모스크바 3국 외상 회의 개최\n\n⑤ ‌제1차 미소 공동 위원회 무기 휴회","image":"assets/questions/ebs-11-02.webp","answer":"②","explanation":"해설\t|\t자료에서 대한민국 정부 수립 과정에 대한 것이라\n는 점, 5·10 총선거와 대한민국 정부 수립 시기 사이에 \n있다는 점 등을 통해 (가)에는 대한민국 헌법 제정이 들어\n가는 것이 가장 적절하다는 것을 알 수 있다. 5·10 총선\n거의 결과 제헌 국회 의원이 선출되었고, 이들로 구성된 \n초대 국회(제헌 국회)는 국호를 대한민국으로 정하고 대\n통령 중심제에 기초한 헌법을 제정하였다.\n오답\t피하기\t|\t①, ③, ④, ⑤ 모두 1948년 5·10 총선거 이\n전에 있었던 사실이다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":32,"printedPage":31,"answerPage":34},{"id":"ebs-11-03","unit":11,"number":3,"type":"choice","title":"3. 다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?","text":"3. 다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?\n\n\n\n\n\n① ‌독립문의 건립 주체를 찾아본다.\n\n② ‌제헌 국회의 구성 과정을 조사한다.\n\n③ ‌청산리 대첩의 전개 과정을 알아본다.\n\n④ ‌강화도 조약이 체결된 계기를 분석한다.\n\n⑤ ‌민립 대학 설립 운동의 결과를 정리한다.","image":"assets/questions/ebs-11-03.webp","answer":"②","explanation":"해설\t|\t자료에서 총선거가 5월 10일이라는 점, 중앙 정부 \n수립을 홍보하고 있다는 점 등을 통해 제헌 국회의 구성 \n과정을 조사하는 탐구 활동이 가장 적절하다는 것을 알 \n수 있다. 5·10 총선거를 통해 제헌 국회가 구성되었다.\n오답\t피하기\t|\t① 독립문 건립, ③ 청산리 대첩, ④ 강화도 \n조약 체결, ⑤ 민립 대학 설립 운동은 모두 8·15 광복 이\n전에 있었던 사실이다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":32,"printedPage":31,"answerPage":34},{"id":"ebs-11-04","unit":11,"number":4,"type":"short","title":"4. 다음 자료에 해당하는 법의 명칭을 쓰시오.","text":"4. 다음 자료에 해당하는 법의 명칭을 쓰시오.\n\n\n 제1조 일본 정부와 통모하여 한·일 합병에 적극\n\n    협력한 자, 한국의 주권을 침해하는 조약\n\n    또는 문서에 조인한 자와 모의한 자는 사형\n\n    또는 무기 징역에 처하고 그 재산과 유산의\n\n    전부 혹은 2분지 1 이상을 몰수한다.\n\n 제3조 일본 치하 독립운동자나 그 가족을 악의로\n\n    살상 박해한 자 또는 이를 지휘한 자는 사\n\n      형, 무기 또는 5년 이상의 징역에 처하고 그\n\n    재산의 전부 혹은 일부를 몰수한다.\n\n\n                                      (                        )","image":"assets/questions/ebs-11-04.webp","answer":"반민족\t행위\t처벌법","explanation":"해설\t|\t자료에서 일본 정부와 통모하여 한·일 합병에 적\n극 협력한 자 등을 처벌한다는 점, 일본 치하 독립운동자\n나 그 가족을 악의로 살상 박해한 자 등을 처벌한다는 점 \n등을 통해 해당 법이 1948년 제헌 국회에서 제정한 반민\n족 행위 처벌법임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":32,"printedPage":31,"answerPage":34},{"id":"ebs-11-05","unit":11,"number":5,"type":"choice","title":"5. 다음 자료를 활용한 탐구 주제로 적절한 것만을 <보기>","text":"5. 다음 자료를 활용한 탐구 주제로 적절한 것만을 <보기>\n에서 고른 것은?\n\n\n 국회에서는 대통령이 친일파를 옹호한다고 말하며\n\n 민심을 선동하고 있다. …… 공산당이 취하는 방식\n\n 이라고 말할 수 있을 것이다. …… 과거에 친일한\n\n 자를 한꺼번에 숙청하였으면 좋을 것인데, 기나긴\n\n 군정 3년 동안에 못한 것을 지금에 와서 단행하면\n\n 앞으로 우리나라가 해 나갈 일에 여러 가지 지장이\n\n 많을 것이다.                 - 이승만 -\n\n\n      < 보기 >\n ㄱ. ‌고부 농민 봉기의 배경\n\n ㄴ. ‌친일파 청산 노력의 좌절\n\n ㄷ. ‌조선 물산 장려회의 조직 과정\n\n ㄹ. ‌반민족 행위 특별 조사 위원회 활동의 경과\n\n\n① ㄱ,‌ ㄴ    ② ㄱ, ㄷ    ③ ㄴ, ㄷ\n\n④ ‌ㄴ, ㄹ    ⑤ ㄷ, ㄹ","image":"assets/questions/ebs-11-05.webp","answer":"④","explanation":"해설\t|\t자료에서 ‘친일한 자를 한꺼번에 숙청하였으면 좋을 \n것인데’, ‘기나긴 군정 3년 동안에 못한 것을 지금에 와서 \n단행하면’이라는 표현을 사용한 점 등을 통해 ‘친일파 청\n산 노력의 좌절’ 또는 반민족 행위 특별 조사 위원회(반민 \n특위) 활동의 경과’를 탐구 주제로 삼는 것이 적절하다는 \n것을 알 수 있다. 제헌 국회는 반민족 행위 특별법을 제정\n하고 반민족 행위 특별 조사 위원회(반민 특위)를 결성하\n여 친일파 청산에 나섰다. 그러나 이승만은 반민 특위를 \n견제하는 담화를 여러 차례 발표하는 등 반민 특위 활동\n에 비협조적인 모습을 보였다. 또한 경찰의 반민 특위 습\n격 등 이승만 정부의 방해로 반민 특위는 그 역할을 다하\n지 못한 채 해체되었고, 이로써 친일파를 청산하려는 노\n력이 좌절되었다.\n오답\t피하기\t|\tㄱ. 고부 농민 봉기는 조선 시대, ㄷ. 조선 물\n산 장려회는 일제 강점기에 해당하며, 모두 제시된 자료\n와 관련이 없다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":33,"printedPage":32,"answerPage":34},{"id":"ebs-11-06","unit":11,"number":6,"type":"choice","title":"6. 다음 법령에 따른 사업의 결과로 옳은 것은?","text":"6. 다음 법령에 따른 사업의 결과로 옳은 것은?\n\n\n  2. ‌다음 농지는 적당한 보상으로 정부가 매수한다.\n\n 가) ‌농가가 아닌 자의 농지\n\n 나) ‌스스로 경작하지 않는 자의 농지. 단 질병, 공\n\n    무, 취학, 기타 부득이한 사유로 인하여 일시\n\n   이농한 자의 농지는 소재지 위원회의 동의로서\n\n   시장, 군수가 일정 기한까지 보류를 인허한다.\n\n 다) ‌본 법 규정의 한도(3정보)를 초과하는 부분의\n\n   농지\n\n\n① 지계가‌   발급되었다.\n\n② ‌대동법이 시행되었다.\n\n③ ‌국채 보상 운동이 일어났다.\n\n④ ‌산미 증식 계획이 실시되었다.\n\n⑤ ‌농민 중심의 농지 소유 확립에 기여하였다.","image":"assets/questions/ebs-11-06.webp","answer":"⑤","explanation":"해설\t|\t자료에서 정부가 적당한 보상으로 농지를 매수한다\n는 내용 등을 통해 해당 법령이 농지 개혁법임을 알 수 있\n다. 농지 개혁법에 따른 농지 개혁으로 대부분의 농민이 \n자기 소유의 토지를 갖게 되었다.\n오답\t피하기\t|\t①, ②, ③, ④ 모두 8·15 광복 이전에 있었\n던 사실이다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":33,"printedPage":32,"answerPage":34},{"id":"ebs-11-07","unit":11,"number":7,"type":"choice","title":"7. 밑줄 친 ‘발급’이 있었던 시기를 연표에서 옳게 고른 것","text":"7. 밑줄 친 ‘발급’이 있었던 시기를 연표에서 옳게 고른 것\n은?\n\n\n\n\n\n 자료는 농지 개혁법이 제정되고, 농지 개혁이 추진\n\n 되는 과정에서 정부가 발급한 지가 증권이다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n  국권     3·1   만주     8·15  대한민국   4·19\n  피탈   운동   사변   광복  정부 수립  혁명\n\n① (가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-11-07.webp","answer":"⑤","explanation":"해설\t|\t자료에서 농지 개혁이 추진되는 과정에서 발급되었\n다는 점 등을 통해 밑줄 친 ‘발급’은 대한민국 정부 수립 \n이후에 있었던 사실임을 알 수 있다. 대한민국 정부 수립\n은 1948년, 4·19 혁명은 1960년에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":33,"printedPage":32,"answerPage":34},{"id":"ebs-11-08","unit":11,"number":8,"type":"short","title":"8. 밑줄 친 ‘이 정부’가 무엇인지 쓰시오.","text":"8. 밑줄 친 ‘이 정부’가 무엇인지 쓰시오.\n\n\n 1948년 출범한 이 정부는         맞아. 한편으로는 친일\n 유상 매입, 유상 분배의       파 청산에 있어서 비협\n 원칙을 정하고 농지 개혁       조적인 모습을 보이기\n 을 추진하였어.            도 했었지.\n\n\n\n\n\n                                      (                        )","image":"assets/questions/ebs-11-08.webp","answer":"이승만\t정부","explanation":"해설\t|\t자료에서 1948년 출범했다는 점, 농지 개혁을 추진\n했다는 점, 친일파 청산에 비협조적인 모습을 보이기도 \n했다는 점 등을 통해 밑줄 친 ‘이 정부’가 이승만 정부임을 \n알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":33,"printedPage":32,"answerPage":34},{"id":"blank-11","unit":11,"number":9,"type":"blank","title":"대한민국 농지 개혁은 유상 매수·____의 원칙으로 실시되었다.","text":"대한민국 농지 개혁은 유상 매수·____의 원칙으로 실시되었다.","answer":"유상 분배","explanation":"정부가 보상하고 농지를 매입한 뒤 농민에게 대가를 받고 분배하는 방식이다.","criteria":[],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":52},{"id":"essay-11","unit":11,"number":10,"type":"essay","title":"반민특위의 목적과 활동이 좌절된 배경을 설명하시오.","text":"반민특위의 목적과 활동이 좌절된 배경을 설명하시오.","answer":"반민특위는 반민족 행위 처벌법에 따라 친일 행위자를 조사하고 처벌하여 친일 잔재를 청산하려 했다. 그러나 이승만 정부의 비협조와 경찰의 습격, 활동 기간을 축소한 법 개정 등으로 활동이 약화되어 청산을 충분히 수행하지 못했다.","explanation":"반민특위는 반민족 행위 처벌법에 따라 친일 행위자를 조사하고 처벌하여 친일 잔재를 청산하려 했다. 그러나 이승만 정부의 비협조와 경찰의 습격, 활동 기간을 축소한 법 개정 등으로 활동이 약화되어 청산을 충분히 수행하지 못했다.","criteria":["친일 행위 조사·처벌 목적","정부 비협조 또는 경찰 습격","법 개정·활동 축소로 청산 좌절"],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":52},{"id":"ebs-12-01","unit":12,"number":1,"type":"short","title":"1. 밑줄 친 ‘이 전쟁’은 무엇인지 쓰시오.","text":"1. 밑줄 친 ‘이 전쟁’은 무엇인지 쓰시오.\n\n\n          자료는 이 전쟁 당시 제작된\n\n           전단이다. 북한의 무력 남침\n\n          으로 시작된 이 전쟁에는 유엔\n\n          군이 참전하였으며, 1953년에\n\n          정전 협정이 체결되었다. 전\n\n          단에는 국군과 유엔군이 서울\n\n          을 탈환하였다는 내용이 담겨\n\n             있다.\n\n\n                                      (                        )","image":"assets/questions/ebs-12-01.webp","answer":"6·25\t전쟁","explanation":"해설\t| 자료에서 북한의 무력 남침으로 시작되었다는 점, \n유엔군이 참전하였다는 점, 1953년에 정전 협정이 체결\n되었다는 점, 국군과 유엔군이 서울을 탈환한 적이 있었\n다는 점 등을 통해 밑줄 친 ‘이 전쟁’은 6·25 전쟁임을 알 \n수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":35,"printedPage":34,"answerPage":37},{"id":"ebs-12-02","unit":12,"number":2,"type":"choice","title":"2. (가), (나) 시기 사이에 있었던 사실로 옳은 것만을 <보기>","text":"2. (가), (나) 시기 사이에 있었던 사실로 옳은 것만을 <보기>\n에서 고른 것은?\n\n\n  (가) 북한의‌   인민군은 국군을 일방적으로 몰아붙여\n\n   개전 3일 만에 서울을 점령하였다.\n\n  (나) ‌국군과 유엔군은 대규모 병력의 공세에 밀려\n\n   다시 서울을 빼앗겼다.\n\n\n      < 보기 >\n ㄱ. ‌인천 상륙 작전이 전개되었다.\n\n ㄴ. ‌중국이 대규모의 군대를 파병하였다.\n\n ㄷ. ‌이승만이 반공 포로를 전격 석방하였다.\n\n ㄹ. ‌애치슨이 미국의 태평양 방어선을 선언하였다.\n\n\n① ㄱ,‌ ㄴ    ② ‌ㄱ, ㄷ    ③ ‌ㄴ, ㄷ\n\n④ ‌ㄴ, ㄹ    ⑤ ‌ㄷ, ㄹ","image":"assets/questions/ebs-12-02.webp","answer":"①","explanation":"해설\t|\t(가)는 6·25 전쟁 발발 직후의 상황, (나)는 1951년 \n1·4 후퇴 상황임을 알 수 있다. 6·25 전쟁 초기에는 북\n한이 우세하였으나 국군과 유엔군이 인천 상륙 작전을 감\n행하여 서울을 수복하고 압록강까지 진출하였다. 그러자 \n중국이 대규모 병력을 파병하여 북한을 지원하였다. 중국\n군은 대규모 병력을 앞세워 압록강을 건너 순식간에 남하\n하였고, 국군과 유엔군은 다시 서울을 빼앗겼다.\n오답\t피하기\t|\tㄷ. 1951년 소련의 제의로 정전 협정이 시작\n되었다. 한편, 정전 협정에 반대하던 이승만은 반공 포로\n를 전격 석방하기도 하였다. ㄹ. 6·25 전쟁 이전 미국의 \n국무 장관 애치슨이 한반도를 미국의 태평양 방어선에서 \n제외한다는 애치슨 선언을 발표하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":35,"printedPage":34,"answerPage":37},{"id":"ebs-12-03","unit":12,"number":3,"type":"choice","title":"3. (가)에 들어갈 내용으로 옳은 것은?","text":"3. (가)에 들어갈 내용으로 옳은 것은?\n\n           <6·25 전쟁의 전개 과정>\n\n\n 북한군   인천 상륙               1·4   정전 협정\n                       (가)\n  남침     작전           후퇴     체결\n\n\n① ‌중국군 참전\n\n② ‌홍범 14조 반포\n\n③ ‌애치슨 라인 발표\n\n④ ‌위화도 회군 단행\n\n⑤ ‌강화도 조약 체결","image":"assets/questions/ebs-12-03.webp","answer":"①","explanation":"해설\t|\t자료에서 인천 상륙 작전은 1950년 9월 15일에 이\n루어졌고, 1·4 후퇴는 1951년 1월 4일 서울을 다시 빼앗\n긴 사건이다. 인천 상륙 작전 이후 국군과 유엔군은 서울\n을 수복하였다. 이후 위기를 느낀 중국군이 참전하였고, \n이들에 밀려 국군과 유엔군은 다시 서울을 빼앗겼다.\n오답\t피하기\t|\t②, ③, ④, ⑤ 모두 6·25 전쟁 발발 이전에 \n있었던 사실이다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":35,"printedPage":34,"answerPage":37},{"id":"ebs-12-04","unit":12,"number":4,"type":"choice","title":"4. 다음 개헌이 있었던 시기를 연표에서 옳게 고른 것은?","text":"4. 다음 개헌이 있었던 시기를 연표에서 옳게 고른 것은?\n\n\n       발췌 개헌의 주요 내용\n\n 제53조 대통령과 부통령은 국민의 보통, 평등, 직\n\n       접, 비밀 투표에 의하여 각각 선거한다.\n\n 부칙  이 헌법은 공포한 날로부터 시행한다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n  국권     3·1   만주     8·15  대한민국   4·19\n  피탈   운동   사변   광복  정부 수립  혁명\n\n① (가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-12-04.webp","answer":"⑤","explanation":"해설\t|\t자료가 발췌 개헌의 주요 내용임을 통해 1952년에 \n있었던 개헌임을 알 수 있다. 대한민국 정부 수립은 1948\n년, 4·19 혁명은 1960년에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":35,"printedPage":34,"answerPage":37},{"id":"ebs-12-05","unit":12,"number":5,"type":"choice","title":"5. 다음 개헌 이후에 있었던 사실로 옳은 것은?","text":"5. 다음 개헌 이후에 있었던 사실로 옳은 것은?\n\n\n 제55조 대통령과 부통령의 임기는 4년으로 한다.\n\n       단, 재선에 의하여 1차 중임할 수 있다.\n\n 부칙  이 헌법 공포 당시의 대통령에 대하여는\n\n      제55조 제1항 단서의 제한을 적용하지 아\n\n      니한다.\n\n\n① 김구가‌   남북 협상을 벌였다.\n\n② ‌이승만이 대통령에 당선되었다.\n\n③ ‌김원봉이 의열단을 조직하였다.\n\n④ ‌이상설이 헤이그에 특사로 파견되었다.\n\n⑤ ‌김좌진 등이 청산리 전투에서 승리하였다.","image":"assets/questions/ebs-12-05.webp","answer":"②","explanation":"해설\t|\t자료에서 헌법 공포 당시의 대통령에 대하여는 대\n통령 중임 제한을 적용하지 않는다는 내용 등을 통해 \n1954년에 있었던 사사오입 개헌임을 알 수 있다. 이 헌법\n에 따라 치러진 1956년 정·부통령 선거에서 이승만이 제\n3대 대통령으로 당선되었다.\n오답\t피하기\t|\t①, ③, ④, ⑤ 모두 대한민국 정부 수립 이전\n에 있었던 사실이다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":36,"printedPage":35,"answerPage":37},{"id":"ebs-12-06","unit":12,"number":6,"type":"short","title":"6. (가)에 들어갈 인물의 이름을 쓰시오.","text":"6. (가)에 들어갈 인물의 이름을 쓰시오.\n\n\n  1956년 정·부통령 선거에서 무소속 후보로 출마한\n\n       (가)    은/는 유효표의 30% 가량을 차지하면\n\n 서 이승만을 위협하였다. 이후      (가)    이/가\n\n 평화 통일론을 주장하며 진보당을 창당하자, 이승\n\n 만 정부는 간첩죄와 국가 보안법 위반 등의 혐의를\n\n 씌워 탄압하였다.\n\n\n                                      (                        )","image":"assets/questions/ebs-12-06.webp","answer":"조봉암","explanation":"해설\t|\t자료에서 1956년 정·부통령 선거에서 무소속 후보\n로 출마하여 많은 표를 얻었다는 점, 진보당을 창당하자 \n이승만 정부가 탄압하였다는 내용 등을 통해 (가) 인물이 \n조봉암임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":36,"printedPage":35,"answerPage":37},{"id":"ebs-12-07","unit":12,"number":7,"type":"choice","title":"7. 다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?","text":"7. 다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?\n\n\n          자료는 미국이 원조품으로 보낸\n\n         밀을 제분한 밀가루를 담았던 포\n\n         대 사진이다. 이 밀가루 포대에\n\n         는 팔거나 다른 물건과 바꾸지\n\n          말라는 문구가 한글과 영문으로\n\n         적혀 있다. 미국이 보내 준 원조\n\n 물자는 전후 한국 경제에 상당한 영향을 끼쳤다.\n\n\n① ‌물산 장려 운동의 계기를 파악한다.\n\n② ‌동학 농민 운동의 영향을 찾아본다.\n\n③ ‌국채 보상 운동의 목적을 정리한다.\n\n④ ‌화폐 정리 사업의 배경을 분석한다.\n\n⑤ ‌삼백 산업의 발달 과정을 알아본다.","image":"assets/questions/ebs-12-07.webp","answer":"⑤","explanation":"해설\t|\t자료에서 미국이 원조품으로 밀을 보냈다는 점, 미\n국이 보내 준 원조 물자는 전후 한국 경제에 상당한 영향\n을 끼쳤다는 점 등을 통해 삼백 산업의 발달 과정을 알아\n보는 것이 탐구 활동으로 가장 적절하다는 것을 알 수 있\n다. 6·25 전쟁 후 미국으로부터 원조받은 잉여 농산물을 \n가공하는 면방직, 제분, 제당의 삼백 산업이 발달하였다.\n오답\t피하기\t|\t① 물산 장려 운동, ② 동학 농민 운동, ③ 국\n채 보상 운동, ④ 화폐 정리 사업은 대한민국 정부 수립 \n이전에 있었던 사건이다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":36,"printedPage":35,"answerPage":37},{"id":"ebs-12-08","unit":12,"number":8,"type":"choice","title":"8. (가)에 들어갈 내용으로 가장 적절한 것은?","text":"8. (가)에 들어갈 내용으로 가장 적절한 것은?\n\n\n 6·25 전쟁 이후 복구 사         맞아. 전쟁 중 피란민이\n 업을 추진하면서 도시화        발생했고, 전후 도시로\n 가 진행되었어.           의 인구 집중이 심화되\n                   면서       (가)\n\n\n\n\n\n① ‌5소경이 만들어졌지.\n\n② ‌수원 화성이 건설되었지.\n\n③ ‌주거 등 도시 문제가 발생하였지.\n\n④ ‌대동법이 전국으로 확대 시행되었지.\n\n⑤ ‌일본인이 주로 거주하는 남촌이 형성되었지.","image":"assets/questions/ebs-12-08.webp","answer":"③","explanation":"해설\t|\t자료에서 6·25 전쟁 이후에 복구 사업이 추진되\n면서 도시화가 진행되었다는 점, 전쟁 중 발생한 피란민\n들이 도시로 이동하여 인구 집중이 심화되었다는 점 등을 \n통해 (가)에는 주거 등 도시 문제가 발생하였다는 내용이 \n들어가는 것이 가장 적절하다는 것을 알 수 있다.\n오답\t피하기\t|\t① 통일 신라 시기, ②, ④ 조선 시대, ⑤ 일\n제 강점기에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":36,"printedPage":35,"answerPage":37},{"id":"blank-12","unit":12,"number":9,"type":"blank","title":"1954년 당시 대통령 이승만의 중임 제한을 없앤 헌법 개정을 ____ 개헌이라고 한다.","text":"1954년 당시 대통령 이승만의 중임 제한을 없앤 헌법 개정을 ____ 개헌이라고 한다.","answer":"사사오입","explanation":"의결 정족수에 사사오입 논리를 적용해 통과를 주장한 개헌으로 장기 집권의 기반이 되었다.","criteria":[],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":57},{"id":"essay-12","unit":12,"number":10,"type":"essay","title":"6·25 전쟁이 한국 사회에 남긴 영향을 인구·생활과 남북 관계 측면에서 설명하시오.","text":"6·25 전쟁이 한국 사회에 남긴 영향을 인구·생활과 남북 관계 측면에서 설명하시오.","answer":"전쟁으로 많은 사람이 사망하거나 피란했고 이산가족과 전쟁고아가 발생했다. 산업 시설과 주거지가 파괴되어 생활이 어려워졌으며, 남북 간 적대감이 커지고 군사적 대치가 지속되면서 분단이 고착되었다.","explanation":"전쟁으로 많은 사람이 사망하거나 피란했고 이산가족과 전쟁고아가 발생했다. 산업 시설과 주거지가 파괴되어 생활이 어려워졌으며, 남북 간 적대감이 커지고 군사적 대치가 지속되면서 분단이 고착되었다.","criteria":["인명 피해·피란·이산가족","시설 파괴와 생활 어려움","적대감 심화와 분단 고착"],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":57},{"id":"ebs-13-01","unit":13,"number":1,"type":"choice","title":"1. 다음 결의안이 발표된 배경으로 가장 적절한 것은?","text":"1. 다음 결의안이 발표된 배경으로 가장 적절한 것은?\n\n\n       4월 26일 국회 본회의 결의안\n\n  1. 대통령은‌    즉시 하야한다.\n\n  2. ‌3·15 정·부통령 선거를 무효로 하고, 재선거\n\n  를 실시한다.\n\n  3. ‌과도 내각하에 완전 내각 책임제 개헌을 단행\n\n   한다.\n\n  4. ‌개헌 통과 후 민의원을 해산하고 총선거를 즉시\n\n   실시한다.\n\n\n① 대한국‌   국제가 제정되었다.\n\n② ‌5·10 총선거가 실시되었다.\n\n③ ‌김원봉이 의열단을 조직하였다.\n\n④ ‌광주 학생 항일 운동이 일어났다.\n\n⑤ ‌3·15 부정 선거를 규탄하는 시위가 확산되었다.","image":"assets/questions/ebs-13-01.webp","answer":"⑤","explanation":"해설\t| 4월 26일 국회 본회의 결의안이라는 점, 대통령은 \n즉시 하야한다는 내용, 3·15 정·부통령 선거를 무효로 \n하고 재선거를 실시한다는 내용 등을 통해 자료는 4·19 \n혁명으로 발표된 것임을 알 수 있다. 3·15 부정 선거를 \n규탄하는 시위가 확산되면서 4·19 혁명이 일어났다.\n오답\t피하기\t|\t①, ②, ③, ④ 모두 대한민국 정부 수립 이전\n에 있었던 사실이다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":38,"printedPage":37,"answerPage":40},{"id":"ebs-13-02","unit":13,"number":2,"type":"choice","title":"2. 다음 선언문이 발표된 시기를 연표에서 옳게 고른 것","text":"2. 다음 선언문이 발표된 시기를 연표에서 옳게 고른 것\n은?\n\n\n 민주주의와 민중의 공복이며 중립적인 권력체인 관\n\n 료와 경찰은 민주를 위장한 가부장적 전제 권력의\n\n 하수인으로 발 벗었다. 민주주의 이념의 최저의 공\n\n 리인 선거권마저 이승만 정부의 마수 앞에 농단되\n\n 었다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n   3·1     8·15  대한민국 장면 정부   5·16    3선\n  운동   광복  정부 수립  출범  군사 정변  개헌\n\n① (가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-13-02.webp","answer":"③","explanation":"해설\t|\t선거권이 이승만 정부의 마수 앞에서 농단되었다는 \n내용 등을 통해 자료는 1960년 3·15 부정 선거를 비판\n하면서 발표된 것임을 알 수 있다. 대한민국 정부 수립은 \n1948년, 장면 정부 출범은 1960년 4·19 혁명 이후에 해\n당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":38,"printedPage":37,"answerPage":40},{"id":"ebs-13-03","unit":13,"number":3,"type":"choice","title":"3. 다음 헌법이 마련된 배경으로 가장 적절한 것은?","text":"3. 다음 헌법이 마련된 배경으로 가장 적절한 것은?\n\n\n 제51조 대통령은 국가의 원수이며 국가를 대표한다.\n\n 제53조 대통령은 양원 합동 회의에서 선거하고 재\n\n     적 국회 의원 3분의 2 이상의 투표를 얻어\n\n     당선된다.\n\n 제68조 행정권은 국무원에 속한다. 국무원은 국무\n\n     총리와 국무 위원으로 조직한다. 국무원은\n\n     민의원에 대하여 연대 책임을 진다.\n\n 제69조 국무총리는 대통령이 지명하여 민의원의\n\n     동의를 얻어야 한다.\n\n\n① ‌4·19 혁명이 일어났다.\n\n② ‌3·1 운동이 시작되었다.\n\n③ ‌임술 농민 봉기가 발생하였다.\n\n④ ‌2·8 독립 선언이 발표되었다.\n\n⑤ ‌6·10 만세 운동이 전개되었다.","image":"assets/questions/ebs-13-03.webp","answer":"①","explanation":"해설\t|\t자료에서 대통령은 양원 합동 회의에서 선거한다\n는 점, 국무원은 민의원에 대하여 연대 책임을 진다는 점 \n등을 통해 4·19 혁명 이후 내각 책임제와 양원제 국회를 \n주요 내용으로 하는 개헌임을 알 수 있다.\n오답\t피하기\t|\t② 3·1 운동은 1919년 시작되어, 일제의 식\n민 통치 방식 변화에 영향을 주었다. ③ 임술 농민 봉기는 \n삼정의 문란 등을 배경으로 조선 후기에 발생하였다. ④ \n1919년 일본 도쿄에서 한국인 유학생들이 2·8 독립 선언\n을 발표하였다. ⑤ 1926년 순종의 장례일에 맞추어 학생\n들을 중심으로 6·10 만세 운동이 전개되었다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":38,"printedPage":37,"answerPage":40},{"id":"ebs-13-04","unit":13,"number":4,"type":"short","title":"4. (가)에 해당하는 인물을 쓰시오.","text":"4. (가)에 해당하는 인물을 쓰시오.\n\n\n\n\n\n 자료는      (가)  내각의 출범 당시 윤보선 대통\n\n 령 부부와      (가)  국무총리 부부의 모습이 담\n\n 긴 사진이다.      (가)   정부는 정부 수립 이후\n\n 역사상 유일한 내각 책임제 정부이다.\n\n\n                                      (                        )","image":"assets/questions/ebs-13-04.webp","answer":"장면","explanation":"해설\t|\t자료에서 내각 출범 당시 모습이라는 점, 윤보선이 \n대통령이었다는 점, 해당 인물이 국무총리라는 점, 정부 \n수립 이후 역사상 유일한 내각 책임제 정부라는 점 등을 \n통해 (가) 인물이 장면임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":38,"printedPage":37,"answerPage":40},{"id":"ebs-13-05","unit":13,"number":5,"type":"choice","title":"5. 다음과 같은 국회가 구성되었던 시기를 연표에서 옳게 ","text":"5. 다음과 같은 국회가 구성되었던 시기를 연표에서 옳게\n고른 것은?\n\n     민주당 자유당 사회 대중당 한국 사회당 …\n\n 민의원   175석   2석     4석       1석   …\n\n 참의원   31석   4석      1석       1석   …\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n   3·1    8·15  대한민국   4·19  한일 협정   3선\n  운동   광복  정부 수립  혁명   체결   개헌\n\n① (가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-13-05.webp","answer":"④","explanation":"해설\t|\t자료에서 국회가 민의원과 참의원의 양원으로 구성\n된 점, 민주당이 다수를 차지한 점 등을 통해 장면 내각 \n시기의 상황임을 알 수 있다. 4·19 혁명의 결과 이승만\n이 대통령직에서 물러났고, 이후 수립된 허정 과도 정부\n는 내각 책임제와 양원제 국회를 주요 내용으로 하는 개\n헌을 단행하였다. 이에 따라 치러진 총선거에서 민주당\n이 압승을 거두고 장면 내각이 출범하였다. 4·19 혁명은 \n1960년, 한일 협정 체결은 1965년에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":39,"printedPage":38,"answerPage":40},{"id":"ebs-13-06","unit":13,"number":6,"type":"choice","title":"6. 다음 자료를 발표한 세력에 대한 설명으로 옳은 것만을 ","text":"6. 다음 자료를 발표한 세력에 대한 설명으로 옳은 것만을\n<보기>에서 고른 것은?\n\n\n  1. 반공을‌   국시의 제일의(義)로 삼는다.\n\n  4. ‌민생고를 해결하여 국가 자주 경제 재건에 총력\n\n  을 기울인다.\n\n  6. ‌과업이 성취되면 양심적인 정치인들에게 정권을\n\n  이양하고 군 본연의 임무에 복귀한다.\n\n\n      < 보기 >\n ㄱ. ‌반공 포로를 석방하였다.\n\n ㄴ. ‌중앙정보부를 창설하였다.\n\n ㄷ. ‌내각 책임제 개헌을 단행하였다.\n\n ㄹ. ‌국가 재건 최고 회의를 설치하였다.\n\n\n① ㄱ,‌ ㄴ    ② ‌ㄱ, ㄷ    ③ ‌ㄴ, ㄷ\n\n④ ‌ㄴ, ㄹ    ⑤ ‌ㄷ, ㄹ","image":"assets/questions/ebs-13-06.webp","answer":"④","explanation":"해설\t|\t자료는 1961년 5·16 군사 정변을 일으킨 박정희 등 \n일부 군인들이 발표한 혁명 공약이다. ㄴ. 군사 정변 세력\n은 중앙정보부를 설치하여 권력 기반을 강화하였다. ㄹ.  \n박정희 등 군사 정변 세력은 국가 재건 최고 회의를 설치\n하여 군정을 실시하였다.\n오답\t피하기\t|\tㄱ. 6·25 전쟁 당시 정전 협정에 반대하던 \n이승만이 반공 포로를 석방하기도 하였다. ㄷ. 4·19 혁\n명의 결과 수립된 허정 과도 정부가 내각 책임제와 양원\n제 국회를 주요 내용으로 하는 개헌을 단행하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":39,"printedPage":38,"answerPage":40},{"id":"ebs-13-07","unit":13,"number":7,"type":"choice","title":"7. 다음 각서가 체결된 배경을 알아보기 위한 탐구 활동으","text":"7. 다음 각서가 체결된 배경을 알아보기 위한 탐구 활동으\n로 가장 적절한 것은?\n\n\n •미국은 한국에 있는 한국군의 현대화 계획을 위하\n\n  여 앞으로 수년 동안 상당량의 장비를 제공한다.\n\n •미국은 이미 약속한 바 있는 1억 5천만 달러 규\n\n  모의 차관에 덧붙여 한국의 경제 개발을 돕기 위\n\n  한 추가 차관을 제공한다.\n\n\n① ‌4·19 혁명의 전개 과정을 정리한다.\n\n② ‌베트남 파병이 이루어진 경위를 조사한다.\n\n③ ‌모스크바 3국 외상 회의의 결정 사항을 알아본다.\n\n④ ‌6·25 전쟁 이후 전후 복구 사업의 내용을 살펴본다.\n\n⑤ ‌좌우 합작 7원칙에 대한 당시 사람들의 입장을 분석\n\n  한다.","image":"assets/questions/ebs-13-07.webp","answer":"②","explanation":"해설\t|\t자료는 미국이 한국군의 현대화를 지원하고 차관을 \n제공하기로 약속하는 내용 등이 포함된 브라운 각서이며, \n이를 통해 베트남 파병이 이루어진 경위를 조사하는 탐구 \n활동이 가장 적절하다는 것을 알 수 있다. 박정희 정부는 \n미국의 요청에 따라 베트남에 파병하였고, 미국은 파병의 \n대가로 한국군의 현대화와 기술 및 차관 제공 등을 약속\n하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":39,"printedPage":38,"answerPage":40},{"id":"ebs-13-08","unit":13,"number":8,"type":"short","title":"8. 밑줄 친 ‘이 정부’는 무엇인지 쓰시오.","text":"8. 밑줄 친 ‘이 정부’는 무엇인지 쓰시오.\n\n\n 이 정부는 대통령에 3회 연속 취임할 수 있도록 허\n\n 용하는 헌법 개정을 추진해 장기 집권을 도모하였\n\n 다. 국민과 야당은 이를 반대하며 전국적인 시위를\n\n 전개하였으나, 이 정부와 여당은 반공 태세 강화와\n\n 국가 발전을 구실로 반대 여론을 억압한 채 3선 개\n\n 헌을 단행하였다(1969).\n\n\n                                      (                        )","image":"assets/questions/ebs-13-08.webp","answer":"박정희\t정부","explanation":"해설\t|\t자료에서 1969년에 3선 개헌을 단행하였다는 점 등\n을 통해 밑줄 친 ‘이 정부’는 박정희 정부임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":39,"printedPage":38,"answerPage":40},{"id":"blank-13","unit":13,"number":9,"type":"blank","title":"4·19 혁명 이후 장면 정부는 대통령 중심제 대신 ____를 채택했다.","text":"4·19 혁명 이후 장면 정부는 대통령 중심제 대신 ____를 채택했다.","answer":"내각 책임제","explanation":"국무총리가 이끄는 내각이 행정의 중심을 이루었고 국회는 양원제로 구성되었다.","criteria":[],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":62},{"id":"essay-13","unit":13,"number":10,"type":"essay","title":"4·19 혁명의 직접적인 계기, 결과, 역사적 의의를 서술하시오.","text":"4·19 혁명의 직접적인 계기, 결과, 역사적 의의를 서술하시오.","answer":"3·15 부정 선거에 대한 저항이 직접적인 계기가 되어 학생과 시민의 시위가 전국으로 확대되었다. 이승만이 하야했고, 국민의 힘으로 독재 정권을 무너뜨려 민주주의 발전의 기반을 마련했다.","explanation":"3·15 부정 선거에 대한 저항이 직접적인 계기가 되어 학생과 시민의 시위가 전국으로 확대되었다. 이승만이 하야했고, 국민의 힘으로 독재 정권을 무너뜨려 민주주의 발전의 기반을 마련했다.","criteria":["3·15 부정 선거","이승만 하야","학생·시민이 독재 정권을 무너뜨림"],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":62},{"id":"ebs-14-01","unit":14,"number":1,"type":"choice","title":"1. 다음 헌법이 만들어진 시기를 연표에서 옳게 고른 것은?","text":"1. 다음 헌법이 만들어진 시기를 연표에서 옳게 고른 것은?\n\n\n 제53조 대통령은 천재지변 또는 중대한 재정·경\n\n     제상의 위기에 처하거나, 국가의 안전 보\n\n     장 또는 공공의 안녕질서가 중대한 위협을\n\n     받거나 받을 우려가 있어 신속한 조치를\n\n     할 필요가 있다고 판단할 때에는 내정·외\n\n     교·국방·경제·재정·사법 등 국정 전\n\n     반에 걸쳐 필요한 긴급 조치를 할 수 있다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n   3·1     8·15  대한민국   4·19    5·16    5·18\n  운동   광복  정부 수립  혁명  군사 정변 민주화\n                            운동\n\n① (가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-14-01.webp","answer":"⑤","explanation":"해설\t| 자료에서 대통령이 국가의 안전 보장 또는 공공의 \n안녕질서가 중대한 위협을 받거나 받을 우려가 있어 신\n속한 조치를 할 필요가 있다고 판단할 때 긴급 조치를 할 \n수 있다는 내용 등을 통해 해당 헌법이 1972년에 제정된 \n유신 헌법임을 알 수 있다. 5·16 군사 정변은 1961년, \n5·18 민주화 운동은 1980년에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":41,"printedPage":40,"answerPage":43},{"id":"ebs-14-02","unit":14,"number":2,"type":"short","title":"2. (가)에 들어갈 기구를 쓰시오.","text":"2. (가)에 들어갈 기구를 쓰시오.\n\n\n 제39조 대통령은      (가)    에서 토론 없이 무\n\n     기명 투표로 선거한다.\n\n 제40조      (가)    은/는 국회 의원 정수의 3분의\n\n       1에 해당하는 수의 국회 의원을 선거한다.\n\n\n                                      (                        )","image":"assets/questions/ebs-14-02.webp","answer":"통일\t주체\t국민\t회의","explanation":"해설\t|\t자료에서 대통령 선거를 토론 없이 무기명으로 투\n표한다는 점, 국회 의원 정수의 3분의 1에 해당하는 수의 \n국회 의원을 선거한다는 점 등을 통해 (가) 기구가 유신 \n헌법에 의해 설치된 통일 주체 국민 회의임을 알 수 있다. \n유신 헌법에서는 통일 주체 국민 회의에서 대통령을 선출\n하도록 하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":41,"printedPage":40,"answerPage":43},{"id":"ebs-14-03","unit":14,"number":3,"type":"choice","title":"3. 다음 선언이 발표된 배경으로 가장 적절한 것은?","text":"3. 다음 선언이 발표된 배경으로 가장 적절한 것은?\n\n\n         3·1 민주 구국 선언(1976)\n\n 4·19 학생 의거로 이승만 독재를 무너뜨려 ‘자유\n\n 민주주의’에 대한 신념을 가슴에 회생시켰다. ……\n\n 국가 안보라는 구실 아래 신앙과 양심의 자유는 날\n\n 로 위축되어 가고 언론의 자유와 학원의 자주성은\n\n 압살당하고 말았다. …… 민주주의는 대한민국의\n\n 국시이다. 따라서 대한민국의 정통성은 민주주의에\n\n 있다. …… 그러므로 우리는 국민의 자유를 억압\n\n 하는 긴급 조치를 곧 철폐하고 …… 국민의 의사가\n\n 자유롭게 표명될 수 있도록 언론·집회·출판의 자\n\n 유를 국민에게 돌리라고 요구한다.\n\n\n① ‌총독부가 설치되었다.\n\n② ‌유신 헌법이 제정되었다.\n\n③ ‌만주 사변이 발발하였다.\n\n④ ‌치안 유지법이 공포되었다.\n\n⑤ ‌강화도 조약이 체결되었다.","image":"assets/questions/ebs-14-03.webp","answer":"②","explanation":"해설\t|\t자료는 1976년에 발표된 3·1 민주 구국 선언이다. \n박정희 정부가 1972년 유신 헌법을 제정하자, 이에 대한 \n저항으로 3·1 민주 구국 선언이 발표되었다.\n오답\t피하기\t|\t①, ③, ④ 일제 강점기, ⑤ 조선 후기에 해당\n한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":41,"printedPage":40,"answerPage":43},{"id":"ebs-14-04","unit":14,"number":4,"type":"choice","title":"4. 다음 일기에 기록되어 있을 내용으로 가장 적절한 것","text":"4. 다음 일기에 기록되어 있을 내용으로 가장 적절한 것\n은?\n\n\n 광주여고에 재학 중이던 ◯◯◯ 학생이 쓴 일기가\n\n 유네스코 세계 기록 유산에 등재된 자료에 포함되\n\n 어 주목을 받았다. 여기에는 1980년 5월 18일부터\n\n 27일까지의 상황이 생생하게 기록되어 있어서 그\n\n 가치를 인정받았다.\n\n\n① ‌사사오입 개헌이 이루어졌다.\n\n② ‌대한 제국 수립이 선포되었다.\n\n③ ‌관군이 홍경래의 난을 진압하였다.\n\n④ ‌계엄군의 폭행으로 사망자가 발생하였다.\n\n⑤ ‌한일 회담에 반대하는 시위가 확산되었다.","image":"assets/questions/ebs-14-04.webp","answer":"④","explanation":"해설\t|\t자료에서 광주여고에 재학 중이던 학생이 쓴 일기라\n는 점, 1980년 5월 18일부터 27일까지의 상황이 생생하게 \n기록되어 있다는 점, 유네스코 세계 기록 유산으로 등재\n되었다는 점 등을 통해 해당 일기에는 5·18 민주화 운동 \n당시의 상황이 기록되어 있음을 알 수 있다. 5·18 민주화 \n운동 당시 신군부는 계엄군을 동원하여 시위를 무력으로 \n진압하였고, 이 과정에서 많은 사람들이 희생당하였다.\n오답\t피하기\t|\t① 1952년, ② 1897년, ③ 조선 후기, ⑤ 1960\n년대에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":41,"printedPage":40,"answerPage":43},{"id":"ebs-14-05","unit":14,"number":5,"type":"short","title":"5. (가)에 들어갈 민주화 운동을 쓰시오.","text":"5. (가)에 들어갈 민주화 운동을 쓰시오.\n\n\n\n\n\n 자료는      (가)  당시 전남도청 앞 금남로에 모\n\n 인 시민들과 무장한 상태로 대치 중인 계엄군의 모\n\n 습이 담긴 사진이다.\n\n\n                                      (                        )","image":"assets/questions/ebs-14-05.webp","answer":"5·18\t민주화\t운동","explanation":"해설\t|\t자료에서 전남도청 앞 금남로에 모인 시민들이라는 \n점, 무장한 상태로 대치 중인 계엄군의 모습이 담겨 있다\n는 점 등을 통해 (가)는 5·18 민주화 운동임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":42,"printedPage":41,"answerPage":43},{"id":"ebs-14-06","unit":14,"number":6,"type":"choice","title":"6. 다음 궐기문이 발표된 시기를 연표에서 옳게 고른 것","text":"6. 다음 궐기문이 발표된 시기를 연표에서 옳게 고른 것\n은?\n\n\n 우리는 왜 총을 들 수밖에 없었는가? 그 대답은 너\n\n 무나 간단합니다. 너무나 무자비한 만행을 더 이상\n\n 보고 있을 수만은 없어서 너도나도 총을 들고 나섰\n\n 던 것입니다. …… 정부 당국에서는 17일 야간에\n\n 계엄령을 확대 선포하고 일부 학생과 민주 인사,\n\n 정치인을 도무지 믿을 수 없는 구실로 불법 연행하\n\n 였습니다. …… 18일 아침에 각 학교에 공수 부대\n\n 를 투입하고 …… 이에 우리 학생들은 다시 거리로\n\n 뛰쳐나와 정부 당국의 불법 처사를 규탄하였던 것\n\n 입니다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n  8·15  대한민국   4·19    5·16    3선     6월\n  광복  정부 수립  혁명  군사 정변  개헌  민주 항쟁\n\n① (가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-14-06.webp","answer":"⑤","explanation":"해설\t|\t자료에서 정부가 17일에 계엄령을 확대 선포하였다\n는 점, 18일에 공수 부대가 학교에 투입되었다는 점 등을 \n통해 해당 궐기문은 1980년에 있었던 5·18 민주화 운동 \n당시에 발표된 것임을 알 수 있다. 3선 개헌은 1969년, 6\n월 민주 항쟁은 1987년에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":42,"printedPage":41,"answerPage":43},{"id":"ebs-14-07","unit":14,"number":7,"type":"choice","title":"7. 다음 민주화 운동 당시 제기된 구호로 옳은 것은?","text":"7. 다음 민주화 운동 당시 제기된 구호로 옳은 것은?\n\n\n  4·13 호헌 조치 이후 민주화를 요구하는 목소리가\n\n 높아졌다. 야당과 종교계, 학생 운동 조직 등은 정\n\n 권 퇴진 운동을 전개하였다. 그러던 중 이한열이 시\n\n 위 도중 경찰이 쏜 최루탄에 맞아 쓰러지는 사건이\n\n 벌어졌다. 이를 계기로 민주화 요구는 더욱 거세어\n\n 졌고, 수십만 명의 사람들이 시위를 전개하였다.\n\n\n① ‌이승만은 하야하라!\n\n② ‌유신 헌법에 반대한다!\n\n③ ‌베트남 파병을 중단하라!\n\n④ ‌대통령 직선제 개헌을 단행하라!\n\n⑤ ‌한일 기본 조약 체결에 반대한다!","image":"assets/questions/ebs-14-07.webp","answer":"④","explanation":"해설\t|\t자료에서 4·13 호헌 조치 이후 민주화를 요구하는 \n목소리가 높아졌다는 점. 이한열이 시위 도중 경찰이 쏜 \n최루탄에 맞아 쓰러지는 사건이 발생했다는 점 등을 통해 \n해당 민주화 운동은 1987년에 전개된 6월 민주 항쟁임을 \n알 수 있다. 1980년대 중반부터 대통령 직선제 개헌에 대\n한 요구가 높아졌으나, 전두환 정부는 4·13 호헌 조치로 \n이를 거부하였다. 이에 6월 민주 항쟁이 전개되어 6·29 \n민주화 선언이 발표되었다.\n오답\t피하기\t|\t① 이승만은 1960년 4·19 혁명으로 하야하\n였다. ② 1980년 제11대 대통령에 전두환이 취임한 후 새\n로운 헌법이 마련되었다. ③ 베트남 파병은 박정희 정부 \n시기에 이루어졌다. ⑤ 한일 기본 조약은 박정희 정부 시\n기에 체결되었다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":42,"printedPage":41,"answerPage":43},{"id":"ebs-14-08","unit":14,"number":8,"type":"choice","title":"8. 다음 선언이 발표된 배경으로 가장 적절한 것은?","text":"8. 다음 선언이 발표된 배경으로 가장 적절한 것은?\n\n\n 첫째, 여야 합의 하에 조속히 대통령 직선제 개헌\n\n 을 하고 새 헌법에 의해 대통령 선거로 1988년 2월\n\n 평화적 정부 이양을 실현토록 하겠습니다. …… 국\n\n 민은 나라의 주인이며, 국민의 뜻은 모든 것에 우\n\n 선하는 것입니다. 둘째, 최대한의 공명정대한 선거\n\n 관리가 이루어져야 합니다.\n\n\n① ‌발췌 개헌안이 통과되었다.\n\n② ‌6월 민주 항쟁이 일어났다.\n\n③ ‌3·15 부정 선거가 자행되었다.\n\n④ ‌5·18 민주화 운동이 진압되었다.\n\n⑤ ‌유신 헌법 폐지 요구가 고조되었다.","image":"assets/questions/ebs-14-08.webp","answer":"②","explanation":"해설\t|\t대통령 직선제 개헌을 하겠다는 점, 1988년 2월 \n평화적 정부 이양을 실현하겠다는 점 등을 통해 자료는 \n6·29 민주화 선언임을 알 수 있다. 직선제 개헌을 요구\n하는 6월 민주 항쟁이 계속되자, 노태우가 6·29 민주화 \n선언을 발표하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":42,"printedPage":41,"answerPage":43},{"id":"blank-14","unit":14,"number":9,"type":"blank","title":"1987년 6월 민주 항쟁의 핵심 정치적 요구는 호헌 철폐와 ____ 도입이었다.","text":"1987년 6월 민주 항쟁의 핵심 정치적 요구는 호헌 철폐와 ____ 도입이었다.","answer":"대통령 직선제","explanation":"6·29 선언 이후 개헌을 통해 5년 단임 대통령 직선제가 도입되었다.","criteria":[],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":67},{"id":"essay-14","unit":14,"number":10,"type":"essay","title":"6월 민주 항쟁의 배경과 시민들의 요구, 제도적 결과를 연결하여 설명하시오.","text":"6월 민주 항쟁의 배경과 시민들의 요구, 제도적 결과를 연결하여 설명하시오.","answer":"박종철 고문치사 사건과 4·13 호헌 조치로 국민의 불만이 커졌다. 시민들은 호헌 철폐와 대통령 직선제를 요구했고, 6·29 선언을 거쳐 5년 단임의 대통령 직선제 개헌이 이루어졌다.","explanation":"박종철 고문치사 사건과 4·13 호헌 조치로 국민의 불만이 커졌다. 시민들은 호헌 철폐와 대통령 직선제를 요구했고, 6·29 선언을 거쳐 5년 단임의 대통령 직선제 개헌이 이루어졌다.","criteria":["고문치사 사건·호헌 조치","호헌 철폐·대통령 직선제 요구","5년 단임 직선제 개헌"],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":67},{"id":"ebs-15-01","unit":15,"number":1,"type":"choice","title":"1. (가)에 들어갈 내용으로 가장 적절한 것은?","text":"1. (가)에 들어갈 내용으로 가장 적절한 것은?\n\n\n  제1, 2차 경제 개발 5개년 계획이 추진되던 시기에\n\n 는 외국 자본을 끌어들여 수출 산업을 육성하였다.\n\n 세계 경제가 호황을 누리던 상황에서 수출액이 크\n\n 게 늘어났고, 여기에 베트남 파병에 따른 특수가\n\n 더해지면서 경제가 빠르게 성장하였다. 그 결과,\n\n               (가)\n\n\n① 농지‌  개혁이 시작되었다.\n\n② ‌미국의 경제 원조가 이루어졌다.\n\n③ ‌노동 집약적 산업이 성장하였다.\n\n④ ‌제2차 석유 파동을 극복할 수 있었다.\n\n⑤ ‌중화학 공업의 비중이 경공업을 앞질렀다.","image":"assets/questions/ebs-15-01.webp","answer":"③","explanation":"해설\t| 자료에서 제1, 2차 경제 개발 5개년 계획이 추진되\n었다는 점, 베트남 파병에 따른 특수가 더해지면서 경제\n가 빠르게 성장하였다는 점 등을 통해 1960년대 경제 상\n황에 대한 것임을 알 수 있다. 제1, 2차 경제 개발 5개년 \n계획 시기에는 자본과 기술 부족으로 신발, 의류, 가발 등 \n낮은 임금을 이용한 노동 집약적 산업이 육성되었다.\n오답\t피하기\t|\t① 농지 개혁은 이승만 정부 시기에 시작되었\n다. ② 미국의 경제 원조는 광복 직후부터 이루어졌고, 특\n히 6·25 전쟁 이후 크게 늘었는데, 이는 전후 복구 사업\n의 기초가 되었다. ④ 제2차 석유 파동은 1978년부터 일\n어났다. ⑤ 제3, 4차 경제 개발 5개년 계획으로 중화학 공\n업이 적극 육성되었고, 그 결과 1970년대 말 공업 구조에\n서 중화학 공업이 차지하는 비중이 경공업을 앞지르게 되\n었다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":44,"printedPage":43,"answerPage":46},{"id":"ebs-15-02","unit":15,"number":2,"type":"choice","title":"2. 밑줄 친 ‘개통’이 있었던 시기를 연표에서 옳게 고른 것","text":"2. 밑줄 친 ‘개통’이 있었던 시기를 연표에서 옳게 고른 것\n은?\n\n\n 오늘, 이 좋은 날을 택해서 우리들의 오랜 꿈이요,\n\n 우리 민족의 숙원이던 경부 간 고속 도로의 완전\n\n 개통을 보게 된 것을 국민 여러분과 경축해 마지않\n\n 는 바입니다. 이 길이는 총연장 428km로 우리나라\n\n 의 리수로 따지면 천 리하고도 약 70리가 더 되는\n\n 데, 장장 천 리 길을 이제부터 자동차로 4시간 반이\n\n 면 달릴 수 있게 되었습니다. …… 만2년 5개월 만\n\n 에 여러 가지 난관과 애로를 극복하고 오늘 예정대\n\n 로 완전히 개통을 보게 된 것입니다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n   3·1  대한민국   4·19    5·16    12·12    6월\n  운동  정부 수립  혁명  군사 정변  사태  민주 항쟁\n\n① (가)‌   ② (나)  ③ (다)  ④ ‌(라)  ⑤ (마)","image":"assets/questions/ebs-15-02.webp","answer":"④","explanation":"해설\t|\t자료에서 경부 간 고속 도로의 완전 개통이라는 점, \n만2년 5개월 만에 개통이 이루어졌다는 점 등을 통해 밑\n줄 친 ‘개통’은 1970년에 있었던 경부 고속 도로 개통임\n을 알 수 있다. 5·16 군사 정변은 1961년, 12·12 사태는 \n1979년에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":44,"printedPage":43,"answerPage":46},{"id":"ebs-15-03","unit":15,"number":3,"type":"choice","title":"3. 교사의 질문에 대한 학생의 답변으로 가장 적절한 것","text":"3. 교사의 질문에 대한 학생의 답변으로 가장 적절한 것\n은?\n\n\n 자료는 ◯◯◯ 정부 시기에 발행된 수출 100억 달러 달성 기념\n 우표입니다. ◯◯◯ 정부 시기에 있었던 대표적인 경제 성장 모\n 습을 말해볼까요?\n\n\n\n\n\n① ‌지계가 발급되었어요.\n\n② ‌대동법이 실시되었어요.\n\n③ ‌포항 종합 제철이 준공되었어요.\n\n④ ‌국채 보상 운동이 전개되었어요.\n\n⑤ ‌조청 상민 수륙 무역 장정이 체결되었어요.","image":"assets/questions/ebs-15-03.webp","answer":"③","explanation":"해설\t|\t수출 100억 달러 달성 기념 우표가 발행되었다는 점 \n등을 통해 자료는 박정희 정부 시기에 해당함을 알 수 있\n다. 박정희 정부 시기인 1973년 포항 종합 제철이 준공되\n었다.\n오답\t피하기\t|\t①, ④ 대한 제국 시기, ②, ⑤ 조선 시대에 \n해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":44,"printedPage":43,"answerPage":46},{"id":"ebs-15-04","unit":15,"number":4,"type":"short","title":"4. 밑줄 친 ‘이 정부’는 무엇인지 쓰시오.","text":"4. 밑줄 친 ‘이 정부’는 무엇인지 쓰시오.\n\n\n  제1, 2차 경제 개발 5개년        맞아. 1970년대 이 정부는\n 계획을 실시한 이 정부      중화학 공업 육성을 목표\n 시기에 경제 성장이 이루      로 제3차 경제 개발 5개\n 어졌어.              년 계획을 실시하였지.\n\n\n\n\n\n                                      (                        )","image":"assets/questions/ebs-15-04.webp","answer":"박정희\t정부","explanation":"해설\t|\t자료에서 제1, 2차 경제 개발 5개년 계획을 실시했\n다는 점, 중화학 공업 육성을 목표로 제3차 경제 개발 5\n개년 계획을 실시했다는 점 등을 통해 밑줄 친 ‘이 정부’는 \n박정희 정부임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":44,"printedPage":43,"answerPage":46},{"id":"ebs-15-05","unit":15,"number":5,"type":"choice","title":"5. (가) 시기의 경제 변화가 나타난 배경으로 가장 적절한 ","text":"5. (가) 시기의 경제 변화가 나타난 배경으로 가장 적절한\n것은?\n\n    (백만 달러)\n      70,000\n           수출\n      60,000           수입\n      50,000\n\n      40,000\n\n      30,000\n\n      20,000\n\n      10,000\n\n         0\n              1982 1983 1984 1985 1986 1987 1988 1989(년)\n                                     (가)\n                        -한국 무역 협회, 각 연도 자료-\n\n① 새마을‌   운동이 시작되었다.\n\n② ‌광주 대단지 사건이 일어났다.\n\n③ ‌제1차 경제 개발 계획이 추진되었다.\n\n④ ‌미국의 잉여 농산물 원조가 이루어졌다.\n\n⑤ ‌저유가, 저금리, 저달러의 3저 호황이 이어졌다.","image":"assets/questions/ebs-15-05.webp","answer":"⑤","explanation":"해설\t|\t자료에서 1980년대 중반 이후 수출이 크게 늘어났\n고, 수출 규모가 수입 규모를 크게 앞질렀다는 점을 알 수 \n있다. 1980년대 중반부터 본격화된 저유가, 저금리, 저달\n러의 세계적인 3저 호황에 힘입어 무역 수지 흑자를 달성\n할 수 있었다.\n오답\t피하기\t|\t① 새마을 운동은 1970년에 시작되었다. ② \n광주 대단지 사건은 1971년 철거민들이 졸속적인 도시 정\n책에 반대하여 경찰과 대치한 사건이다. ③ 제1차 경제 개\n발 계획은 1962년부터 1966년까지 추진되었다. ④ 6·25 \n전쟁 이후 미국의 잉여 농산물 원조가 본격적으로 이루어\n졌고, 이는 전후 복구에 큰 도움이 되었다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":45,"printedPage":44,"answerPage":46},{"id":"ebs-15-06","unit":15,"number":6,"type":"short","title":"6. 밑줄 친 ‘이 운동’의 명칭을 쓰시오.","text":"6. 밑줄 친 ‘이 운동’의 명칭을 쓰시오.\n\n\n 1970년부터 농촌 환경 개선을 시작으로 이 운동이\n\n 추진되었으며, 점차 도시로 확산되어 근면·자조·\n\n 협동을 강조하는 전국적인 의식 개혁 운동으로 이\n\n 어졌다. 그러나 유신 체제 합리화에 이용되었다는\n\n 평가를 받기도 한다.\n\n\n                                      (                        )","image":"assets/questions/ebs-15-06.webp","answer":"새마을\t운동","explanation":"해설\t|\t자료에서 1970년부터 농촌 환경 개선을 시작으로 추\n진되었다는 점, 근면·자조·협동을 강조하였다는 점 등\n을 통해 밑줄 친 ‘이 운동’은 새마을 운동임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":45,"printedPage":44,"answerPage":46},{"id":"ebs-15-07","unit":15,"number":7,"type":"choice","title":"7. 다음 경제 정책이 끼친 영향으로 적절한 것만을 <보기>","text":"7. 다음 경제 정책이 끼친 영향으로 적절한 것만을 <보기>\n에서 고른 것은?\n\n\n 박정희 정부는 수출 주도형 경제 개발을 추진하는\n\n 과정에서 수출 가격 경쟁력을 내세워 노동자의 낮\n\n 은 임금을 강요하였다. 이러한 저임금을 유지하려\n\n 면 노동자의 생계비를 최소화하여야 했기 때문에\n\n 쌀의 가격을 물가 상승률보다 낮게 책정하는 저곡\n\n 가 정책도 추진하였다.\n\n\n      < 보기 >\n ㄱ. ‌원산 총파업이 일어났다.\n\n ㄴ. ‌도시와 농촌의 소득 격차가 심화되었다.\n\n ㄷ. ‌강주룡이 을밀대 지붕에서 농성을 벌였다.\n\n ㄹ. ‌전태일이 근로 기준법 준수를 요구하며 분신하\n\n   였다.\n\n\n① ‌ㄱ, ㄴ    ② ㄱ, ㄷ    ③ ㄴ, ㄷ\n\n④ ‌ㄴ, ㄹ    ⑤ ㄷ, ㄹ","image":"assets/questions/ebs-15-07.webp","answer":"④","explanation":"해설\t|\t자료에서 박정희 정부가 노동자의 낮은 임금을 강\n요하였다는 점, 저곡가 정책을 추진하였다는 점 등을 통\n해 농민과 노동자가 어려움을 겪었을 것을 추론할 수 있\n다. ㄴ. 경제 개발 계획의 결과 도시와 농촌 간 소득 격차\n가 심해졌다. 이는 1970년부터 새마을 운동이 추진되는 \n배경이 되었다. ㄹ. 1970년 전태일은 열악한 노동자들의 \n처지 개선을 위해 근로 기준법 준수 등을 요구하며 분신\n하였다.\n오답\t피하기\t|\tㄱ, ㄷ. 모두 일제 강점기에 있었던 노동 운\n동에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":45,"printedPage":44,"answerPage":46},{"id":"ebs-15-08","unit":15,"number":8,"type":"choice","title":"8. 다음 탄원서가 제출된 시기를 연표에서 옳게 고른 것","text":"8. 다음 탄원서가 제출된 시기를 연표에서 옳게 고른 것\n은?\n\n\n 저(전태일)는 제품(의류) 계통에 종사하는 재단사\n\n 입니다. …… 저의 직장은 시내 동대문구 평화 시\n\n 장으로써 …… 저희들의 요구는 1일 14시간의 작\n\n 업 시간을 단축하십시오. 1일 10시간~12시간을, 1\n\n 개월 휴일 2일을 일요일마다 휴일로 쉬기를 희망\n\n 합니다. …… 시다공의 수당 현 70원 내지 100원을\n\n 50% 이상 인상하십시오. …… 인간으로서의 최소\n\n 한의 요구입니다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n   8·15  대한민국   4·19    5·16    5·18    6월\n  광복  정부 수립  혁명  군사 정변 민주화 민주 항쟁\n                       운동\n\n① ‌(가)  ② (나)  ③ (다)  ④ ‌(라)  ⑤ (마)","image":"assets/questions/ebs-15-08.webp","answer":"④","explanation":"해설\t|\t자료에서 전태일이 작업 시간 단축과 임금 인상 등\n을 요구한다는 점 등을 통해 박정희 정부 시기에 작성된 \n탄원서임을 알 수 있다. 5·16 군사 정변은 1961년, 5·18 \n민주화 운동은 1980년에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":45,"printedPage":44,"answerPage":46},{"id":"blank-15","unit":15,"number":9,"type":"blank","title":"1980년대 중반의 3저 호황은 저유가·저금리·____를 가리킨다.","text":"1980년대 중반의 3저 호황은 저유가·저금리·____를 가리킨다.","answer":"저달러","explanation":"국제 경제의 유리한 조건이 한국의 수출과 경제 성장에 도움을 주었다.","criteria":[],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":72},{"id":"essay-15","unit":15,"number":10,"type":"essay","title":"한국의 산업화가 가져온 성과 한 가지와 사회적 과제 두 가지를 설명하시오.","text":"한국의 산업화가 가져온 성과 한 가지와 사회적 과제 두 가지를 설명하시오.","answer":"수출 확대와 중화학 공업의 성장으로 산업 기반과 국민 경제 규모가 커졌다. 그러나 저임금·장시간 노동 등 노동 문제, 도시와 농촌의 격차 및 환경 오염 같은 문제를 해결해야 했다.","explanation":"수출 확대와 중화학 공업의 성장으로 산업 기반과 국민 경제 규모가 커졌다. 그러나 저임금·장시간 노동 등 노동 문제, 도시와 농촌의 격차 및 환경 오염 같은 문제를 해결해야 했다.","criteria":["수출 확대 또는 산업 기반 성장","저임금·장시간 노동 문제","도농 격차 또는 환경 오염"],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":72},{"id":"ebs-16-01","unit":16,"number":1,"type":"short","title":"1. 다음 자료의 사건이 무엇인지 쓰시오.","text":"1. 다음 자료의 사건이 무엇인지 쓰시오.\n\n\n  1971년 서울 도심을 정비하기 위해 10만여 명을 오\n\n 늘날의 경기도 성남으로 이주시키는 과정에서 편\n\n 의 시설 정비를 약속한 서울시가 이를 지키지 않아\n\n 이주민이 집단 반발하였다. 이주민들은 긴급 구호\n\n 물자 제공과 조세 부과 연기 등을 주장하며 경찰과\n\n 대치하였다.\n\n\n                                      (                        )","image":"assets/questions/ebs-16-01.webp","answer":"광주\t대단지\t사건","explanation":"해설\t| 자료에서 1971년에 강제 이주된 서울의 많은 철거\n민들이 서울시의 편의 시설 정비 등 약속이 지켜지지 않\n은 것에 반발하여 경찰과 대치하였다는 내용 등을 통해 \n광주 대단지 사건에 대한 것임을 알 수 있다. 산업화의 결\n과 도시화가 빠르게 진행되면서 발생한 사건이다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":47,"printedPage":46,"answerPage":49},{"id":"ebs-16-02","unit":16,"number":2,"type":"choice","title":"2. (가)에 들어갈 내용으로 가장 적절한 것은?","text":"2. (가)에 들어갈 내용으로 가장 적절한 것은?\n\n\n 자료는 혼식과 분식을 장려하는 내용이 담긴 포스터입니다. 1970\n 년대 정부는      (가)   문제를 해소하고자 혼식과 분식을\n 장려하였습니다.\n\n\n\n\n\n① 쌀‌ 부족\n\n② ‌미곡 공출\n\n③ ‌군포 부담\n\n④ ‌관료전 폐지\n\n⑤ ‌방납의 폐단","image":"assets/questions/ebs-16-02.webp","answer":"①","explanation":"해설\t|\t자료에서 혼식과 분식을 장려하고 있다는 점, 1970\n년대 정부가 이 문제를 해결하기 위해 노력하였다는 점 \n등을 통해 (가)에는 ‘쌀 부족’이 들어가는 것이 가장 적절\n한다는 것을 알 수 있다. \n오답\t피하기\t|\t② 일제 강점기, ③ 조선 시대, ④ 신라 시대, \n⑤ 조선 시대에 해당하는 내용이다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":47,"printedPage":46,"answerPage":49},{"id":"ebs-16-03","unit":16,"number":3,"type":"choice","title":"3. 다음 자료를 활용한 탐구 주제로 가장 적절한 것은?","text":"3. 다음 자료를 활용한 탐구 주제로 가장 적절한 것은?\n\n\n         국민 교육 헌장\n\n 우리는 민족중흥의 역사적 사명을 띠고 이 땅에 태\n\n 어났다. 조상의 빛난 얼을 오늘에 되살려, 안으로\n\n 자주독립의 자세를 확립하고, 밖으로 인류 공영에\n\n 이바지할 때다. ……\n\n\n① ‌고려 후기 성균관의 설립\n\n② ‌조선 후기 교육 입국 조서의 반포\n\n③ ‌통일 신라 시기 독서삼품과의 시행\n\n④ ‌일제 강점기 제1차 조선 교육령의 내용\n\n⑤ ‌박정희 정부 시기 국가주의 교육의 강화","image":"assets/questions/ebs-16-03.webp","answer":"⑤","explanation":"해설\t|\t자료는 박정희 정부 시기인 1968년에 만들어진 국\n민 교육 헌장이다. 박정희 정부는 학교에서 국민 교육 헌\n장을 외우게 하고 군사 교육과 반공 교육 등 국가주의 교\n육을 강화하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":47,"printedPage":46,"answerPage":49},{"id":"ebs-16-04","unit":16,"number":4,"type":"choice","title":"4. 밑줄 친 ‘이 정부’ 시기에 있었던 사실로 옳은 것은?","text":"4. 밑줄 친 ‘이 정부’ 시기에 있었던 사실로 옳은 것은?\n\n\n 1960년대 이 정부 시기에        맞아. 교련 수업에서 남학\n 는 고등학교에서 교련 수      생은 총검술 등, 여학생은\n 업이 필수로 시행되었어.      응급 처치 등을 배웠지.\n\n\n\n\n\n① ‌육영 공원이 설립되었다.\n\n② ‌신흥 강습소가 세워졌다.\n\n③ ‌학도 지원병제가 시행되었다.\n\n④ ‌중학교 진학이 추첨제로 바뀌었다.\n\n⑤ ‌소학교 명칭이 국민학교로 변경되었다.","image":"assets/questions/ebs-16-04.webp","answer":"④","explanation":"해설\t|\t자료에서 1960년대 고등학교에서 교련 수업이 필수\n로 시행되었다는 점 등을 통해 밑줄 친 ‘이 정부’는 박정희 \n정부임을 알 수 있다. 박정희 정부 시기에 입시 경쟁과 사\n교육비 증가 등의 문제를 해결하고자 중학교 진학을 추첨\n제로 바꾸어 중학교 무시험 진학 제도를 실시하였다.\n오답\t피하기\t|\t① 조선 후기 근대 교육 기관으로 육영 공원\n이 설립되었다. ② 신민회는 무장 투쟁을 위해 만주에 신\n흥 강습소를 세웠다. ③ 중일 전쟁을 일으킨 일제는 침략 \n전쟁을 확대하면서 병력을 확보하기 위해 학도 지원병제\n를 시행하였다. ⑤ 일제 강점기에 소학교 명칭이 국민학\n교로 변경되었다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":47,"printedPage":46,"answerPage":49},{"id":"ebs-16-05","unit":16,"number":5,"type":"choice","title":"5. 다음 사건을 순서대로 바르게 나열한 것은?","text":"5. 다음 사건을 순서대로 바르게 나열한 것은?\n\n\n  (가) 초등‌  교육이 의무화되었다.\n\n  (나) ‌국민 교육 헌장이 반포되었다.\n\n  (다) ‌고교 평준화 제도가 도입되었다.\n\n\n① (가)‌  - (나) - (다)\n\n② ‌(가) - (다) - (나)\n\n③ ‌(나) - (가) - (다)\n\n④ ‌(나) - (다) - (가)\n\n⑤ ‌(다) - (가) - (나)","image":"assets/questions/ebs-16-05.webp","answer":"①","explanation":"해설\t|\t(가)는 1950년대, (나)는 1968년, (다)는 1970년대에 \n해당한다. 6·25 전쟁 이후 어려운 여건에서도 많은 사람\n들이 자녀 교육에 힘썼으며, 이에 이승만 정부는 초등 교\n육 의무 교육제를 시행하였다. 박정희 정부는 1968년 국\n민 교육 헌장을 만들어 학교에서 외우게 하는 등 국가주\n의 교육을 강화하였다. 경제 성장과 인구 증가로 교육은 \n양적으로 크게 성장한 반면, 입시 경쟁과 사교육비 증가\n의 문제가 대두되었다. 이를 해결하고자 1970년대 정부는 \n고교 입학시험을 연합고사로 바꾸고 고교 평준화 제도를 \n도입하여 확대해 나갔다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":48,"printedPage":47,"answerPage":49},{"id":"ebs-16-06","unit":16,"number":6,"type":"choice","title":"6. (가)에 들어갈 내용으로 옳은 것은?","text":"6. (가)에 들어갈 내용으로 옳은 것은?\n\n\n [한국사 학습 내용 정리]\n\n       언론과 대중문화의 변화\n\n •언론 규제 강화 →      (가)   기자들이 자유\n\n  언론 실천 선언 발표(1974)\n\n\n\n① 제국신문‌\n\n② ‌한성순보\n\n③ ‌독립신문\n\n④ ‌동아일보\n\n⑤ ‌대한매일신보","image":"assets/questions/ebs-16-06.webp","answer":"④","explanation":"해설\t|\t자료에서 언론 규제 강화에 맞서 1974년 자유 언론 \n실천 선언을 발표했다는 점 등을 통해 (가)에는 동아일보\n가 들어가야 한다는 것을 알 수 있다.\n오답\t피하기\t|\t①, ②, ⑤ 국권 피탈 이전에 창간되었던 신\n문이다. ③ 독립 협회, 대한민국 임시 정부에서 독립신문\n을 발행하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":48,"printedPage":47,"answerPage":49},{"id":"ebs-16-07","unit":16,"number":7,"type":"choice","title":"7. (가)에 들어갈 내용으로 옳은 것은?","text":"7. (가)에 들어갈 내용으로 옳은 것은?\n\n\n\n 1970년대 대중문   텔레비전 보급이\n 화 확산에 대해 말    확대되었어.               (가)\n 해보자.\n\n\n\n\n\n① ‌조선일보가 창간되었어.\n\n② ‌신간회가 순회 강연을 열었어.\n\n③ ‌신채호가 독사신론을 연재하였어.\n\n④ ‌청바지 등 청년 문화가 유행하였어.\n\n⑤ ‌나운규가 영화 아리랑을 제작하였어.","image":"assets/questions/ebs-16-07.webp","answer":"④","explanation":"해설\t|\t자료에서 1970년대 대중문화 확산에 대해 이야기하\n고 있다는 점, 텔레비전 보급이 확대되었다는 점 등을 통\n해 (가)에는 청바지 등 청년 문화가 유행하였다는 내용이 \n들어가는 것이 옳다는 것을 알 수 있다.\n오답\t피하기\t|\t① 조선일보는 일제 강점기인 1920년에 창간\n되었다. ② 신간회는 1927년에 창립되었다. ③ 신채호는 \n국권 피탈 이전 대한매일신보에 독사신론을 연재하였다. \n⑤ 일제 강점기에 나운규는 영화 아리랑을 제작하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":48,"printedPage":47,"answerPage":49},{"id":"ebs-16-08","unit":16,"number":8,"type":"choice","title":"8. 밑줄 친 ‘이 정부’에 해당하는 것은?","text":"8. 밑줄 친 ‘이 정부’에 해당하는 것은?\n\n\n 프로 야구는 이 정부 시기 동대문 야구장에서 열린\n\n 개막식으로 시작되었다. 이후 큰 인기를 끌어 개막\n\n 식 이듬해에 관중 200만 명을 돌파하였다. 이 정부\n\n 시기에 상업적 프로 스포츠 시대가 열렸지만, 언론\n\n 과 문화 통제는 여전하였다.\n\n\n① ‌이승만 정부\n\n② ‌박정희 정부\n\n③ ‌전두환 정부\n\n④ ‌노태우 정부\n\n⑤ ‌김영삼 정부","image":"assets/questions/ebs-16-08.webp","answer":"③","explanation":"해설\t|\t자료에서 프로 야구 개막식이 동대문 야구장에서 \n열렸다는 점 등을 통해 밑줄 친 ‘이 정부’는 전두환 정부임\n을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":48,"printedPage":47,"answerPage":49},{"id":"blank-16","unit":16,"number":9,"type":"blank","title":"1969년 도입되어 중학교 진학 단계의 입학시험을 없앤 제도는 ____ 제도이다.","text":"1969년 도입되어 중학교 진학 단계의 입학시험을 없앤 제도는 ____ 제도이다.","answer":"중학교 무시험 진학","explanation":"중등 교육의 기회를 넓히고 과도한 입시 경쟁을 완화하기 위한 정책이었다.","criteria":[],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":77},{"id":"essay-16","unit":16,"number":10,"type":"essay","title":"산업화에 따른 도시화가 일상생활에 가져온 변화와 문제점을 설명하시오.","text":"산업화에 따른 도시화가 일상생활에 가져온 변화와 문제점을 설명하시오.","answer":"농촌 인구가 도시로 이동하고 아파트·대중교통 등 도시 생활이 확대되었다. 그러나 급속한 인구 집중으로 주택 부족과 교통 혼잡, 도시 빈민 문제가 발생했으며 농촌은 인구 감소와 고령화, 도농 격차를 겪었다.","explanation":"농촌 인구가 도시로 이동하고 아파트·대중교통 등 도시 생활이 확대되었다. 그러나 급속한 인구 집중으로 주택 부족과 교통 혼잡, 도시 빈민 문제가 발생했으며 농촌은 인구 감소와 고령화, 도농 격차를 겪었다.","criteria":["농촌에서 도시로 인구 이동","주택·교통·도시 빈민 문제","농촌 인구 감소 또는 도농 격차"],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":77},{"id":"ebs-17-01","unit":17,"number":1,"type":"choice","title":"1. 밑줄 친 ‘창당’이 있었던 시기를 연표에서 옳게 고른 것","text":"1. 밑줄 친 ‘창당’이 있었던 시기를 연표에서 옳게 고른 것\n은?\n\n\n 제13대 국회 의원 선거 결과, 당시 여당인 민주 정\n\n 의당보다 야당인 평화 민주당, 통일 민주당, 신민\n\n 주 공화당의 의석수를 합한 것이 더 많게 되었는\n\n 데, 이렇게 구성된 국회 상황을 여소야대 국회라고\n\n 한다. 이후 여당은 정국 운영을 주도적으로 장악하\n\n 기 위해 김영삼과 김종필이 이끄는 두 정당과 합당\n\n 하여 민주 자유당을 창당하였다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n  8·15  대한민국   4·19    5·18    6월   김영삼\n  광복  정부 수립  혁명   민주화 민주 항쟁  정부\n                 운동        출범\n\n① (가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-17-01.webp","answer":"⑤","explanation":"해설\t| 자료에서 제13대 국회 의원 선거 결과 여소야대 국\n회가 만들어졌다는 점, 여당이 김영삼과 김종필이 이끄는 \n두 정당과 합당하여 민주 자유당을 창당하였다는 점 등을 \n통해 밑줄 친 ‘창당’은 노태우 정부 시기에 있었던 3당 합\n당과 관련된 것임을 알 수 있다. 노태우 정부는 1987년 6\n월 민주 항쟁 이후 제정된 헌법에 의해 1988년 출범하였\n다. 김영삼 정부 출범은 1993년에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":50,"printedPage":49,"answerPage":52},{"id":"ebs-17-02","unit":17,"number":2,"type":"choice","title":"2. (가) 정부에 대한 설명으로 옳은 것은?","text":"2. (가) 정부에 대한 설명으로 옳은 것은?\n\n\n  5·16 군사 정변 이후 31년 만에 민간인 출신 후보\n\n 자가 대통령에 당선되어 수립된      (가)    은/는\n\n 고위 공직자 재산 공개 등을 시행하여 부정부패 척\n\n 결에 앞장섰다. 또한 ‘역사 바로 세우기’ 운동을 전\n\n 개하였다.\n\n\n① 국가‌  총동원법을 제정하였다.\n\n② ‌사사오입 개헌을 단행하였다.\n\n③ ‌남북 정상 회담을 개최하였다.\n\n④ ‌지방 자치제를 전면 시행하였다.\n\n⑤ ‌선거를 통한 여야 정권 교체로 성립되었다.","image":"assets/questions/ebs-17-02.webp","answer":"④","explanation":"해설\t|\t자료에서 5·16 군사 정변 이후 31년 만에 민간인 \n출신 후보자가 대통령에 당선되었다는 점, ‘역사 바로 세\n우기’ 운동을 전개하였다는 점 등을 통해 (가) 정부는 김영\n삼 정부임을 알 수 있다. 김영삼 정부는 지방 자치제를 전\n면 시행하였다.\n오답\t피하기\t|\t① 국가 총동원법은 일제 강점기에 제정되었\n다. ② 사사오입 개헌은 이승만 정부 시기에 단행되었다. \n③ 남북 정상 회담은 김대중 정부, 노무현 정부, 문재인 \n정부 시기에 개최되었다. ⑤ 대한민국 정부 수립 이후 선\n거를 통한 최초의 여야 정권 교체로 김대중 정부가 출범\n하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":50,"printedPage":49,"answerPage":52},{"id":"ebs-17-03","unit":17,"number":3,"type":"short","title":"3. 밑줄 친 ‘이 정부’는 무엇인지 쓰시오.","text":"3. 밑줄 친 ‘이 정부’는 무엇인지 쓰시오.\n\n\n 1993년 출범한 이 정부       맞아. 그리고 5·18 민주\n 는 공직자 윤리법을 개정     화 운동 등에 관한 특별\n 하여 고위 공직자의 재산     법을 제정하고 전두환·\n 공개를 의무화하였어.       노태우 두 전직 대통령을\n                    처벌하였지.\n\n\n\n\n\n                                      (                        )","image":"assets/questions/ebs-17-03.webp","answer":"김영삼\t정부","explanation":"해설\t|\t자료에서 1993년에 출범하였다는 점, 5·18 민주화 \n운동 등에 관한 특별법을 제정하였다는 점 등을 통해 밑\n줄 친 ‘이 정부’는 김영삼 정부임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":50,"printedPage":49,"answerPage":52},{"id":"ebs-17-04","unit":17,"number":4,"type":"choice","title":"4. 밑줄 친 ㉠에 해당하는 인물로 옳은 것은?","text":"4. 밑줄 친 ㉠에 해당하는 인물로 옳은 것은?\n\n\n 제15대 대통령 선거에서 ㉠ 야당의 후보가 당선되\n\n 면서 처음으로 선거에 의한 평화적 여야 정권 교체\n\n 가 이루어졌다. 이 정부는 인사 청문회법을 제정하\n\n 여 고위 공직자의 능력과 도덕성을 공개적으로 검\n\n 증하였다.\n\n\n① ‌박정희\n\n② ‌이승만\n\n③ ‌김대중\n\n④ ‌윤보선\n\n⑤ ‌조봉암","image":"assets/questions/ebs-17-04.webp","answer":"③","explanation":"해설\t|\t자료에서 제15대 대통령 선거에 야당 후보로 출마\n하여 당선되었다는 점, 처음으로 선거에 의한 평화적 여\n야 정권 교체가 이루어졌다는 점, 인사 청문회법을 제정\n하였다는 점 등을 통해 밑줄 친 ㉠에 해당하는 인물은 김\n대중임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":50,"printedPage":49,"answerPage":52},{"id":"ebs-17-05","unit":17,"number":5,"type":"choice","title":"5. (가), (나) 시기 사이에 있었던 사실로 옳은 것은?","text":"5. (가), (나) 시기 사이에 있었던 사실로 옳은 것은?\n\n\n  (가) 6월‌  민주 항쟁 이후 처음 치러진 대통령 선거\n\n   에서 여당의 후보가 당선되었다.\n\n  (나) ‌외환 위기 속에서 치러진 제15대 대통령 선거\n\n   에서 야당의 후보가 당선되었다.\n\n\n① 김영삼‌   정부가 출범하였다.\n\n② ‌흥선 대원군이 집권하였다.\n\n③ ‌김구가 주석으로 활동하였다.\n\n④ ‌장면이 국무총리로 취임하였다.\n\n⑤ ‌김규식이 파리 강화 회의에 파견되었다.","image":"assets/questions/ebs-17-05.webp","answer":"①","explanation":"해설\t|\t(가)는 6월 민주 항쟁 이후 처음 치러진 대통령 선\n거에서 여당 후보가 당선되었다는 점을 통해 1987년의 상\n황임을 알 수 있다. (나)는 외환 위기 속에서 치러진 제15\n대 대통령 선거에서 야당 후보가 당선되었다는 점을 통해 \n1997년의 상황임을 알 수 있다. 김영삼 정부는 1993년에 \n출범하였다.\n오답\t피하기\t|\t② 조선 후기, ③, ⑤ 일제 강점기에 해당한\n다. ④ 1960년 4·19 혁명 이후 장면이 국무총리로 취임\n하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":51,"printedPage":50,"answerPage":52},{"id":"ebs-17-06","unit":17,"number":6,"type":"choice","title":"6. (가) 정부에 대한 설명으로 옳은 것은?","text":"6. (가) 정부에 대한 설명으로 옳은 것은?\n\n\n 세계 20개국의 정상들이 금융, 경제 등을 논의하\n\n 는 서울 G20 정상 회의는      (가)   정부 시기\n\n 에 한국에서 개최되었다. 서울 G20 정상 회의와 같\n\n 은 세계적으로 영향력 있는 대규모 회의를 개최함\n\n 으로써, 대한민국은 높아진 국제적 위상을 보여 주\n\n 었다.\n\n\n① 지계를‌   발급하였다.\n\n② ‌실용주의 경제를 추구하였다.\n\n③ ‌화폐 정리 사업을 추진하였다.\n\n④ ‌국채 보상 운동을 주도하였다.\n\n⑤ ‌임시 토지 조사국을 설치하였다.","image":"assets/questions/ebs-17-06.webp","answer":"②","explanation":"해설\t|\t자료에서 서울 G20 정상 회의가 개최되었다는 점, \n대한민국의 높아진 국제적 위상을 보여 주었다는 점 등을 \n통해 (가) 정부는 이명박 정부임을 알 수 있다. 이명박 정\n부는 기업 활동의 규제를 완화하는 등 실용주의 경제를 \n추구하였다.\n오답\t피하기\t|\t① 지계 발급, ③ 화폐 정리 사업, ④ 국채 보\n상 운동은 대한 제국 시기에 해당한다. ⑤ 일제는 토지 조\n사 사업을 위해 임시 토지 조사국을 설치하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":51,"printedPage":50,"answerPage":52},{"id":"ebs-17-07","unit":17,"number":7,"type":"choice","title":"7. 다음과 같은 창립 선언문을 발표한 단체로 옳은 것은?","text":"7. 다음과 같은 창립 선언문을 발표한 단체로 옳은 것은?\n\n\n 지금 우리는 시급히 해결해야 할 수많은 사회 문\n\n 제, 인권 문제를 안고 있습니다. 소외된 자, 억압\n\n 받는 자에 대한 무관심은 동료 시민으로서의 신성\n\n 한 의무를 방기하는 태도입니다. 우리는 기필코 신\n\n 체적, 정신적, 사회적으로 어려움에 처한 이웃들이\n\n 보다 인간답게 살 수 있는 여건을 함께 만들어가야\n\n 하겠습니다.\n\n\n① ‌신간회\n\n② ‌참여 연대\n\n③ ‌독립 협회\n\n④ ‌한인 애국단\n\n⑤ ‌조선 민족 전선 연맹","image":"assets/questions/ebs-17-07.webp","answer":"②","explanation":"해설\t|\t수많은 사회 문제, 인권 문제가 있다는 점, 인간답\n게 살 수 있는 여건을 함께 만들어가야 하겠다는 점 등을 \n통해 자료는 참여 연대의 창립 선언문임을 알 수 있다.\n오답\t피하기\t|\t①, ④, ⑤ 일제 강점기에 활동한 단체이다. \n③ 독립 협회는 1896년에 창립되었다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":51,"printedPage":50,"answerPage":52},{"id":"ebs-17-08","unit":17,"number":8,"type":"choice","title":"8. (가)에 들어갈 내용으로 가장 적절한 것은?","text":"8. (가)에 들어갈 내용으로 가장 적절한 것은?\n\n\n       (가)    은/는 시민이 자발적으로 참여하는 평\n\n 화적 시위 형태이다. 사회에 대한 다양한 의견을\n\n 자유롭게 표현하고 소통하는 민주주의의 장 역할을\n\n 하기도 한다.\n\n\n① ‌촛불 집회\n\n② ‌의열 활동\n\n③ ‌무장 투쟁\n\n④ ‌의거 활동\n\n⑤ ‌국내 진공 작전","image":"assets/questions/ebs-17-08.webp","answer":"①","explanation":"해설\t|\t자료에서 시민들이 자발적으로 참여하는 평화적 시\n위 형태라는 점, 민주주의의 장 역할을 하기도 한다는 점 \n등을 통해 (가)에는 촛불 집회가 들어가는 것이 가장 적절\n하다는 것을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":51,"printedPage":50,"answerPage":52},{"id":"blank-17","unit":17,"number":9,"type":"blank","title":"1993년 김영삼 정부가 실제 명의로 금융 거래를 하도록 실시한 제도는 ____이다.","text":"1993년 김영삼 정부가 실제 명의로 금융 거래를 하도록 실시한 제도는 ____이다.","answer":"금융 실명제","explanation":"금융 거래의 투명성을 높이고 부정한 자금 거래를 줄이기 위한 제도였다.","criteria":[],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":82},{"id":"essay-17","unit":17,"number":10,"type":"essay","title":"6월 민주 항쟁 이후 민주주의가 발전한 사례를 제도와 시민 참여 측면에서 설명하시오.","text":"6월 민주 항쟁 이후 민주주의가 발전한 사례를 제도와 시민 참여 측면에서 설명하시오.","answer":"대통령 직선제와 지방 자치 전면 실시로 국민의 정치적 선택과 참여가 확대되었다. 선거를 통한 여야 간 평화적 정권 교체가 이루어졌으며, 시민 단체와 인권·환경 운동이 성장하여 권력을 감시하고 사회 문제 해결에 참여했다.","explanation":"대통령 직선제와 지방 자치 전면 실시로 국민의 정치적 선택과 참여가 확대되었다. 선거를 통한 여야 간 평화적 정권 교체가 이루어졌으며, 시민 단체와 인권·환경 운동이 성장하여 권력을 감시하고 사회 문제 해결에 참여했다.","criteria":["직선제 또는 지방 자치 확대","선거를 통한 평화적 정권 교체","시민 단체 성장과 권력 감시"],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":82},{"id":"ebs-18-01","unit":18,"number":1,"type":"choice","title":"1. 다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?","text":"1. 다음 자료를 활용한 탐구 활동으로 가장 적절한 것은?\n\n                 (%)\n                  14\n                                     1997 외환 위기\n                   12\n\n                 10\n\n               8\n\n                6\n\n                4\n\n                 2\n\n               0\n\n              -2\n\n              -4\n                                      -5.5\n              -6\n                   1985    1990    1995   2000   2005(년)\n                  - 국가통계포털(국제통계연감: 경제 성장률), 2017 -\n\n① 지계를‌   발급한 기관을 살펴본다.\n\n② ‌임시 토지 조사국이 운영된 기간을 조사한다.\n\n③ ‌조선 물산 장려회가 만들어진 지역을 정리한다.\n\n④ ‌제1차 경제 개발 5개년 계획이 시작된 시기를 알아\n\n  본다.\n\n⑤ ‌국제 통화 기금[IMF]에 구제 금융을 요청한 시기를\n\n  파악한다.","image":"assets/questions/ebs-18-01.webp","answer":"⑤","explanation":"해설\t| 자료에서 1997년의 경제 성장률이 –5.5%라는 점, \n1997년이 외환 위기라고 표시된 점 등을 통해 국제 통화 \n기금[IMF]에 구제 금융을 요청한 시기를 파악하는 탐구 \n활동이 가장 적절함을 알 수 있다. \n오답\t피하기\t|\t① 지계는 대한 제국 시기에 발급되었다. ② \n임시 토지 조사국은 일제 강점기에 운영되었다. ③ 일제 \n강점기 평양에서 조선 물산 장려회가 조직되어 물산 장려 \n운동을 주도하였다. ④ 제1차 경제 개발 5개년 계획은 박\n정희 정부 시기인 1962년에 시작되었다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":53,"printedPage":52,"answerPage":55},{"id":"ebs-18-02","unit":18,"number":2,"type":"short","title":"2. 밑줄 친 ‘이 정부’는 무엇인지 쓰시오.","text":"2. 밑줄 친 ‘이 정부’는 무엇인지 쓰시오.\n\n\n 동남아시아가 외환 위기에 빠지면서 국내에서도 외\n\n 국 투자자들이 대출을 대거 회수하였다. 이에 외환\n\n 보유고가 고갈되어 외채에 의존하던 기업들이 연쇄\n\n 적으로 부도를 맞았다. 결국 이 정부는 국제 통화\n\n 기금[IMF]에 구제 금융을 요청하였다.\n\n\n                                      (                        )","image":"assets/questions/ebs-18-02.webp","answer":"김영삼\t정부","explanation":"해설\t|\t자료에서 외환 보유고가 고갈되어 외채에 의존하던 \n기업들이 연쇄적으로 부도를 맞았다는 점, 국제 통화 기\n금[IMF]에 구제 금융을 요청하였다는 점 등을 통해 밑줄 \n친 ‘이 정부’는 김영삼 정부임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":53,"printedPage":52,"answerPage":55},{"id":"ebs-18-03","unit":18,"number":3,"type":"choice","title":"3. (가)에 들어갈 내용으로 옳은 것은?","text":"3. (가)에 들어갈 내용으로 옳은 것은?\n\n\n 1990년대 말 발생   구조 조정을 실시\n 한 외환 위기를 극    하였어.\n                                                (가)\n 복하기 위한 노력\n 에 대해 말해보자.\n\n\n\n\n\n① ‌군포를 징수하였어.\n\n② ‌대동법을 실시하였어.\n\n③ ‌미곡 공출을 시행하였어.\n\n④ ‌농지 개혁법을 제정하였어.\n\n⑤ ‌공기업 민영화를 추진하였어.","image":"assets/questions/ebs-18-03.webp","answer":"⑤","explanation":"해설\t|\t자료에서 1990년대 말 발생한 외환 위기 극복 노력\n에 대해 이야기하고 있다는 점, 구조 조정을 실시하였다\n는 점 등을 통해 (가)에는 공기업 민영화를 추진하였다는 \n내용이 들어가는 것이 옳다는 것을 알 수 있다.\n오답\t피하기\t|\t① 군포 징수, ② 대동법 실시는 조선 시대, \n③ 미곡 공출은 일제 강점기, ④ 농지 개혁법 제정은 이승\n만 정부 시기에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":53,"printedPage":52,"answerPage":55},{"id":"ebs-18-04","unit":18,"number":4,"type":"choice","title":"4. 다음 운동이 전개된 배경으로 가장 적절한 것은?","text":"4. 다음 운동이 전개된 배경으로 가장 적절한 것은?\n\n\n\n\n\n    ▲부족한 외화를 확보하자는 구호 아래 전개된 금 모으기 운동\n\n① ‌두 차례에 걸친 석유 파동이 일어났다.\n\n② ‌미국과 자유 무역 협정[FTA]이 체결되었다.\n\n③ ‌유상 매입의 원칙 아래 농지 개혁이 추진되었다.\n\n④ ‌국제 통화 기금[IMF]의 구제 금융이 이루어졌다.\n\n⑤ ‌전태일이 근로 기준법 준수를 요구하며 분신하였다.","image":"assets/questions/ebs-18-04.webp","answer":"④","explanation":"해설\t|\t자료는 외환 위기를 극복하기 위해 전개된 금 모으\n기 운동에 관한 것이다. 1997년 말 외환 위기로 김영삼 정\n부는 국제 통화 기금에 구제 금융을 요청하였고, 외환 위\n기를 극복하기 위한 금 모으기 운동이 전개되었다.\n오답\t피하기\t|\t①, ⑤ 박정희 정부 시기, ② 노무현 정부 시\n기, ③ 이승만 정부 시기에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":53,"printedPage":52,"answerPage":55},{"id":"ebs-18-05","unit":18,"number":5,"type":"choice","title":"5. 밑줄 친 ‘상환’이 있었던 시기를 연표에서 옳게 고른 것","text":"5. 밑줄 친 ‘상환’이 있었던 시기를 연표에서 옳게 고른 것\n은?\n\n\n 외환 위기 당시 부족한 외화를 확보하기 위해 국민\n\n 들이 자발적으로 금 모으기 운동을 전개하였다. 이\n\n 운동을 통해 전국 각지에서 금을 모았고, 이는 부\n\n 족한 외환을 보충하는 데 도움이 되었다. 이러한\n\n 정부와 국민의 노력이 모여 국제 통화 기금[IMF]의\n\n 지원금을 조기에 상환하였다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n 전두환  노태우  김영삼  김대중  노무현  이명박\n  정부   정부   정부   정부   정부   정부\n  출범   출범   출범   출범   출범   출범\n\n① (가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-18-05.webp","answer":"④","explanation":"해설\t|\t자료에서 외환 위기 당시 부족한 외화를 확보하기 \n위해 금 모으기 운동이 전개되었다는 점, 정부와 국민의 \n노력이 모여 국제 통화 기금[IMF]의 지원금을 조기에 상\n환하였다는 점 등을 통해 밑줄 친 ‘상환’은 김대중 정부 시\n기에 있었다는 것을 알 수 있다. 국제 통화 기금의 지원금\n을 2001년에 조기 상환하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":54,"printedPage":53,"answerPage":55},{"id":"ebs-18-06","unit":18,"number":6,"type":"choice","title":"6. 밑줄 친 ㉠에 해당하는 내용으로 가장 적절한 것은?","text":"6. 밑줄 친 ㉠에 해당하는 내용으로 가장 적절한 것은?\n\n\n 외환 위기를 극복하는 과정에서 구조 조정을 실시\n\n 하였고, 이는 우리 사회에 ㉠ 많은 변화를 가져왔다.\n\n\n① 회사령이‌    폐지되었다.\n\n② ‌원산 총파업이 전개되었다.\n\n③ ‌비정규직 노동자가 크게 늘었다.\n\n④ ‌조선 노농 총동맹이 결성되었다.\n\n⑤ ‌조선 총독부의 지세 수입이 증가하였다.","image":"assets/questions/ebs-18-06.webp","answer":"③","explanation":"해설\t|\t자료에서 외환 위기를 극복하는 과정에서 구조 조\n정을 실시하였다는 점 등을 통해 밑줄 친 ㉠에 해당하는 \n내용으로 비정규직 노동자가 크게 늘었다는 것이 가장 적\n절하다는 것을 알 수 있다.\n오답\t피하기\t|\t①, ②, ④, ⑤ 모두 일제 강점기에 해당하는 \n내용이다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":54,"printedPage":53,"answerPage":55},{"id":"ebs-18-07","unit":18,"number":7,"type":"short","title":"7. (가)에 들어갈 내용을 쓰시오.","text":"7. (가)에 들어갈 내용을 쓰시오.\n\n\n 우리나라는 2004년 칠레와 협정이 발효된 것\n\n 을 시작으로 미국 및 유럽 연합[EU], 중국 등과\n\n       (가)    을/를 체결하였다.      (가)    은/는\n\n 국가 간의 자유로운 무역 활동을 위해 무역 장벽을\n\n 완화시키거나 제거하는 협정이다.\n\n\n                                      (                        )","image":"assets/questions/ebs-18-07.webp","answer":"자유\t무역\t협정[FTA]","explanation":"해설\t|\t자료에서 2004년에 발효된 칠레와의 협정이 시작\n이라는 점, 미국, 유럽 연합, 중국 등과도 체결하였다는 \n점, 국가 간의 자유로운 무역 활동을 위해 무역 장벽을 완\n화시키거나 제거하는 협정이라는 점 등을 통해 (가)는 자\n유 무역 협정임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":54,"printedPage":53,"answerPage":55},{"id":"ebs-18-08","unit":18,"number":8,"type":"choice","title":"8. 밑줄 친 ㉠에 해당하는 내용으로 옳지 않은 것은?","text":"8. 밑줄 친 ㉠에 해당하는 내용으로 옳지 않은 것은?\n\n\n [한국사 학습 내용 정리]\n\n    6월 민주 항쟁 이후 사회와 문화의 변동\n\n •다문화 사회로의 변화\n\n •저출산·고령화 현상 심화\n\n •정보화와 ㉠ 대중문화의 발달\n\n\n\n① ‌독립 공채가 발행되었다.\n\n② ‌한류라는 문화 열풍이 일어났다.\n\n③ ‌케이팝[K-Pop]이 인기를 끌었다.\n\n④ ‌한국 영화가 해외에서 호평을 받았다.\n\n⑤ ‌온라인 동영상 서비스[OTT]를 통해 한국 문화가 전\n\n  파되었다.","image":"assets/questions/ebs-18-08.webp","answer":"①","explanation":"해설\t|\t자료는 6월 민주 항쟁 이후 사회와 문화의 변동과 \n관련된 학습 내용을 정리한 것이다. 밑줄 친 ㉠에 해당하\n는 내용으로 6월 민주 항쟁 이후의 상황이 적절하다는 것\n을 알 수 있다. 6월 민주 항쟁 이후 민주화의 진전으로 한\n류라는 문화 열풍이 일어났다. 2000년 이후에는 한국의 \n대중가요가 케이팝[K-Pop]이라고 불리며 인기를 끌었\n다. 또한 한국 영화가 국제 영화제에서 호평을 받았으며, \n온라인 동영상 서비스[OTT]를 통해 한국 문화가 전파되\n었다.\n오답\t피하기\t|\t① 대한민국 임시 정부는 독립운동에 필요한 \n자금을 마련하기 위해 독립 공채를 발행하였다. ","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":54,"printedPage":53,"answerPage":55},{"id":"blank-18","unit":18,"number":9,"type":"blank","title":"1997년 한국 정부가 구제 금융을 요청한 국제기구의 약칭은 ____이다.","text":"1997년 한국 정부가 구제 금융을 요청한 국제기구의 약칭은 ____이다.","answer":"IMF","explanation":"국제 통화 기금으로, 한국은 구조 조정과 외자 유치 등을 추진한 뒤 2001년 지원금을 조기 상환했다.","criteria":[],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":87},{"id":"essay-18","unit":18,"number":10,"type":"essay","title":"외환 위기를 극복하기 위한 노력 두 가지와 그 과정에서 나타난 사회 문제를 설명하시오.","text":"외환 위기를 극복하기 위한 노력 두 가지와 그 과정에서 나타난 사회 문제를 설명하시오.","answer":"정부는 기업과 금융 기관의 구조 조정 및 외국 자본 유치를 추진했고 국민은 금 모으기 운동에 참여했다. 그러나 구조 조정 과정에서 실업과 고용 불안이 커지고 비정규직 및 소득 격차 문제가 심화되었다.","explanation":"정부는 기업과 금융 기관의 구조 조정 및 외국 자본 유치를 추진했고 국민은 금 모으기 운동에 참여했다. 그러나 구조 조정 과정에서 실업과 고용 불안이 커지고 비정규직 및 소득 격차 문제가 심화되었다.","criteria":["구조 조정·외국 자본 유치","금 모으기 운동","실업·고용 불안 또는 소득 격차"],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":87},{"id":"ebs-19-01","unit":19,"number":1,"type":"choice","title":"1. (가) 인물에 대한 설명으로 옳은 것은?","text":"1. (가) 인물에 대한 설명으로 옳은 것은?\n\n\n 김일성이 사망한 후 그 아들인      (가)    이/가\n\n 권력을 승계하였다. 2011년에는      (가)     의 아\n\n 들인 김정은에게 권력이 승계되면서 3대에 걸친 권\n\n 력 세습이 이루어졌다.\n\n\n① 합영법을 제정하였다.\n\n② 토지 개혁을 추진하였다.\n\n③ 천리마 운동을 시행하였다.\n\n④ 남북 정상 회담을 실시하였다.\n\n⑤ 사회주의 헌법에 따라 주석에 취임하였다.","image":"assets/questions/ebs-19-01.webp","answer":"④","explanation":"해설\t| 자료에서 김일성의 아들이며, 김일성 사망 후 권력\n을 이어받았다는 점, 아들이 김정은이며 북한의 권력이 \n김정은에게 승계되었다는 점 등을 통해 (가) 인물은 김정\n일임을 알 수 있다. 1994년 김일성이 사망한 후 권력을 승\n계한 김정일은 김대중, 노무현 대통령과 두 차례에 걸쳐 \n남북 정상 회담을 개최하였다.\n오답\t피하기\t|\t① 1984년 북한은 외국 자본 유치를 위해 합\n영법을 제정하였다. ② 토지 개혁은 8·15 광복 이후 북한\n에서 시작되었다. 6·25 전쟁 이후에는 협농 농장화가 진\n행되었다. ③ 천리마 운동은 1950년대 후반에 전개되었\n다. ⑤ 사회주의 헌법은 1972년에 제정되었다. 이때 주석\n직이 신설되었고, 김일성이 취임하였다. 김일성 사후 권\n력을 물려받은 김정일은 국방 위원장 자격으로 권력을 차\n지하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":56,"printedPage":55,"answerPage":58},{"id":"ebs-19-02","unit":19,"number":2,"type":"choice","title":"2. 밑줄 친 ‘북미 정상 회담’이 있었던 시기를 연표에서 옳","text":"2. 밑줄 친 ‘북미 정상 회담’이 있었던 시기를 연표에서 옳\n게 고른 것은?\n\n\n 싱가포르에서 최초로 개최된 북미 정상 회담에서\n\n 양국은 새로운 북미 관계를 수립하고 한반도에 평\n\n 화 체제를 정착시키기 위해 노력할 것이라는 선언\n\n 을 발표하였다. 그러나 북한은 이후 핵무기 개발\n\n 등으로 국제적 고립을 자초하고 있다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n  4·19    5·18  노태우  김일성  김정일  윤석열\n  혁명   민주화   정부   사망   사망   정부\n       운동   출범              출범\n\n① (가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-19-02.webp","answer":"⑤","explanation":"해설\t|\t자료에서 싱가포르에서 최초로 개최된 북미 정상 \n회담이라는 점, 새로운 북미 관계 수립 등의 내용을 발표\n하였다는 점 등을 통해 밑줄 친 ‘북미 정상 회담’은 김정은 \n집권 시기인 2018년에 있었던 것임을 알 수 있다. 김정일 \n사망은 2011년, 윤석열 정부 출범은 2022년에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":56,"printedPage":55,"answerPage":58},{"id":"ebs-19-03","unit":19,"number":3,"type":"choice","title":"3. (가)에 들어갈 내용으로 옳은 것은?","text":"3. (가)에 들어갈 내용으로 옳은 것은?\n\n\n 북한은 1991년      (가)  경제 무역 지대를 설치\n\n 하였고, 이곳 안에서는 자유 무역과 시장 개방 등\n\n 이 이루어졌다. 이후에도 여러 지역에 경제특구를\n\n 지정하여 부분적인 개방을 하였으며, 앞으로 더 많\n\n 은 경제 개발구를 설립하겠다는 계획을 발표하기도\n\n 하였다.\n\n\n① 봉오동\n\n② 청산리\n\n③ 대전자령\n\n④ 사도하자\n\n⑤ 나진·선봉","image":"assets/questions/ebs-19-03.webp","answer":"⑤","explanation":"해설\t|\t자료에서 북한이 1991년 경제 무역 지대를 설치하\n였다는 점, 자유 무역과 시장 개방 등이 이루어졌는 점 등\n을 통해 (가)에는 나진·선봉이 들어가야 한다는 것을 알 \n수 있다.\n오답\t피하기\t|\t①, ②, ③, ④ 모두 중국 지역에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":56,"printedPage":55,"answerPage":58},{"id":"ebs-19-04","unit":19,"number":4,"type":"short","title":"4. 다음 남북 성명은 무엇인지 쓰시오.","text":"4. 다음 남북 성명은 무엇인지 쓰시오.\n\n\n 첫째, ‌통일은 외세에 의존하거나 외세의 간섭을 받\n\n    지 않고 자주적으로 해결하여야 한다.\n\n 둘째, ‌통일은 서로 상대방을 반대하는 무력 행사에\n\n    의거하지 않고 평화적 방법으로 실현하여야\n\n     한다.\n\n 셋째, ‌사상과 이념·제도의 차이를 초월하여 하나\n\n    의 민족으로서 민족적 대단결을 도모하여야\n\n     한다.\n\n\n                                      (                        )","image":"assets/questions/ebs-19-04.webp","answer":"7·4\t남북\t공동\t성명","explanation":"해설\t|\t외세의 간섭을 받지 않고 자주적으로 해결하여야 \n한다는 점, 평화적 방법으로 실현하여야 한다는 점, 민\n족적 대단결을 도모하여야 한다는 점 등을 통해 자료는 \n1972년에 발표된 7·4 남북 공동 성명임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":56,"printedPage":55,"answerPage":58},{"id":"ebs-19-05","unit":19,"number":5,"type":"choice","title":"5. 다음 내용이 포함된 합의서가 발표된 시기를 연표에서 ","text":"5. 다음 내용이 포함된 합의서가 발표된 시기를 연표에서\n옳게 고른 것은?\n\n\n 방문단은 쌍방 적십자사 중앙 기관 책임자를 단장\n\n 으로 하여 이산가족 고향 방문단, 예술 공연단, 취\n\n 재 기자, 지원 인원으로 구성한다. 이산가족 고향\n\n 방문단은 서울과 평양을 고향으로 한 인원을 위주\n\n 로 하여 50명으로 한다. 교환 방문 시기는 9월 20\n\n 일∼9월 23일(3박 4일)로 한다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n   4·19    5·18  노태우  김영삼  김대중  노무현\n  혁명   민주화   정부   정부   정부   정부\n       운동   출범   출범   출범   출범\n\n① (가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-19-05.webp","answer":"②","explanation":"해설\t|\t자료에서 쌍방 적십자사 중앙 기관 책임자를 단장\n으로 하여 이산가족 고향 방문단, 예술 공연단 등으로 방\n문단을 구성한다는 점, 방문단 인원은 50명이며, 9월 20\n일~9월 23일에 진행된다는 점 등을 통해 전두환 정부 시\n기인 1985년에 발표된 남북 이산가족 고향 방문 및 예술 \n공연단 교환 방문에 관한 합의서임을 알 수 있다. 5·18 \n민주화 운동은 1980년, 노태우 정부 출범은 1988년에 해\n당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":57,"printedPage":56,"answerPage":58},{"id":"ebs-19-06","unit":19,"number":6,"type":"choice","title":"6. 밑줄 친 ‘합의’를 이룬 정부 시기에 있었던 사실로 옳은 ","text":"6. 밑줄 친 ‘합의’를 이룬 정부 시기에 있었던 사실로 옳은\n것은?\n\n\n 남과 북은 분단된 조국의 평화적 통일을 염원하는\n\n 온 겨레의 뜻에 따라, 7·4 남북 공동 성명에서 천\n\n 명된 조국 통일 3대 원칙을 재확인하고, …… 다각\n\n 적인 교류·협력을 실현하여 민족 공동의 이익과\n\n 번영을 도모하며, …… 평화 통일을 성취하기 위한\n\n 공동의 노력을 경주할 것을 다짐하면서 다음과 같\n\n 이 합의하였다.\n\n 제1조 남과 북은 서로 상대방의 체제를 인정하고\n\n     존중한다.\n\n\n① 신간회가 결성되었다.\n\n② 정전 협정이 체결되었다.\n\n③ 위화도 회군이 단행되었다.\n\n④ 좌우 합작 7원칙이 발표되었다.\n\n⑤ 남과 북이 유엔에 동시 가입하였다.","image":"assets/questions/ebs-19-06.webp","answer":"⑤","explanation":"해설\t|\t자료에서 7·4 남북 공동 성명의 조국 통일 3대 원\n칙을 재확인하였다는 점, 남과 북은 서로 상대방의 체제\n를 인정하고 존중한다는 내용 등을 통해 밑줄 친 ‘합의’는 \n노태우 정부 시기인 1991년에 발표된 남북 기본 합의서임\n을 알 수 있다. 노태우 정부 시기인 1991년에 남과 북은 \n유엔에 동시 가입하였다.\n오답\t피하기\t|\t① 일제 강점기, ② 이승만 정부 시기, ③ 고\n려 말, ④ 미군정기에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":57,"printedPage":56,"answerPage":58},{"id":"ebs-19-07","unit":19,"number":7,"type":"choice","title":"7. 다음 선언이 발표된 이후 남북 관계로 옳은 것은?","text":"7. 다음 선언이 발표된 이후 남북 관계로 옳은 것은?\n\n\n  1. ‌남과 북은 나라의 통일 문제를 그 주인인 우리\n\n  민족끼리 힘을 합쳐 자주적으로 해결해 나가기\n\n  로 하였다.\n\n  2. ‌남과 북은 나라의 통일을 위한 남측의 연합제 안\n\n  과 북측의 낮은 단계의 연방제 안이 서로 공통\n\n  성이 있다고 인정하고 앞으로 이 방향에서 통일\n\n  을 지향시켜 나가기로 하였다.\n\n\n① 개성 공단 사업이 이루어졌다.\n\n② 남북 기본 합의서가 채택되었다.\n\n③ 남북이 유엔에 동시 가입하였다.\n\n④ 7·4 남북 공동 성명이 발표되었다.\n\n⑤ 이산가족 고향 방문이 처음 실시되었다.","image":"assets/questions/ebs-19-07.webp","answer":"①","explanation":"해설\t|\t자료는 김대중 정부 시기인 2000년에 제1차 남북 \n정상 회담에서 발표된 6·15 남북 공동 선언이다. 6·15 \n남북 공동 선언 이후인 노무현 정부 시기에 개성 공단 사\n업이 활발히 이루어졌다. \n오답\t피하기\t|\t② 남북 기본 합의서는 노태우 정부 시기에 \n채택되었다. ③ 노태우 정부 시기인 1991년 남북이 유엔\n에 동시 가입하였다. ④ 7·4 남북 공동 성명은 1972년에 \n발표되었다. ⑤ 이산가족 고향 방문은 전두환 정부 시기\n에 처음 이루어졌다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":57,"printedPage":56,"answerPage":58},{"id":"ebs-19-08","unit":19,"number":8,"type":"short","title":"8. 다음 선언을 발표한 정부는 무엇인지 쓰시오.","text":"8. 다음 선언을 발표한 정부는 무엇인지 쓰시오.\n\n\n           <10·4 남북 공동 선언>\n\n  1. 6·15 공동 선언을 적극 구현해 나간다.\n\n  4. ‌현 정전 체제를 종식시키고 항구적인 평화 체제\n\n  를 구축하기 위한 종전 선언을 협력해 추진하기\n\n  로 하였다.\n\n  5. 경제 협력 사업을 적극 활성화하기로 하였다.\n\n •서해 평화 협력 특별 지대를 설치하여 공동 어로\n\n  구역과 평화 수역 설정, 민간 선박의 해주 직항\n\n  로 통과, 한강 하구 공동 이용 등을 추진해 나가\n\n  기로 하였다.\n\n\n                                      (                        )","image":"assets/questions/ebs-19-08.webp","answer":"노무현\t정부","explanation":"해설\t|\t자료에서 10·4 남북 공동 성명이라는 점, 6·15 공\n동 선언을 적극 구현한다는 점 등을 통해 노무현 정부 시\n기에 발표된 것임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":57,"printedPage":56,"answerPage":58},{"id":"blank-19","unit":19,"number":9,"type":"blank","title":"1972년 7·4 남북 공동 성명이 제시한 통일 원칙은 자주·평화·____이다.","text":"1972년 7·4 남북 공동 성명이 제시한 통일 원칙은 자주·평화·____이다.","answer":"민족 대단결","explanation":"사상과 이념, 제도의 차이를 넘어 민족의 단결을 도모한다는 원칙이다.","criteria":[],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":92},{"id":"essay-19","unit":19,"number":10,"type":"essay","title":"7·4 남북 공동 성명과 남북 기본 합의서의 발표 시기 및 핵심 내용을 비교하시오.","text":"7·4 남북 공동 성명과 남북 기본 합의서의 발표 시기 및 핵심 내용을 비교하시오.","answer":"1972년 7·4 남북 공동 성명은 자주·평화·민족 대단결이라는 통일 3원칙을 제시했다. 1991년 남북 기본 합의서는 서로의 체제를 인정·존중하고 화해·불가침·교류 협력을 추진하기로 한 합의였다.","explanation":"1972년 7·4 남북 공동 성명은 자주·평화·민족 대단결이라는 통일 3원칙을 제시했다. 1991년 남북 기본 합의서는 서로의 체제를 인정·존중하고 화해·불가침·교류 협력을 추진하기로 한 합의였다.","criteria":["1972년 공동 성명과 통일 3원칙","1991년 남북 기본 합의서","상호 체제 존중·화해·불가침·교류 협력"],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":92},{"id":"ebs-20-01","unit":20,"number":1,"type":"choice","title":"1. (가)에 들어갈 내용으로 옳은 것은?","text":"1. (가)에 들어갈 내용으로 옳은 것은?\n\n\n                      [수행 평가 활동지]\n\n     우리 고유의 영토,      (가)\n\n <수집 자료>\n\n •연합국 최고 사령관 각서[SCAPIN] 제677호에\n\n  따른 부속 지도\n\n •연합국 최고 사령관 각서 제1033호\n\n\n\n\n① 독도     ② 간도     ③ 청산리\n\n④ 봉오동    ⑤ 연해주","image":"assets/questions/ebs-20-01.webp","answer":"①","explanation":"해설\t| 자료에서 우리 고유의 영토라는 점, 연합국 최고 사\n령관 각서[SCAPIN] 제677호에 따른 부속 지도 및 연합국 \n최고 사령관 각서 제1033호가 수집 자료라는 점 등을 통\n해 (가)에는 독도가 들어가야 한다는 것을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":59,"printedPage":58,"answerPage":61},{"id":"ebs-20-02","unit":20,"number":2,"type":"choice","title":"2. 밑줄 친 ‘발표’가 있었던 시기를 연표에서 옳게 고른 것","text":"2. 밑줄 친 ‘발표’가 있었던 시기를 연표에서 옳게 고른 것\n은?\n\n\n ◯◯◯ 정부는 ‘인접 해양에 관한 주권 선언’, 이른\n\n 바 평화선 선언을 발표하여 독도가 우리 영토임을\n\n 분명히 하였다.\n\n\n      (가)    (나)    (다)    (라)    (마)\n\n  8·15  대한민국   4·19    5·18    6월   한일\n  광복  정부 수립  혁명   민주화 민주 항쟁  월드컵\n                 운동       대회 개최\n\n① (가)  ② (나)  ③ (다)  ④ (라)  ⑤ (마)","image":"assets/questions/ebs-20-02.webp","answer":"②","explanation":"해설\t|\t자료에서 이른바 평화선 선언을 발표하였다는 점, \n이를 통해 독도가 우리 영토임을 분명히 하였다는 점 등\n을 통해 밑줄 친 ‘발표’는 이승만 정부 시기인 1952년에 있\n었던 사실임을 알 수 있다. 대한민국 정부 수립은 1948년, \n4·19 혁명은 1960년에 해당한다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":59,"printedPage":58,"answerPage":61},{"id":"ebs-20-03","unit":20,"number":3,"type":"choice","title":"3. (가)에 해당하는 국가로 옳은 것은?","text":"3. (가)에 해당하는 국가로 옳은 것은?\n\n 독도는 지리적·국제법    맞아. 하지만     (가)    이/가\n 적·역사적으로 우리 고   자국의 영토라며 억지 주장을 펼\n 유의 영토야.          치면서, 갈등을 일으키고 있어.\n\n\n\n\n\n① 미국     ② 중국     ③ 일본\n\n④ 영국     ⑤ 러시아","image":"assets/questions/ebs-20-03.webp","answer":"③","explanation":"해설\t|\t자료에서 독도에 대해 이야기하고 있다는 점, 독도\n는 지리적·국제법적·역사적으로 우리 고유의 영토라는 \n점, 자국의 영토라며 억지 주장을 펼치면서 갈등을 일으\n키고 있다는 점 등을 통해 (가) 국가는 일본임을 알 수 있\n다. 일본은 독도 영유권을 주장하는 등 주변국과 갈등을 \n일으키고 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":59,"printedPage":58,"answerPage":61},{"id":"ebs-20-04","unit":20,"number":4,"type":"short","title":"4. (가)에 들어갈 내용을 쓰시오.","text":"4. (가)에 들어갈 내용을 쓰시오.\n\n\n       (가)  신사에는 아시아·태평양 전쟁의 A급\n\n 전범으로 분류된 사람들의 위패가 보관되어 있다.\n\n 따라서      (가)   신사를 참배한다는 것은 과거\n\n 의 침략 전쟁의 잘못을 반성하지 않는다는 의미로\n\n 해석될 수 있어서 주변국의 비판을 받고 있다.\n\n\n\n                                      (                        )","image":"assets/questions/ebs-20-04.webp","answer":"야스쿠니","explanation":"해설\t|\t자료에서 아시아·태평양 전쟁의 A급 전범으로 분\n류된 사람들의 위패가 보관되어 있다는 점, (가) 신사를 \n참배한다는 것은 과거 침략 전쟁의 잘못을 반성하지 않는\n다는 의미로 해석될 수 있어서 주변국의 비판을 받고 있\n다는 점 등을 통해 (가)에는 ‘야스쿠니’가 들어가야 한다는 \n것을 알 수 있다. 일본 정치인들의 야스쿠니 신사 참배는 \n침략 전쟁 당시 자행하였던 비인도적인 행위를 반성하지 \n않는 것으로 여겨져 주변국과 갈등을 빚고 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":59,"printedPage":58,"answerPage":61},{"id":"ebs-20-05","unit":20,"number":5,"type":"choice","title":"5. (가)에 들어갈 내용으로 가장 적절한 것은?","text":"5. (가)에 들어갈 내용으로 가장 적절한 것은?\n\n\n일본의 나가사키   원래 섬의 명칭은\n 현에 있는 군함도   하시마인데, 섬이\n                                               (가)\n 는 어떤 곳인지   군함 모양처럼 생겨\n 이야기해보자.    서 군함도라 불려.\n\n\n\n\n\n① 한국인이 강제 징용된 곳이야.\n\n② 강주룡이 고공 농성을 벌인 곳이야.\n\n③ 대한민국 임시 정부가 수립된 곳이야.\n\n④ 이순신의 수군이 일본군을 격퇴한 곳이야.\n\n⑤ 한국인 유학생이 2·8 독립 선언을 발표한 곳이야.","image":"assets/questions/ebs-20-05.webp","answer":"①","explanation":"해설\t|\t자료는 일본의 나가사키현에 있는 군함도에 대해 \n학생들이 대화하고 있는 장면이다. 따라서 (가)에는 군함\n도와 관련된 내용이 들어가는 것이 가장 적절하다는 것을 \n알 수 있다. 군함도는 일제 강점기에 많은 한국인들이 강\n제 징용된 곳이다.\n오답\t피하기\t|\t② 일제 강점기 강주룡은 평양의 을밀대 지\n붕 위에서 고공 농성을 벌였다. ③ 3·1 운동 이후 상하이\n에서 대한민국 임시 정부가 수립되었다. ④ 임진왜란 당\n시 이순신이 이끄는 수군은 한산도 등지에서 일본군을 격\n퇴하였다. ⑤ 1919년 일본 도쿄에서 한국인 유학생들이 \n2·8 독립 선언을 발표하였다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":60,"printedPage":59,"answerPage":61},{"id":"ebs-20-06","unit":20,"number":6,"type":"short","title":"6. (가) 사업은 무엇인지 명칭을 쓰시오.","text":"6. (가) 사업은 무엇인지 명칭을 쓰시오.\n\n\n 중국은 조선족을 비롯한 중국 내 수많은 소수 민족\n\n 을 통합시킬 논리를 필요로 하였다. 이에 중국은\n\n ‘통일적 다민족 국가론’을 내세워 중국 내의 모든\n\n 민족이 중화 민족이고, 따라서 그들의 역사도 중국\n\n 의 역사라는 논리를 펴고 있다.      (가)   은/는\n\n 이러한 논리를 바탕으로 진행된 국가 사업으로, 고\n\n 조선·부여·고구려는 고대 중국 왕조의 지방 정권\n\n 이므로 중국사에 편입시켜야 한다고 주장하여 중국\n\n 과 한국 간 갈등을 유발하였다.\n\n\n                                      (                        )","image":"assets/questions/ebs-20-06.webp","answer":"동북공정","explanation":"해설\t|\t자료에서 중국이 ‘통일적 다민족 국가론’을 내세워 \n중국 내의 모든 민족이 중화 민족이고, 그들의 역사도 중\n국의 역사라는 논리를 펼치고 있다는 점, 고조선·부여·\n고구려는 고대 중국 왕조의 지방 정권이므로 중국사에 편\n입시켜야 한다고 주장한다는 점 등을 통해 (가) 사업은 동\n북공정임을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":60,"printedPage":59,"answerPage":61},{"id":"ebs-20-07","unit":20,"number":7,"type":"choice","title":"7. (가)에 들어갈 지명으로 옳은 것은?","text":"7. (가)에 들어갈 지명으로 옳은 것은?\n\n\n       (가)    은/는 일본이 청일 전쟁에서 승리한\n\n 이후 이곳을 차지하여 오늘날까지 영유권을 유지하\n\n 고 있다. 반면 중국은 청일 전쟁으로 강제 할양된\n\n 것이므로 되찾아야 한다고 주장하고 있다.\n\n\n① 쓰시마\n\n② 하와이\n\n③ 오키나와 제도\n\n④ 쿠릴 열도(북방 4도)\n\n⑤ 센카쿠 열도(댜오위다오)","image":"assets/questions/ebs-20-07.webp","answer":"⑤","explanation":"해설\t|\t자료에서 일본이 청일 전쟁에서 승리한 이후 오늘\n날까지 영유권을 유지하고 있다는 점, 중국은 청일 전쟁\n으로 강제 할양된 것이므로 되찾아야 한다고 주장하고 있\n다는 점 등을 통해 (가)에는 센카쿠 열도(댜오위다오)가 \n들어가야 한다는 것을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":60,"printedPage":59,"answerPage":61},{"id":"ebs-20-08","unit":20,"number":8,"type":"choice","title":"8. 밑줄 친 ‘다양한 노력’에 해당하는 내용으로 옳은 것은?","text":"8. 밑줄 친 ‘다양한 노력’에 해당하는 내용으로 옳은 것은?\n\n\n 20세기에 있었던 침략과 전쟁, 식민 지배 등으로\n\n 인해 오늘날 한국과 중국, 일본은 역사 갈등을 겪\n\n 고 있다. 이러한 갈등을 풀고 평화를 실현하기 위\n\n 해서는 다양한 노력이 필요하다.\n\n\n① 민족 유일당 운동으로 신간회 창립\n\n② 연합 작전을 위한 조명 연합군 결성\n\n③ 미곡 공출 등 국가 총동원 체제 구축\n\n④ 공동 역사 연구를 통한 역사 교재 제작\n\n⑤ 대일 항전을 위한 대일 선전 성명서 발표","image":"assets/questions/ebs-20-08.webp","answer":"④","explanation":"해설\t|\t자료에서 동아시아 역사 갈등을 풀기 위한 것이라\n는 점 등을 통해 밑줄 친 ‘다양한 노력’에는 공동 역사 연\n구를 통한 역사 교재 제작이 해당한다는 것을 알 수 있다.","source":"EBSi 문제","sourceBook":"최소성취수준보장지도_한국사2_학습지(통합본).pdf","sourcePage":60,"printedPage":59,"answerPage":61},{"id":"blank-20","unit":20,"number":9,"type":"blank","title":"2002년부터 중국이 추진하여 고구려·발해 등의 역사 해석을 둘러싼 갈등을 일으킨 사업은 ____이다.","text":"2002년부터 중국이 추진하여 고구려·발해 등의 역사 해석을 둘러싼 갈등을 일으킨 사업은 ____이다.","answer":"동북공정","explanation":"동북 지역의 역사를 연구한다는 명목 아래 한국 고대사의 귀속을 둘러싼 문제가 제기되었다.","criteria":[],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":97},{"id":"essay-20","unit":20,"number":10,"type":"essay","title":"동아시아의 역사 갈등 사례 한 가지와 이를 평화적으로 해결하기 위한 방법 두 가지를 제안하시오.","text":"동아시아의 역사 갈등 사례 한 가지와 이를 평화적으로 해결하기 위한 방법 두 가지를 제안하시오.","answer":"중국의 동북공정이나 일본 일부 교과서의 침략 역사 축소 등이 역사 갈등의 사례이다. 관련국 연구자들이 사료에 근거한 공동 연구와 교재 집필을 진행하고, 청소년·시민 교류를 통해 피해자의 경험과 서로의 인식을 이해하며 대화를 이어갈 수 있다.","explanation":"중국의 동북공정이나 일본 일부 교과서의 침략 역사 축소 등이 역사 갈등의 사례이다. 관련국 연구자들이 사료에 근거한 공동 연구와 교재 집필을 진행하고, 청소년·시민 교류를 통해 피해자의 경험과 서로의 인식을 이해하며 대화를 이어갈 수 있다.","criteria":["구체적인 역사 갈등 사례","사료에 근거한 공동 역사 연구","청소년·시민 교류와 피해자 존중"],"source":"자체 제작","sourceBook":"EBSi 한국사2 자료 참고 · 자체 작성","sourcePage":97}],"groups":["일제 식민 통치와 민족운동","대한민국의 발전","오늘날의 대한민국"],"version":1};
